            // Ships & Vessels button → Manage row
            const btnShips = document.createElement('button');
            btnShips.className = 'btn-action';
            btnShips.id = 'btnShips';
            btnShips.title = 'Ships & Vessels';
            btnShips.textContent = '⛵ Ships';
