    // ── EVENT LOG ──

    function inferCategoryFromMessage(event) {
        var m = ((event.message || event.description || '') + ' ' + ((event.details && event.details.type) || '')).toLowerCase();
        if (m.includes('war') || m.includes('army') || m.includes('siege') || m.includes('battle')) return 'military';
        if (m.includes('plague') || m.includes('illness') || m.includes('infected') || m.includes('quarantine') || m.includes('sick') || m.includes('disease') || m.includes('died of') || m.includes('health policy') || m.includes('epidemic')) return 'illness';
        if (m.includes('trade') || m.includes('sold') || m.includes('bought')) return 'my_actions';
        if (m.includes('caravan') || m.includes('warehouse') || m.includes('building')) return 'my_business';
        if (m.includes('fire') || m.includes('flood')) return 'local_town';
        if (m.includes('law') || m.includes('tax') || m.includes('festival') || m.includes('king')) return 'my_kingdom';
        if (m.includes('pirate') || m.includes('bandit') || m.includes('ambush')) return 'combat';
        if (m.includes('elite merchant') || m.includes('married') || m.includes('retired')) return 'npc_activity';
        return 'local_town';
    }

    function openEventLog() {
        if (typeof Player !== 'undefined' && Player.state && Player.state.storyMode) {
            Player.state.storyMode._viewedEventLog = true;
            if (typeof StoryMode !== 'undefined' && StoryMode.tick) StoryMode.tick(Player.state);
        }
        let events;
        try { events = (Engine.getAllEvents ? Engine.getAllEvents() : Engine.getEvents()); } catch (e) { events = []; }

        // Mark all events as read and force-clear badge immediately
        _lastSeenEventCount = events ? events.length : 0;
        if (el.notifCount) {
            el.notifCount.textContent = '0';
            el.notifCount.classList.add('hidden');
        }

        if (!events || !events.length) {
            openModal('📋 Event Log', '<div class="text-dim text-center">No events yet.</div>');
            return;
        }

        const tradeLog = Player.tradeLog || [];

        // Pagination and search state
        if (typeof openEventLog._currentPage !== 'number') openEventLog._currentPage = 0;
        if (typeof openEventLog._searchQuery !== 'string') openEventLog._searchQuery = '';
        var currentPage = openEventLog._currentPage;
        var searchQuery = openEventLog._searchQuery.toLowerCase().trim();

        // Category tab groups
        var tabGroups = {
            all:      { label: '📋 All',      categories: null },
            personal: { label: '🧑 Personal', categories: ['my_actions', 'my_business', 'travel_events', 'combat'] },
            local:    { label: '🏘️ Local',    categories: ['local_town', 'npc_activity', 'illness'] },
            world:    { label: '🌍 World',     categories: ['my_kingdom', 'foreign_kingdoms', 'world_economy', 'military', 'political_intrigue'] },
        };
        if (!openEventLog._activeTab) openEventLog._activeTab = 'all';
        var activeTab = openEventLog._activeTab;

        var tabBarHtml = '<div style="display:flex;gap:4px;margin-bottom:8px;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:6px;">';
        for (var tabKey in tabGroups) {
            if (tabGroups.hasOwnProperty(tabKey)) {
                var tg = tabGroups[tabKey];
                var isActive = (tabKey === activeTab);
                tabBarHtml += '<button class="btn-medieval" style="font-size:0.78rem;padding:4px 10px;' +
                    (isActive ? 'background:rgba(255,215,0,0.2);border-color:var(--gold);color:var(--gold);' : 'opacity:0.6;') +
                    '" data-action="_setEventTab" data-tab="' + tabKey + '">' + tg.label + '</button>';
            }
        }
        tabBarHtml += '</div>';

        // Build filter bar (only show when on "all" tab)
        var filterBarHtml = '';
        if (activeTab === 'all') {
            filterBarHtml = '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:8px;">';
            var filterLabels = {
                my_actions: '🎯 My Actions',
                my_business: '💼 Business',
                my_kingdom: '👑 Kingdom',
                local_town: '🏘️ Local',
                foreign_kingdoms: '🌍 Foreign',
                world_economy: '📈 Economy',
                military: '⚔️ Military',
                npc_activity: '👥 NPCs',
                travel_events: '🚶 Travel',
                illness: '🦠 Illness',
                combat: '☠️ Combat',
                political_intrigue: '🕵️ Intrigue',
                error_alerts: '🐛 Debug',
            };
            var filters = (typeof Player !== 'undefined' && Player.getNotificationFilters) ? Player.getNotificationFilters() : {};
            for (var fKey in filterLabels) {
                if (filterLabels.hasOwnProperty(fKey)) {
                    var fLabel = filterLabels[fKey];
                    var isOn = filters[fKey] === true || filters[fKey] === 'smart';
                    var isSmart = filters[fKey] === 'smart';
                    filterBarHtml += '<button class="btn-medieval" style="font-size:0.7rem;padding:2px 6px;opacity:' + (isOn ? 1 : 0.4) + ';' + (isSmart ? 'border:1px solid gold;' : '') + '" data-action="toggleNotifFilter" data-id="' + fKey + '">' + fLabel + '</button>';
                }
            }
            filterBarHtml += '</div>';
        }

        let html = tabBarHtml + filterBarHtml;

        // Search bar
        var escapedQuery = openEventLog._searchQuery.replace(/'/g, "\\'").replace(/"/g, '&quot;');
        html += '<div style="margin-bottom:8px;"><input type="text" id="eventLogSearch" value="' + escapedQuery + '" placeholder="🔍 Search events..." style="width:100%;padding:6px 10px;background:rgba(0,0,0,0.3);border:1px solid rgba(255,255,255,0.15);border-radius:4px;color:var(--text-color);font-size:0.85rem;" oninput="UI._searchEventLog(this.value)" /></div>';

        html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';

        // Combine engine events and trade log, sort by day descending
        const allEvents = [
            ...events.map(e => ({ ...e, source: 'world' })),
            ...tradeLog.map((t, i) => ({
                day: t.day || 0,
                type: 'trade',
                description: t.description || `Trade #${i + 1}`,
                source: 'trade'
            }))
        ].sort((a, b) => (b.day || 0) - (a.day || 0));

        // Filter events based on active tab
        var activeCats = (tabGroups[activeTab] && tabGroups[activeTab].categories) ? tabGroups[activeTab].categories : null;

        var filteredEvents = allEvents.filter(function(e) {
            var cat = e.category || inferCategoryFromMessage(e);
            // v9p33river369: local_town events only show if player is in that town
            if (cat === 'local_town' && e.townId) {
                var _pTown = (typeof Player !== 'undefined' && Player.state) ? Player.state.townId : null;
                if (_pTown && e.townId !== _pTown) return false;
            }
            // Tab filter
            if (activeCats && !activeCats.includes(cat)) return false;
            // In "all" tab, use user's notification filter preferences (but NOT the day-suppress or skill-gate)
            if (activeTab === 'all' && typeof Player !== 'undefined' && Player.getNotificationFilters) {
                var filters = Player.getNotificationFilters();
                if (filters) {
                    var filterKey = cat;
                    // If filter explicitly set to false (not just missing), hide it
                    if (filters.hasOwnProperty(filterKey) && filters[filterKey] === false) return false;
                }
            }
            return true;
        });

        // Cap at 1000 events total
        if (filteredEvents.length > 1000) filteredEvents = filteredEvents.slice(0, 1000);

        // Apply search filter
        if (searchQuery) {
            filteredEvents = filteredEvents.filter(function(e) {
                var text = (e.description || e.message || e.type || '').toLowerCase();
                return text.indexOf(searchQuery) !== -1;
            });
        }

        var totalEvents = filteredEvents.length;
        var eventsPerPage = 100;
        var totalPages = Math.max(1, Math.ceil(totalEvents / eventsPerPage));
        if (currentPage >= totalPages) currentPage = totalPages - 1;
        if (currentPage < 0) currentPage = 0;
        openEventLog._currentPage = currentPage;

        var pageStart = currentPage * eventsPerPage;
        var pageEnd = Math.min(pageStart + eventsPerPage, totalEvents);
        var pageEvents = filteredEvents.slice(pageStart, pageEnd);

        // Event count and clear button
        var countLabel = searchQuery ? (totalEvents + ' results') : (totalEvents + ' events');
        if (totalPages > 1) countLabel += ' (page ' + (currentPage + 1) + '/' + totalPages + ')';
        html += '<span style="font-size:0.85rem;color:var(--text-muted);">' + countLabel + '</span>' +
            '<button class="btn-medieval" data-action="clearEventLog" style="font-size:0.8rem;padding:4px 10px;">🗑️ Clear Log</button>' +
            '</div>';

        // Pagination controls at top
        if (totalPages > 1) {
            html += '<div style="display:flex;justify-content:center;gap:6px;margin-bottom:8px;">';
            html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 10px;' + (currentPage === 0 ? 'opacity:0.3;pointer-events:none;' : '') + '" data-action="_setEventPage" data-page="' + (currentPage - 1) + '">◀ Prev</button>';
            // Page number buttons (show up to 5 around current page)
            var startPage = Math.max(0, currentPage - 2);
            var endPage = Math.min(totalPages - 1, startPage + 4);
            if (endPage - startPage < 4) startPage = Math.max(0, endPage - 4);
            for (var pi = startPage; pi <= endPage; pi++) {
                html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 8px;min-width:28px;' + (pi === currentPage ? 'background:rgba(255,215,0,0.25);border-color:var(--gold);color:var(--gold);' : 'opacity:0.6;') + '" data-action="_setEventPage" data-page="' + pi + '">' + (pi + 1) + '</button>';
            }
            html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 10px;' + (currentPage >= totalPages - 1 ? 'opacity:0.3;pointer-events:none;' : '') + '" data-action="_setEventPage" data-page="' + (currentPage + 1) + '">Next ▶</button>';
            html += '</div>';
        }

        html += '<div class="event-log-list">';

        // Store events for detail lookup (full filtered set, not just current page)
        openEventLog._cachedEvents = filteredEvents;

        // Group stackable events (refugees, migrations, similar types within 3 days)
        var stackableTypes = { 'refugees': '🏃 Refugee Movements', 'migration': '🏃 Migration Events', 'npc_death': '💀 Deaths', 'npc_birth': '👶 Births' };
        var displayItems = []; // { type: 'single'|'group', event, events, groupLabel, indices }
        var i = 0;
        while (i < pageEvents.length) {
            var ev = pageEvents[i];
            var evType = ev.details && ev.details.type ? ev.details.type : null;
            if (evType && stackableTypes[evType]) {
                // Collect consecutive events of this type within 3 days
                var group = [{ event: ev, idx: pageStart + i }];
                var j = i + 1;
                while (j < pageEvents.length && j < i + 20) {
                    var next = pageEvents[j];
                    var nextType = next.details && next.details.type ? next.details.type : null;
                    if (nextType === evType && Math.abs((next.day || 0) - (ev.day || 0)) <= 3) {
                        group.push({ event: next, idx: pageStart + j });
                        j++;
                    } else {
                        break;
                    }
                }
                if (group.length >= 2) {
                    displayItems.push({ type: 'group', events: group, groupLabel: stackableTypes[evType], groupType: evType, dayStart: ev.day });
                    i = j;
                } else {
                    displayItems.push({ type: 'single', event: ev, idx: pageStart + i });
                    i++;
                }
            } else {
                displayItems.push({ type: 'single', event: ev, idx: pageStart + i });
                i++;
            }
        }

        for (var di = 0; di < displayItems.length; di++) {
            var item = displayItems[di];
            if (item.type === 'group') {
                // Collapsed group header
                var groupId = 'evGroup_' + di;
                html += '<div class="event-log-item event-personal" style="cursor:pointer;border-left:3px solid #c4a35a;" data-action="_toggleVisibility" data-id="' + groupId + '">';
                html += '<span class="event-day">Day ' + (item.dayStart || '?') + '</span>';
                html += '<span class="event-text">' + item.groupLabel + ' (' + item.events.length + ' events) ▸</span>';
                html += '</div>';
                html += '<div id="' + groupId + '" style="display:none;margin-left:12px;border-left:2px solid #555;padding-left:6px;">';
                for (var gi = 0; gi < item.events.length; gi++) {
                    var ge = item.events[gi];
                    var clickAct = 'data-action="showEventDetail" data-id="' + ge.idx + '"';
                    html += '<div class="event-log-item event-personal" ' + clickAct + ' style="cursor:pointer;padding:3px 6px;font-size:0.78rem;">';
                    html += '<span class="event-day">Day ' + (ge.event.day || '?') + '</span>';
                    html += '<span class="event-text">' + (ge.event.description || ge.event.message || 'Event') + '</span>';
                    html += (ge.event.details ? '<span style="float:right;opacity:0.5;">ℹ️</span>' : '') + '</div>';
                }
                html += '</div>';
            } else {
                var event = item.event;
                var evIdx = item.idx;
                var type = (event.type || event.message || '').toLowerCase();
                var eventClass = 'event-world';
                if (type.includes('war') || type.includes('plague') || type.includes('assassin') || type.includes('bandit') ||
                    type.includes('collapse') || type.includes('bankrupt')) {
                    eventClass = 'event-war';
                } else if (type.includes('flood') || type.includes('fire') || type.includes('blight') ||
                           type.includes('mine collapse') || type.includes('embargo') || type.includes('disaster')) {
                    eventClass = 'event-war';
                } else if (type.includes('trade') || type.includes('festival') || type.includes('bountiful') ||
                           type.includes('discovery') || type.includes('prospector')) {
                    eventClass = 'event-trade';
                } else if (type.includes('personal') || type.includes('hire') || type.includes('build') ||
                           type.includes('refugee') || type.includes('migrat')) {
                    eventClass = 'event-personal';
                }

                var clickAction = 'data-action="showEventDetail" data-id="' + evIdx + '"';

                html += '<div class="event-log-item ' + eventClass + '" ' + clickAction + ' style="cursor:pointer;">' +
                    '<span class="event-day">Day ' + (event.day || '?') + '</span>' +
                    '<span class="event-text">' + (event.description || event.message || type || 'Event') + '</span>' +
                    (event.details ? '<span class="event-detail-icon" style="float:right;opacity:0.5;">ℹ️</span>' : '') +
                    '</div>';
            }
        }

        html += '</div>';

        // Pagination controls at bottom
        if (totalPages > 1) {
            html += '<div style="display:flex;justify-content:center;gap:6px;margin-top:8px;">';
            html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 10px;' + (currentPage === 0 ? 'opacity:0.3;pointer-events:none;' : '') + '" data-action="_setEventPage" data-page="' + (currentPage - 1) + '">◀ Prev</button>';
            var startPage2 = Math.max(0, currentPage - 2);
            var endPage2 = Math.min(totalPages - 1, startPage2 + 4);
            if (endPage2 - startPage2 < 4) startPage2 = Math.max(0, endPage2 - 4);
            for (var pi2 = startPage2; pi2 <= endPage2; pi2++) {
                html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 8px;min-width:28px;' + (pi2 === currentPage ? 'background:rgba(255,215,0,0.25);border-color:var(--gold);color:var(--gold);' : 'opacity:0.6;') + '" data-action="_setEventPage" data-page="' + pi2 + '">' + (pi2 + 1) + '</button>';
            }
            html += '<button class="btn-medieval" style="font-size:0.75rem;padding:3px 10px;' + (currentPage >= totalPages - 1 ? 'opacity:0.3;pointer-events:none;' : '') + '" data-action="_setEventPage" data-page="' + (currentPage + 1) + '">Next ▶</button>';
            html += '</div>';
        }

        openModal('📋 Event Log', html);
        // Restore focus to search input if there was a query
        if (searchQuery) {
            try {
                var searchEl = document.getElementById('eventLogSearch');
                if (searchEl) { searchEl.focus(); searchEl.setSelectionRange(searchEl.value.length, searchEl.value.length); }
            } catch(e) {}
        }
    }

    function _setEventTab(tabKey) {
        openEventLog._activeTab = tabKey;
        openEventLog._currentPage = 0; // reset page on tab change
        openEventLog();
    }

    function _setEventPage(page) {
        openEventLog._currentPage = Math.max(0, page);
        openEventLog();
    }

    var _searchEventDebounce = null;
    function _searchEventLog(query) {
        openEventLog._searchQuery = query || '';
        openEventLog._currentPage = 0; // reset to first page on search
        if (_searchEventDebounce) clearTimeout(_searchEventDebounce);
        _searchEventDebounce = setTimeout(function() { openEventLog(); }, 300);
    }

    function clearEventLog() {
        try {
            var world = Engine.getWorld();
            if (world && world.eventLog) {
                world.eventLog.length = 0;
            }
        } catch (e) {}
        // v9p33river329: Clear Log is for event notifications only; keep Player.tradeLog history intact.
        _lastSeenEventCount = 0;
        // Force badge hidden immediately
        if (el.notifCount) {
            el.notifCount.textContent = '0';
            el.notifCount.classList.add('hidden');
        }
        closeModal();
    }

