                    html += '<button class="btn-medieval" style="font-size:0.65rem;padding:1px 7px;' + (!subOn ? 'background:#c44e52;color:#fff;' : 'opacity:0.4;') + '" data-action="setNotifFilter" data-key="' + subKey + '" data-val="false">Off</button>';
