    function _addTradePresets(containerId, resourceId, type) {
        if (!_isMobileLayout()) return;
        var container = document.getElementById(containerId);
        if (!container) return;
        var presets = [1, 5, 10];
        var html = '<div class="trade-qty-presets">';
        for (var i = 0; i < presets.length; i++) {
            html += '<button data-action="setTradeQty" data-type="' + type + '" data-id="' + resourceId + '" data-qty="' + presets[i] + '">' + presets[i] + '</button>';
        }
        html += '<button data-action="setTradeQty" data-type="' + type + '" data-id="' + resourceId + '" data-qty="max">Max</button>';
        html += '</div>';
        container.insertAdjacentHTML('beforeend', html);
    }

    function updateConditionsIndicator() {
        if (typeof Player === 'undefined') return;
        var injuries = Player.injuries || [];
        var illnesses = Player.illnesses || [];
        var healthGroup = document.getElementById('healthBarGroup');
        if (!healthGroup) return;

        var el2 = document.getElementById('conditionsIndicator');
        if (injuries.length === 0 && illnesses.length === 0) {
            if (el2) el2.style.display = 'none';
            return;
        }

        if (!el2) {
            el2 = document.createElement('div');
            el2.id = 'conditionsIndicator';
            el2.style.cssText = 'padding:2px 6px;font-size:0.72rem;line-height:1.4;cursor:pointer;';
            el2.title = 'Click for health details';
            el2.addEventListener('click', function() { openHealthDetailPanel(); });
            healthGroup.appendChild(el2);
        }
        el2.style.display = '';

        var html2 = '';
        for (var i = 0; i < injuries.length; i++) {
            var inj = injuries[i];
            var sevColor = inj.severity === 'severe' ? '#e74c3c' : inj.severity === 'moderate' ? '#e67e22' : '#8e8';
            var injName = inj.name || 'Injury';
            html2 += '<span data-action="openHealthDetailPanel" style="cursor:pointer;color:' + sevColor + ';margin-right:8px;">🩹 ' + injName + ' <span style="font-size:0.65rem;opacity:0.8;">(' + inj.severity + ')</span></span>';
        }
        for (var j = 0; j < illnesses.length; j++) {
            var ill = illnesses[j];
            var sevColor2 = ill.severity === 'severe' ? '#e74c3c' : ill.severity === 'moderate' ? '#e67e22' : '#8e8';
            var illName = ill.name || (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Illness');
            html2 += '<span data-action="openHealthDetailPanel" style="cursor:pointer;color:' + sevColor2 + ';margin-right:8px;">🤒 ' + illName + ' <span style="font-size:0.65rem;opacity:0.8;">(' + ill.severity + ')</span></span>';
        }
        el2.innerHTML = html2;
    }

    function openHealthDetailPanel() {
        if (typeof Player === 'undefined') return;
        var injuries = Player.injuries || [];
        var illnesses = Player.illnesses || [];
        var injTypes = Player.getInjuryTypes ? Player.getInjuryTypes() : [];
        var illTypes = Player.getIllnessTypes ? Player.getIllnessTypes() : [];
        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        if (injuries.length === 0 && illnesses.length === 0) {
            html += '<p style="color:#8e8;text-align:center;padding:20px;">✅ You are in good health — no injuries or illnesses.</p>';
            var curHp = Player.health != null ? Player.health : 100;
            var maxHp2 = Player.maxHealth || 100;
            if (curHp < maxHp2) {
                html += '<p style="color:#ccc;text-align:center;font-size:0.85rem;">❤️ Health: ' + Math.floor(curHp) + '/' + maxHp2 + ' — Recovers +1/day when energy, hunger, and thirst are all above 80%.</p>';
            }
            // Medical rest option when health < 30
            if (curHp < 30 && !Player.traveling) {
                var _innCost = Player.getLodgingCost ? Player.getLodgingCost('inn_room') : 5;
                var _medCostPerDay = _innCost * 5;
                var _playerGold = Player.gold || 0;
                html += '<div style="background:rgba(200,50,50,0.12);border:1px solid rgba(200,80,80,0.4);border-radius:8px;padding:12px;margin:10px 0;">';
                html += '<h3 style="margin:0 0 6px 0;font-size:0.9rem;color:#e74c3c;">🛏️ Medical Rest</h3>';
                html += '<div style="font-size:0.78rem;color:#ccc;margin-bottom:8px;">Your health is critically low. Extended bed rest at the inn can help you recover (+5 HP/day). Cost: <strong>' + _medCostPerDay + 'g/day</strong> (5× inn rate)</div>';
                var _medDays = [1, 3, 5];
                for (var _mdi = 0; _mdi < _medDays.length; _mdi++) {
                    var _md = _medDays[_mdi];
                    var _mdCost = _medCostPerDay * _md;
                    var _canAfford = _playerGold >= _mdCost;
                    html += '<button class="btn-medieval" data-action="startMedicalRest" data-days="' + _md + '" style="font-size:0.78rem;padding:6px 14px;margin:3px 4px;' + (_canAfford ? '' : 'opacity:0.4;cursor:not-allowed;') + '"' + (_canAfford ? '' : ' disabled') + '>';
                    html += '🛏️ Rest ' + _md + ' day' + (_md > 1 ? 's' : '') + ' — ' + _mdCost + 'g';
                    html += '</button>';
                }
                html += '</div>';
            }
            html += '</div>';
            openModal('🏥 Health Status', html, '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        // Injuries
        for (var i = 0; i < injuries.length; i++) {
            var inj = injuries[i];
            var typeDef = null;
            for (var ti = 0; ti < injTypes.length; ti++) {
                if (injTypes[ti].id === inj.type) { typeDef = injTypes[ti]; break; }
            }
            var sevColor = inj.severity === 'severe' ? '#e74c3c' : inj.severity === 'moderate' ? '#e67e22' : '#2ecc71';
            var injName = inj.name || (typeDef ? typeDef.name : 'Unknown Injury');
            var daysHad = day - (inj.dayOccurred || 0);

            html += '<div style="border:1px solid ' + sevColor + '44;border-radius:8px;padding:10px;margin-bottom:10px;background:rgba(200,50,50,0.06);">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🩹 ' + injName + '</span>';
            html += '<span style="font-weight:bold;color:' + sevColor + ';text-transform:uppercase;font-size:0.85rem;">' + (inj.severity || 'unknown') + '</span>';
            html += '</div>';

            // Status
            html += '<div style="font-size:0.82rem;color:#bbb;margin:6px 0;">';
            html += inj.treated ? '✅ Being treated' : '⚠️ <span style="color:#e67e22;">Untreated</span>';
            html += ' · Day ' + daysHad + ' of injury';
            if (inj.treated && inj.healDay) {
                var daysLeft = Math.max(0, inj.healDay - day);
                html += ' · ~' + daysLeft + ' days to recover';
            }
            html += '</div>';

            // Debuffs
            if (typeDef && typeDef.debuffDesc) {
                html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
                html += '<strong style="color:#e67e22;">⚡ Active Debuffs:</strong> <span style="color:#ddd;">' + typeDef.debuffDesc + '</span>';
                html += '</div>';
            }

            // Risks
            var drainPerDay = inj.severity === 'severe' ? 8 : inj.severity === 'moderate' ? 3 : 1;
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#c44e52;">⚠️ Risks:</strong> <span style="color:#ddd;">';
            html += '❤️ Drains <strong style="color:#e74c3c;">' + drainPerDay + ' health/day</strong>. ';
            if (typeDef && typeDef.deathRisk) {
                html += 'Daily death risk: ' + (typeDef.deathRisk * 100).toFixed(1) + '%. ';
            }
            html += 'Health at 0 = death. ';
            if (inj.severity === 'minor') {
                html += 'Will heal on its own in ' + (typeDef ? (typeDef.healDays * 2) : '10-30') + ' days untreated.';
            } else if (inj.severity === 'moderate') {
                html += 'May worsen to <span style="color:#e74c3c;">severe</span> if untreated for 10+ days. Natural recovery: ' + (typeDef ? (typeDef.healDays * 4) : '30-90') + ' days.';
            } else if (inj.severity === 'severe') {
                html += '<span style="color:#e74c3c;">Can be fatal if untreated for 30+ days.</span> Seek treatment immediately.';
            }
            html += '</span></div>';

            // Treatment options
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(50,100,50,0.15);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#2ecc71;">💊 Treatment Options:</strong><br>';
            html += '<span style="color:#ddd;">';
            html += '🏥 <strong>Hospital</strong> — Treats all severities. Fastest recovery. Requires hospital in town.<br>';
            if (inj.severity !== 'severe') {
                html += '🩺 <strong>Clinic</strong> — Treats minor/moderate. Cheaper than hospital. Requires clinic in town.<br>';
            } else {
                html += '🩺 <strong>Clinic</strong> — <span style="color:#e67e22;">Can treat severe, but takes 2x longer with lower success rate.</span><br>';
            }
            html += '🧑‍⚕️ <strong>Self-treat</strong> — Requires ';
            if (inj.severity === 'minor') html += 'First Aid skill';
            else if (inj.severity === 'moderate') html += 'Field Medic skill';
            else html += 'Doctor skill';
            if (typeDef && typeDef.product) {
                var prodName = typeDef.product.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                html += ' + ' + prodName + ' (' + (typeDef.productCost || '?') + 'g)';
            }
            html += '</span></div>';
            html += '</div>';
        }

        // Illnesses
        for (var k = 0; k < illnesses.length; k++) {
            var ill = illnesses[k];
            var illTypeDef = null;
            for (var ti2 = 0; ti2 < illTypes.length; ti2++) {
                if (illTypes[ti2].id === ill.type) { illTypeDef = illTypes[ti2]; break; }
            }
            var sevColor2 = ill.severity === 'severe' ? '#e74c3c' : ill.severity === 'moderate' ? '#e67e22' : '#2ecc71';
            var illName = ill.name || (illTypeDef ? illTypeDef.name : (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Unknown Illness'));
            var daysIll = day - (ill.dayOccurred || 0);

            html += '<div style="border:1px solid ' + sevColor2 + '44;border-radius:8px;padding:10px;margin-bottom:10px;background:rgba(200,150,50,0.06);">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🤒 ' + illName + '</span>';
            html += '<span style="font-weight:bold;color:' + sevColor2 + ';text-transform:uppercase;font-size:0.85rem;">' + (ill.severity || 'unknown') + '</span>';
            html += '</div>';

            // Status
            html += '<div style="font-size:0.82rem;color:#bbb;margin:6px 0;">';
            html += ill.treated ? '✅ Being treated' : '⚠️ <span style="color:#e67e22;">Untreated</span>';
            html += ' · Day ' + daysIll + ' of illness';
            if (ill.treated && ill.healDay) {
                var daysLeft2 = Math.max(0, ill.healDay - day);
                html += ' · ~' + daysLeft2 + ' days to recover';
            }
            html += '</div>';

            // Debuffs
            if (illTypeDef && illTypeDef.debuffDesc) {
                html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
                html += '<strong style="color:#e67e22;">⚡ Active Debuffs:</strong> <span style="color:#ddd;">' + illTypeDef.debuffDesc + '</span>';
                html += '</div>';
            }

            // Risks
            var drainPerDay2 = ill.severity === 'severe' ? 8 : ill.severity === 'moderate' ? 3 : 1;
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(0,0,0,0.2);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#c44e52;">⚠️ Risks:</strong> <span style="color:#ddd;">';
            html += '❤️ Drains <strong style="color:#e74c3c;">' + drainPerDay2 + ' health/day</strong>. ';
            if (illTypeDef && illTypeDef.deathRisk) {
                html += 'Daily death risk: ' + (illTypeDef.deathRisk * 100).toFixed(1) + '%. ';
            }
            html += 'Health at 0 = death. ';
            if (ill.severity === 'minor') {
                html += 'May worsen to <span style="color:#e67e22;">moderate</span> after 10 days untreated.';
            } else if (ill.severity === 'moderate') {
                html += 'May worsen to <span style="color:#e74c3c;">severe</span> after 25 days untreated.';
            } else if (ill.severity === 'severe') {
                html += '<span style="color:#e74c3c;">Can be fatal. Seek treatment immediately.</span>';
            }
            html += '</span></div>';

            // Treatment
            html += '<div style="font-size:0.8rem;padding:6px;background:rgba(50,100,50,0.15);border-radius:4px;margin:4px 0;">';
            html += '<strong style="color:#2ecc71;">💊 Treatment Options:</strong><br>';
            html += '<span style="color:#ddd;">';
            html += '🏥 <strong>Hospital</strong> — Treats all severities. Fastest recovery.<br>';
            if (ill.severity !== 'severe') {
                html += '🩺 <strong>Clinic</strong> — Treats minor/moderate. Cheaper than hospital.<br>';
            } else {
                html += '🩺 <strong>Clinic</strong> — <span style="color:#e67e22;">Can treat severe, but takes 2x longer with lower success rate.</span><br>';
            }
            html += '🧑‍⚕️ <strong>Self-treat</strong> — Requires ';
            if (ill.severity === 'minor') html += 'First Aid skill';
            else if (ill.severity === 'moderate') html += 'Field Medic skill';
            else html += 'Doctor skill';
            if (illTypeDef && illTypeDef.product) {
                var prodName2 = illTypeDef.product.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                html += ' + ' + prodName2 + ' (' + (illTypeDef.productCost || '?') + 'g)';
            }
            html += '</span></div>';
            html += '</div>';
        }

        html += '</div>';

        var footer = '<button class="btn-medieval" data-action="openHealthDialog" style="margin-right:8px;">🏥 Go to Treatment</button>';
        footer += '<button class="btn-medieval" data-action="closeModal">Close</button>';
        openModal('🏥 Health Status — Conditions Detail', html, footer);
    }

    // ═══════════════════════════════════════════════════════════
    //  GUILDS PANEL
    // ═══════════════════════════════════════════════════════════
    function openGuildsPanel() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot visit guilds while traveling.', 'warning'); return; }

        var guilds = CONFIG.GUILDS;
        if (!guilds) { toast('Guilds not available.', 'warning'); return; }

        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}

        var html = '<div style="max-height:550px;overflow-y:auto;">';
        html += '<p style="color:#ccc;margin:0 0 10px;">Join guilds to craft at any guild-member building in your town. One membership per building category.</p>';

        for (var gId in guilds) {
            var g = guilds[gId];
            var membership = Player.guildMemberships[gId];
            var isMember = membership && membership.expiresDay > day;
            var monthlyPrice = Player.getGuildPrice(gId, 'monthly');
            var yearlyPrice = Player.getGuildPrice(gId, 'yearly');
            var isMerchants = (gId === 'merchants');

            html += '<div style="border:1px solid ' + (isMember ? '#4a7' : '#555') + ';border-radius:6px;padding:10px;margin-bottom:8px;background:' + (isMember ? 'rgba(68,170,119,0.1)' : 'rgba(40,40,40,0.5)') + ';">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<span style="font-size:1.2em;">' + g.icon + ' <strong>' + escapeHtml(g.name) + '</strong></span>';

            if (isMember) {
                var _arStatus = membership.autoRenew ? ' <span style="color:#ffd700;font-size:0.8em;">🔄 Auto-renew ON</span>' : '';
                html += '<span style="color:#4a7;font-size:0.9em;">✅ Member until Day ' + membership.expiresDay + _arStatus + '</span>';
            } else {
                html += '<span style="color:#888;font-size:0.9em;">Not a member</span>';
            }
            html += '</div>';

            // Merchants Guild: special benefit description
            if (isMerchants) {
                if (!isMember) {
                    html += '<div style="background:rgba(255,215,0,0.08);border:1px solid #5a4a20;border-radius:4px;padding:8px;margin:6px 0;">';
                    html += '<div style="color:#d4a74a;font-size:0.9em;font-weight:bold;margin-bottom:4px;">📊 Exclusive Benefit: Daily Market Intelligence</div>';
                    html += '<div style="color:#bbb;font-size:0.82em;line-height:1.4;">Members gain access to the guild\'s <strong>Daily Market Report</strong> — a curated list of 10 trade tips compiled by guild agents across all towns. Tips include the best prices for goods, profitable trade routes, cheapest labor markets, building costs, resource shortages, and more. A new report is generated each day. Reading the report costs a small fee of ' + (CONFIG.MERCHANTS_GUILD_REPORT_FEE || 25) + 'g.</div>';
                    html += '</div>';
                } else {
                    // Member: show report button
                    html += '<div style="margin:6px 0;text-align:center;">';
                    html += '<button class="btn-medieval" style="background:linear-gradient(135deg,#3a2a10,#5a4a20);border-color:#d4a74a;color:#FFD700;padding:6px 16px;" data-action="openMerchantGuildReport">📊 Read Today\'s Market Report (' + (CONFIG.MERCHANTS_GUILD_REPORT_FEE || 25) + 'g)</button>';
                    html += '</div>';
                }
            }

            // Building types this guild gives access to
            var guildBuildingNames = [];
            var BT_G = typeof BUILDING_TYPES !== 'undefined' ? BUILDING_TYPES : (CONFIG.BUILDING_TYPES || {});
            for (var btk in BT_G) {
                var bt = BT_G[btk];
                if (g.categories.indexOf(bt.category) !== -1) {
                    guildBuildingNames.push(bt.name);
                }
            }
            if (!isMerchants) {
                html += '<div style="color:#aaa;font-size:0.85em;margin:4px 0;">Gives Access to Buildings: <span style="color:#ddd;">' + (guildBuildingNames.length > 0 ? guildBuildingNames.join(', ') : 'None') + '</span></div>';
            } else {
                html += '<div style="color:#aaa;font-size:0.85em;margin:4px 0;">Gives Access to: <span style="color:#ddd;">Market Stalls, Transport Guild Halls, & Daily Market Intelligence Reports</span></div>';
            }

            // Local availability indicator — only count buildings whose owner is in the guild
            var localTown = null;
            try { localTown = Engine.findTown(Player.townId); } catch(e2) {}
            var localGuildBuildings = 0;
            if (localTown && localTown.buildings) {
                for (var lbi = 0; lbi < localTown.buildings.length; lbi++) {
                    var lb = localTown.buildings[lbi];
                    if (!lb.inGuild) continue;
                    var lbt = null;
                    for (var lbk in BT_G) { if (BT_G[lbk].id === lb.type) { lbt = BT_G[lbk]; break; } }
                    if (lbt && g.categories.indexOf(lbt.category) !== -1) localGuildBuildings++;
                }
            }
            if (localGuildBuildings > 0) {
                html += '<div style="color:#4a7;font-size:0.85em;margin:2px 0;">✅ ' + localGuildBuildings + ' guild building' + (localGuildBuildings > 1 ? 's' : '') + ' in this town</div>';
            } else if (!isMerchants) {
                html += '<div style="color:#c55;font-size:0.85em;margin:2px 0;">❌ No guild buildings of this type here</div>';
            }

            // Join/Extend buttons with auto-renew next to active type
            html += '<div style="margin-top:6px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">';
            var _arLabel = '';
            if (isMember) {
                var _arChecked = membership.autoRenew ? 'checked' : '';
                _arLabel = '<label style="font-size:0.8em;color:#ccc;cursor:pointer;display:inline-flex;align-items:center;gap:3px;margin-left:2px;">' +
                    '<input type="checkbox" ' + _arChecked + ' onchange="(function(cb){var r=Player.setGuildAutoRenew(\'' + gId + '\',cb.checked);UI.toast(r.message,r.success?\'success\':\'warning\');UI.openGuildsPanel();})(this)">' +
                    '🔄 Auto</label>';
            }
            html += '<button class="btn-medieval" data-action="guildJoin" data-id="' + gId + '" data-type="monthly">' + (isMember ? '🔄 Extend' : '📜 Join') + ' Monthly (' + monthlyPrice + 'g)</button>';
            if (isMember && membership.type === 'monthly') html += _arLabel;
            html += '<button class="btn-medieval" data-action="guildJoin" data-id="' + gId + '" data-type="yearly">' + (isMember ? '🔄 Extend' : '📜 Join') + ' Yearly (' + yearlyPrice + 'g)</button>';
            if (isMember && membership.type !== 'monthly') html += _arLabel;
            html += '</div>';

            // If member, show craftable items at current town
            if (isMember) {
                var items = Player.getGuildCraftableItems();
                var guildItems = [];
                for (var i = 0; i < items.length; i++) {
                    if (items[i].guildName === g.name) guildItems.push(items[i]);
                }
                if (guildItems.length > 0) {
                    html += '<div style="margin-top:8px;border-top:1px solid #444;padding-top:6px;">';
                    html += '<div style="color:#aaa;font-size:0.85em;margin-bottom:4px;">Available to craft in this town:</div>';
                    for (var j = 0; j < guildItems.length; j++) {
                        var item = guildItems[j];
                        var matsText = '';
                        var consumeKeys = Object.keys(item.consumes || {});
                        if (consumeKeys.length > 0) {
                            var matParts = [];
                            for (var k = 0; k < consumeKeys.length; k++) {
                                matParts.push(item.consumes[consumeKeys[k]] + ' ' + consumeKeys[k]);
                            }
                            matsText = matParts.join(', ');
                        } else {
                            matsText = 'none';
                        }
                        html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid #333;">';
                        // Quality chance label for tiered products
                        var _gqLabel = '';
                        var _gqRes = findResource(item.productId);
                        if (_gqRes && (_gqRes.tier === 'good' || _gqRes.tier === 'excellent') && _gqRes.baseItem && Player.qualityCraftChance) {
                            var _gqChance = Math.round(Player.qualityCraftChance(_gqRes.tier, _gqRes.baseItem, 0) * 100);
                            _gqLabel = ' <span style="color:#a855f7;font-size:0.8em;">(' + _gqChance + '% chance)</span>';
                        }
                        html += '<span><strong>' + escapeHtml(item.productName) + '</strong>' + _gqLabel + ' <span style="color:#888;font-size:0.85em;">at ' + escapeHtml(item.buildingName) + ' (needs: ' + matsText + ')</span></span>';
                        html += '<button class="btn-medieval" style="font-size:0.85em;" data-action="guildCraftPrompt" data-id="' + escapeHtml(item.buildingId) + '" data-product="' + escapeHtml(item.productId) + '" data-name="' + escapeHtml(item.productName) + '">🔨 Craft</button>';
                        html += '</div>';
                    }
                    html += '</div>';
                } else if (!isMerchants) {
                    html += '<div style="margin-top:6px;color:#777;font-size:0.85em;">No guild buildings of this type in your current town.</div>';
                }
            }

            html += '</div>';
        }

        html += '</div>';
        openModal('🏛️ Guilds', html);
    }

    function guildJoin(guildId, type) {
        if (typeof Player === 'undefined') return;
        var result = Player.joinGuild(guildId, type);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openGuildsPanel(); // refresh
    }

    function openMerchantGuildReport() {
        if (typeof Player === 'undefined') return;
        var result = Player.readMerchantGuildReport();
        if (!result.success) {
            toast(result.message, 'warning');
            return;
        }

        var tips = result.tips || [];
        var day = 0;
        try { day = Engine.getDay(); } catch(e) {}
        var year = Math.floor((day - 1) / (CONFIG.DAYS_PER_SEASON || 90)) + 1;

        var html = '<div style="max-height:500px;overflow-y:auto;padding:4px;">';
        html += '<div style="text-align:center;border-bottom:2px solid #5a4a20;padding-bottom:8px;margin-bottom:12px;">';
        html += '<div style="font-size:1.1rem;color:#d4a74a;font-variant:small-caps;letter-spacing:2px;">Merchants\' Guild Intelligence Bureau</div>';
        html += '<div style="font-size:0.8rem;color:#888;margin-top:4px;">Daily Market Report — Day ' + day + ', Year ' + year + '</div>';
        html += '<div style="font-size:0.75rem;color:#666;margin-top:2px;">Report fee: ' + (result.fee || 10) + 'g deducted</div>';
        html += '</div>';

        if (tips.length === 0) {
            html += '<p style="color:#999;font-style:italic;text-align:center;">Our agents found no actionable intelligence today. Check back tomorrow.</p>';
        } else {
            for (var i = 0; i < tips.length; i++) {
                var tip = tips[i];
                html += '<div style="display:flex;gap:8px;align-items:flex-start;padding:6px 8px;margin-bottom:6px;background:rgba(60,50,30,0.2);border-left:3px solid #5a4a20;border-radius:0 4px 4px 0;">';
                html += '<span style="font-size:1.1rem;flex-shrink:0;">' + (tip.icon || '📋') + '</span>';
                html += '<div style="font-size:0.85rem;color:#d4c8a8;line-height:1.4;">' + (i + 1) + '. ' + tip.text + '</div>';
                html += '</div>';
            }
        }

        html += '<div style="text-align:center;margin-top:12px;border-top:1px solid #333;padding-top:8px;">';
        html += '<div style="font-size:0.7rem;color:#666;font-style:italic;">This report is valid for today only. A new report will be available tomorrow.</div>';
        html += '</div>';
        html += '</div>';

        openModal('📊 Daily Market Report', html, '<button class="btn-medieval" data-action="openGuildsPanel">← Back to Guilds</button> <button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    function guildCraftPrompt(buildingId, productId, productName) {
        var html = '<div style="text-align:center;">';
        html += '<p>How many <strong>' + productName + '</strong> to craft?</p>';
        html += '<input type="number" id="guildCraftQty" value="1" min="1" max="100" style="width:80px;text-align:center;padding:4px;background:#222;color:#eee;border:1px solid #555;border-radius:4px;">';
        html += '<div style="margin-top:10px;">';
        html += '<button class="btn-medieval" data-action="guildCraftExecute" data-id="' + escapeHtml(buildingId) + '" data-val="' + escapeHtml(productId) + '">🔨 Craft</button>';
        html += ' <button class="btn-medieval" data-action="openGuildsPanel">Cancel</button>';
        html += '</div></div>';
        openModal('🔨 Craft ' + productName, html);
    }

    function guildCraftExecute(buildingId, productId) {
        if (typeof Player === 'undefined') return;
        var qtyEl = document.getElementById('guildCraftQty');
        var qty = qtyEl ? parseInt(qtyEl.value, 10) : 1;
        if (isNaN(qty) || qty < 1) qty = 1;

        var result = Player.craftAtGuildBuilding(buildingId, productId, qty);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openGuildsPanel(); // refresh
    }

    // ═══════════════════════════════════════════════════════════
    //  REAL ESTATE MARKET ANALYSIS REPORT
    // ═══════════════════════════════════════════════════════════
    function openRealEstateReport(selectedTownId) {
        if (typeof Player === 'undefined' || typeof Engine === 'undefined') return;

        var hasLocal = Player.hasSkill && Player.hasSkill('local_market_analysis');
        var hasKingdom = Player.hasSkill && Player.hasSkill('kingdom_market_analysis');
        var hasGlobal = Player.hasSkill && Player.hasSkill('global_market_analysis');

        if (!hasLocal && !hasKingdom && !hasGlobal) {
            openModal('📊 Real Estate Report',
                '<p style="color:#cc8800;">You need the <b>Local Market Analysis</b> skill to view real estate reports.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        // Determine available towns
        var allTowns = Engine.getTowns();
        var playerTown = (typeof Player !== 'undefined' && Player.townId) ? Engine.findTown(Player.townId) : null;
        var playerKingdomId = typeof Player !== 'undefined' ? Player.kingdomId : null;
        var availableTowns = [];

        if (hasGlobal) {
            availableTowns = allTowns;
        } else if (hasKingdom) {
            for (var i = 0; i < allTowns.length; i++) {
                if (allTowns[i].kingdomId === playerKingdomId) availableTowns.push(allTowns[i]);
            }
        } else {
            if (playerTown) availableTowns = [playerTown];
        }

        if (availableTowns.length === 0) {
            openModal('📊 Real Estate Report',
                '<p style="color:#aaa;">No towns available for analysis.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        var targetTownId = selectedTownId || (playerTown ? playerTown.id : availableTowns[0].id);
        var report = Engine.getRealEstateReport(targetTownId);
        if (!report) {
            openModal('📊 Real Estate Report',
                '<p style="color:#cc8800;">No market data available for this town.</p>',
                '<button class="btn-medieval" data-action="closeModal">Close</button>');
            return;
        }

        var html = '<div style="max-height:520px;overflow-y:auto;">';

        // Town selector (if more than one town available)
        if (availableTowns.length > 1) {
            html += '<div style="margin-bottom:10px;">';
            html += '<label style="font-size:0.8rem;color:#ccc;">Select Town: </label>';
            html += '<select id="reReportTownSelect" onchange="UI.openRealEstateReport(this.value)" style="font-size:0.8rem;padding:3px 6px;background:#2a2520;color:#e8dcc8;border:1px solid #555;border-radius:4px;">';
            for (var ti = 0; ti < availableTowns.length; ti++) {
                var t = availableTowns[ti];
                var sel = (t.id === targetTownId) ? ' selected' : '';
                html += '<option value="' + t.id + '"' + sel + '>' + (t.name || t.id) + '</option>';
            }
            html += '</select></div>';
        }

        // Header
        html += '<h3 style="color:#ffd700;margin:0 0 6px 0;">📊 ' + report.townName + ' Real Estate Report</h3>';
        html += '<div style="font-size:0.75rem;color:#999;margin-bottom:10px;">Day ' + report.day + ' | ' + (report.category || 'Unknown') + '</div>';

        // Building costs table
        html += '<h4 style="color:#cba135;margin:10px 0 4px 0;">🏗️ Building Costs</h4>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:0.78rem;">';
        html += '<tr style="border-bottom:1px solid rgba(255,215,0,0.3);">';
        html += '<th style="text-align:left;padding:4px 6px;">Building</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Base Cost</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Material Cost</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Total</th></tr>';
        for (var bi = 0; bi < report.buildings.length; bi++) {
            var b = report.buildings[bi];
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">';
            html += '<td style="padding:3px 6px;">' + b.name + '</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ccc;">' + b.baseCost + 'g</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ccc;">' + b.materialCost + 'g</td>';
            html += '<td style="text-align:right;padding:3px 6px;color:#ffd700;">' + b.totalCost + 'g</td></tr>';
        }
        html += '</table>';

        // Material price trends table
        html += '<h4 style="color:#cba135;margin:14px 0 4px 0;">📈 Material Price Trends</h4>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:0.78rem;">';
        html += '<tr style="border-bottom:1px solid rgba(255,215,0,0.3);">';
        html += '<th style="text-align:left;padding:4px 6px;">Material</th>';
        html += '<th style="text-align:right;padding:4px 6px;">Current</th>';
        html += '<th style="text-align:right;padding:4px 6px;">90d Ago</th>';
        html += '<th style="text-align:right;padding:4px 6px;">360d Ago</th>';
        html += '<th style="text-align:right;padding:4px 6px;">90d Proj</th>';
        html += '<th style="text-align:right;padding:4px 6px;">360d Proj</th></tr>';

        for (var mi = 0; mi < report.materials.length; mi++) {
            var m = report.materials[mi];
            html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">';
            html += '<td style="padding:3px 6px;">' + m.name + '</td>';
            html += '<td style="text-align:right;padding:3px 6px;">' + (Math.round(m.current * 100) / 100) + 'g</td>';

            // 90 days ago with color coding
            if (m.price90ago !== null) {
                var color90 = m.price90ago > m.current ? '#55a868' : (m.price90ago < m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + color90 + ';">' + (Math.round(m.price90ago * 100) / 100) + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 4 years (360 days) ago with color coding
            if (m.price360ago !== null) {
                var color360 = m.price360ago > m.current ? '#55a868' : (m.price360ago < m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + color360 + ';">' + (Math.round(m.price360ago * 100) / 100) + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 90-day projection with color coding
            if (m.projected90 !== null) {
                var pColor90 = m.projected90 < m.current ? '#55a868' : (m.projected90 > m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + pColor90 + ';">' + m.projected90 + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }

            // 4-year (360-day) projection with color coding
            if (m.projected360 !== null) {
                var pColor360 = m.projected360 < m.current ? '#55a868' : (m.projected360 > m.current ? '#cc4444' : '#ccc');
                html += '<td style="text-align:right;padding:3px 6px;color:' + pColor360 + ';">' + m.projected360 + 'g</td>';
            } else {
                html += '<td style="text-align:right;padding:3px 6px;color:#666;">N/A</td>';
            }
            html += '</tr>';
        }
        html += '</table>';

        // Legend
        html += '<div style="margin-top:8px;font-size:0.7rem;color:#888;">';
        html += '<span style="color:#55a868;">■</span> Price drop (favorable) &nbsp;';
        html += '<span style="color:#cc4444;">■</span> Price increase (unfavorable)';
        html += '</div>';

        html += '</div>';

        openModal('📊 Real Estate Report', html,
            '<button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    // ═══════════════════════════════════════════════════════════
    //  SHIPS & VESSELS DIALOG
    // ═══════════════════════════════════════════════════════════
    function openShipsDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot manage ships while traveling.', 'warning'); return; }

        var townId = Player.state.townId;
        var town = Engine.findTown(townId);
        if (!town || !town.isPort) { toast('You must be at a seaport to manage ships.', 'warning'); return; }

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        // ── Section 1: Your Ships at this Port ──
        var shipsHere = Player.getShipsAtPort ? Player.getShipsAtPort(townId) : [];
        var maxShips = CONFIG.MAX_SHIPS_PER_PORT || 5;
        html += '<h3>⚓ Your Ships at ' + town.name + ' (' + shipsHere.length + '/' + maxShips + ' docked)</h3>';

        if (shipsHere.length === 0) {
            html += '<p style="color:#aaa;">No ships docked here. Build or sail one to this port.</p>';
        } else {
            for (var si = 0; si < shipsHere.length; si++) {
                var ship = shipsHere[si];
                var sType = CONFIG.SHIP_TYPES[ship.type] || {};
                var condition = ship.condition !== undefined ? ship.condition : 100;
                var condColor = condition >= 60 ? '#55a868' : condition >= 30 ? '#e67e22' : '#e74c3c';
                var condPct = Math.max(0, Math.min(100, condition));
                var dockFee = CONFIG.DOCKING_FEE_BASE[sType.sizeCategory || 'small'] || 10;

                // Status
                var status = '🟢 Idle';
                if (ship.assignedCaravan) status = '🔵 Assigned to caravan';
                if (ship.unpaidDocking) status = '⚠️ Unpaid docking';

                html += '<div style="border:1px solid #555;padding:8px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + (sType.icon || '⛵') + ' ' + (ship.name || sType.name || 'Ship') + '</strong> <span style="color:#aaa;font-size:0.8rem;">(' + (sType.name || ship.type) + ')</span></div>';
                html += '<div style="font-size:0.8rem;margin-top:2px;">📦 Cap: ' + (sType.capacity || 0) + ' | ⚡ Spd: ' + (sType.speed || 1).toFixed(1) + 'x | 🛡️ Def: ' + (sType.defense || 0) + ' | 👥 Min Crew: ' + (sType.minCrew || 1) + '</div>';

                // Condition bar
                html += '<div style="margin-top:4px;font-size:0.78rem;">🔧 Condition: <span style="color:' + condColor + ';">' + condPct + '%</span>';
                html += ' <div style="display:inline-block;width:80px;height:8px;background:rgba(255,255,255,0.1);border-radius:4px;vertical-align:middle;">';
                html += '<div style="width:' + condPct + '%;height:100%;background:' + condColor + ';border-radius:4px;"></div></div></div>';

                html += '<div style="font-size:0.78rem;color:#aaa;">' + status + ' | Docking: ' + dockFee + 'g/month</div>';

                // Buttons
                html += '<div style="margin-top:4px;">';
                html += '<button class="btn-medieval" data-action="repairShipAndOpenShipsDialog" data-id="' + ship.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;"' + (condition >= 100 ? ' disabled' : '') + '>🔧 Repair</button>';
                html += '<button class="btn-medieval" data-action="openShipCargo" data-id="' + ship.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">📦 Cargo</button>';
                if ((sType.maxAddons || 0) > 0) {
                    html += '<button class="btn-medieval" data-action="showShipAddons" data-id="' + ship.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">📦 Addons';
                    if (ship.addons) html += ' (' + ship.addons.length + '/' + sType.maxAddons + ')';
                    html += '</button>';
                }
                html += '</div></div>';
            }
        }

        // v9p33river83: Build a Ship section restored to the Ships dialog
        // (was removed in v9p33river75 per earlier user request, then user
        // changed their mind). Still removed from the Character > Inventory
        // dialog (v9p33river81).
        html += '<h3 style="margin-top:12px;">🏗️ Build a Ship</h3>';
        var atLimit = shipsHere.length >= maxShips;
        if (atLimit) {
            html += '<div style="font-size:0.8rem;color:#e67e22;margin-bottom:6px;">⚠️ Port is full (' + maxShips + '/' + maxShips + '). Sail a ship away to build more here.</div>';
        }

        for (var typeId in CONFIG.SHIP_TYPES) {
            var st = CONFIG.SHIP_TYPES[typeId];
            var totalCost = Player.getShipPrice ? Player.getShipPrice(typeId, townId) : 0;
            var canAfford = Player.gold >= totalCost;

            // Check materials
            var allMatsAvailable = true;
            var matParts = [];
            for (var matId in (st.materials || {})) {
                var needed = st.materials[matId];
                var playerHas = (Player.inventory && Player.inventory[matId]) || 0;
                var marketPrice = Engine.getResourcePrice ? Engine.getResourcePrice(townId, matId) : 0;
                var marketQty = Engine.getResourceSupply ? Engine.getResourceSupply(townId, matId) : 0;
                var needToBuy = Math.max(0, needed - playerHas);
                var hasEnough = playerHas >= needed;
                var marketHasEnough = needToBuy <= marketQty;
                if (!hasEnough && !marketHasEnough) allMatsAvailable = false;

                var matColor, indicator;
                if (hasEnough) {
                    matColor = '#55a868';
                    indicator = ' ✓ owned';
                } else if (marketHasEnough) {
                    matColor = '#d4a843';
                    indicator = ' 🛒 buy ' + needToBuy + ' @ ' + (marketPrice || 0).toFixed(1) + 'g ea';
                } else {
                    matColor = '#c44e52';
                    indicator = ' ✗ need ' + needToBuy + ', market has ' + marketQty;
                }
                matParts.push('<span style="color:' + matColor + ';">' + matId + ': ' + playerHas + '/' + needed + indicator + '</span>');
            }

            var canBuild = canAfford && allMatsAvailable && !atLimit;
            html += '<div style="border:1px solid #444;padding:6px;margin:3px 0;border-radius:4px;opacity:' + (canBuild ? '1' : '0.6') + ';">';
            html += '<div>' + (st.icon || '⛵') + ' <strong>' + st.name + '</strong> — <span style="color:#ffd700;">' + totalCost.toFixed(2) + 'g</span></div>';
            html += '<div style="font-size:0.75rem;color:#aaa;">' + (st.description || '') + '</div>';
            html += '<div style="font-size:0.8rem;margin-top:2px;">📦 Cap:' + st.capacity + ' ⚡ Spd:' + st.speed + ' 🛡️ Def:' + st.defense + ' 👥 Crew:' + st.minCrew + '</div>';

            if (matParts.length > 0) {
                html += '<div style="font-size:0.7rem;margin-top:2px;">📦 ' + matParts.join(', ') + '</div>';
            }

            html += '<button class="btn-medieval" data-action="buyShipAndOpenShipsDialog" data-id="' + typeId + '" style="font-size:0.75rem;padding:3px 8px;margin-top:3px;"' + (canBuild ? '' : ' disabled') + '>🏗️ Build</button>';
            if (atLimit) html += ' <span style="color:#c44e52;font-size:0.75rem;">Port full!</span>';
            if (!allMatsAvailable) html += ' <span style="color:#c44e52;font-size:0.75rem;">Missing materials!</span>';
            html += '</div>';
        }

        // ── Section 3: Ship Rentals Info ──
        html += '<h3 style="margin-top:12px;">📋 Ship Rentals</h3>';
        html += '<div style="font-size:0.8rem;color:#aaa;margin-bottom:6px;">Rent a ship per day for sea caravans without owning one.</div>';
        for (var rTypeId in CONFIG.SHIP_TYPES) {
            var rt = CONFIG.SHIP_TYPES[rTypeId];
            var rentalCost = Player.getShipRentalCost ? Player.getShipRentalCost(rTypeId, townId) : 0;
            html += '<div style="font-size:0.78rem;padding:2px 0;">' + (rt.icon || '⛵') + ' ' + rt.name + ' — <span style="color:#ffd700;">' + rentalCost.toFixed(1) + 'g/day</span> rental</div>';
        }
        html += '<div style="font-size:0.7rem;color:#888;margin-top:4px;">Select rental when creating a sea caravan.</div>';

        // ── Section 4: Ships at Other Ports (collapsible) ──
        var allShips = Player.state.ships || [];
        var otherShips = [];
        for (var oi = 0; oi < allShips.length; oi++) {
            if (allShips[oi].townId !== townId) otherShips.push(allShips[oi]);
        }
        if (otherShips.length > 0) {
            html += '<h3 style="margin-top:12px;cursor:pointer;" data-action="_toggleVisibility">📍 Ships at Other Ports ▾</h3>';
            html += '<div id="otherShipsSection" style="display:none;">';
            var grouped = {};
            for (var gi = 0; gi < otherShips.length; gi++) {
                var gTownId = otherShips[gi].townId || 'unknown';
                if (!grouped[gTownId]) grouped[gTownId] = [];
                grouped[gTownId].push(otherShips[gi]);
            }
            for (var gKey in grouped) {
                var gTown = Engine.findTown(gKey);
                var gTownName = gTown ? gTown.name : gKey;
                var gNames = [];
                for (var gni = 0; gni < grouped[gKey].length; gni++) {
                    var gs = grouped[gKey][gni];
                    var gst = CONFIG.SHIP_TYPES[gs.type] || {};
                    gNames.push((gst.icon || '⛵') + ' ' + (gs.name || gst.name || 'Ship'));
                }
                html += '<div style="font-size:0.8rem;padding:2px 0;"><strong>' + gTownName + ':</strong> ' + gNames.join(', ') + '</div>';
            }
            html += '</div>';
        }

        html += '</div>';
        openModal('⛵ Ships & Vessels', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  v9p33river74: SHIP CARGO DIALOG (load/unload between ship & inventory)
    // ═══════════════════════════════════════════════════════════
    function openShipCargoDialog(shipId) {
        if (typeof Player === 'undefined') return;
        var ship = (Player.ships || []).find(function(s) { return s.id === shipId; });
        if (!ship) { toast('Ship not found.', 'error'); return; }
        var sType = CONFIG.SHIP_TYPES[ship.type] || {};
        var capacity = sType.capacity || 0;
        var cargo = Player.getShipCargo ? Player.getShipCargo(shipId) : (ship.cargo || {});
        var cargoWeight = Player.getShipCargoWeight ? Player.getShipCargoWeight(shipId) : 0;
        var inv = Player.inventory || {};
        var carry = Player.getCarryCapacity ? Player.getCarryCapacity() : 0;
        var carried = Player.getCarriedWeight ? Player.getCarriedWeight() : 0;

        var pctShip = capacity > 0 ? Math.min(100, Math.floor(cargoWeight / capacity * 100)) : 0;
        var pctYou = carry > 0 ? Math.min(100, Math.floor(carried / carry * 100)) : 0;

        var html = '<div style="max-height:520px;overflow-y:auto;">';
        html += '<div style="display:flex;gap:12px;margin-bottom:10px;">';
        html += '<div style="flex:1;background:rgba(40,80,120,0.18);border:1px solid #4a7090;border-radius:6px;padding:8px;">';
        html += '<div style="font-weight:bold;">' + (sType.icon || '⛵') + ' ' + (ship.name || sType.name || 'Ship') + '</div>';
        html += '<div style="font-size:0.78rem;color:#aaa;">Cargo: ' + cargoWeight + ' / ' + capacity + ' weight (' + pctShip + '%)</div>';
        html += '<div style="height:6px;background:rgba(255,255,255,0.08);border-radius:3px;margin-top:4px;"><div style="width:' + pctShip + '%;height:100%;background:#4a90c0;border-radius:3px;"></div></div>';
        html += '</div>';
        html += '<div style="flex:1;background:rgba(110,90,40,0.18);border:1px solid #8a7040;border-radius:6px;padding:8px;">';
        html += '<div style="font-weight:bold;">🎒 You</div>';
        html += '<div style="font-size:0.78rem;color:#aaa;">Carry: ' + carried + ' / ' + carry + ' weight (' + pctYou + '%)</div>';
        html += '<div style="height:6px;background:rgba(255,255,255,0.08);border-radius:3px;margin-top:4px;"><div style="width:' + pctYou + '%;height:100%;background:#c0a050;border-radius:3px;"></div></div>';
        html += '</div>';
        html += '</div>';

        // Two-column layout: ship side / inventory side
        html += '<div style="display:flex;gap:10px;">';

        // Ship cargo (unload)
        html += '<div style="flex:1;border:1px solid #444;border-radius:6px;padding:6px;">';
        html += '<div style="font-weight:bold;margin-bottom:4px;">⛵ On Ship</div>';
        var shipKeys = Object.keys(cargo).filter(function(k) { return cargo[k] > 0; }).sort();
        if (shipKeys.length === 0) {
            html += '<div style="font-size:0.8rem;color:#888;">Empty.</div>';
        } else {
            for (var i = 0; i < shipKeys.length; i++) {
                var k = shipKeys[i];
                var qty = cargo[k];
                html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);">';
                html += '<span style="font-size:0.8rem;">' + k + ' × ' + qty + '</span>';
                html += '<span>';
                html += '<button class="btn-medieval" data-action="shipCargoUnload" data-id="' + shipId + '" data-res="' + k + '" data-qty="1" style="font-size:0.7rem;padding:1px 5px;">▶ 1</button> ';
                html += '<button class="btn-medieval" data-action="shipCargoUnload" data-id="' + shipId + '" data-res="' + k + '" data-qty="10" style="font-size:0.7rem;padding:1px 5px;">▶ 10</button> ';
                html += '<button class="btn-medieval" data-action="shipCargoUnload" data-id="' + shipId + '" data-res="' + k + '" data-qty="' + qty + '" style="font-size:0.7rem;padding:1px 5px;">▶ All</button>';
                html += '</span></div>';
            }
        }
        html += '</div>';

        // Inventory (load)
        html += '<div style="flex:1;border:1px solid #444;border-radius:6px;padding:6px;">';
        html += '<div style="font-weight:bold;margin-bottom:4px;">🎒 Inventory</div>';
        var invKeys = Object.keys(inv).filter(function(k) { return inv[k] > 0 && k !== 'horses'; }).sort();
        if (invKeys.length === 0) {
            html += '<div style="font-size:0.8rem;color:#888;">Nothing to load.</div>';
        } else {
            for (var ii = 0; ii < invKeys.length; ii++) {
                var ik = invKeys[ii];
                var iq = inv[ik];
                html += '<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);">';
                html += '<span style="font-size:0.8rem;">' + ik + ' × ' + iq + '</span>';
                html += '<span>';
                html += '<button class="btn-medieval" data-action="shipCargoLoad" data-id="' + shipId + '" data-res="' + ik + '" data-qty="1" style="font-size:0.7rem;padding:1px 5px;">◀ 1</button> ';
                html += '<button class="btn-medieval" data-action="shipCargoLoad" data-id="' + shipId + '" data-res="' + ik + '" data-qty="10" style="font-size:0.7rem;padding:1px 5px;">◀ 10</button> ';
                html += '<button class="btn-medieval" data-action="shipCargoLoad" data-id="' + shipId + '" data-res="' + ik + '" data-qty="' + iq + '" style="font-size:0.7rem;padding:1px 5px;">◀ All</button>';
                html += '</span></div>';
            }
        }
        html += '</div>';

        html += '</div>';
        html += '</div>';
        openModal('📦 Cargo: ' + (ship.name || sType.name || 'Ship'), html, '<button class="btn-medieval" data-action="closeModal">Close</button> <button class="btn-medieval" data-action="openShipsDialog">⛵ Back to Ships</button>');
    }

    function _shipCargoTransfer(shipId, resId, qty, direction) {
        if (!Player.transferShipCargo) return;
        var r = Player.transferShipCargo(shipId, resId, qty, direction);
        if (r.success) toast(r.message, 'success');
        else toast(r.message, 'warning');
        // Refresh dialog
        openShipCargoDialog(shipId);
    }

    // ═══════════════════════════════════════════════════════════
    //  HOUSING DIALOG
    // ═══════════════════════════════════════════════════════════
    function openHousingDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot manage housing while traveling.', 'warning'); return; }

        var html = '<div style="max-height:500px;overflow-y:auto;">';

        // Current houses
        var houses = Player.houses || [];
        html += '<h3>🏠 Your Properties (' + houses.length + ')</h3>';
        if (houses.length === 0) {
            html += '<p style="color:#aaa;">No properties owned. Buy land and build a home!</p>';
        } else {
            for (var i = 0; i < houses.length; i++) {
                var h = houses[i];
                var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === h.type; });
                if (!ht) continue;
                var town = Engine.findTown(h.townId);
                var isPrimary = h.id === Player.primaryHouseId;
                html += '<div style="border:1px solid ' + (isPrimary ? '#ffd700' : '#555') + ';padding:8px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + ht.icon + ' ' + ht.name + '</strong> in ' + (town ? town.name : '?') + (isPrimary ? ' ⭐ Primary' : '') + '</div>';
                html += '<div style="font-size:0.8rem;color:#aaa;">' + ht.description + '</div>';
                html += '<div style="font-size:0.8rem;">Storage: ' + ht.storage + ' | Comfort: ' + ht.comfort + ' | Security: ' + Math.round(ht.security * 100) + '%</div>';
                // Show installed addons
                if (h.addons && h.addons.length > 0 && CONFIG.HOUSE_ADDONS) {
                    var _addonNames = [];
                    for (var _ai = 0; _ai < h.addons.length; _ai++) {
                        var _aDef = CONFIG.HOUSE_ADDONS[h.addons[_ai]];
                        if (_aDef) _addonNames.push(_aDef.icon + ' ' + _aDef.name);
                    }
                    html += '<div style="font-size:0.78rem;color:#5ac85a;">Addons: ' + _addonNames.join(', ') + '</div>';
                    // Garden manure status
                    if (h.addons.indexOf('garden') >= 0) {
                        var _manure = h.gardenManure || 0;
                        var _manureColor = _manure <= 0 ? '#c44e52' : _manure <= 1 ? '#e67e22' : '#5ac85a';
                        html += '<div style="font-size:0.78rem;">💩 Garden Manure: <span style="color:' + _manureColor + ';">' + _manure + '/4</span>';
                        if (_manure <= 0) html += ' <span style="color:#c44e52;">⚠️ Garden inactive!</span>';
                        if (h.townId === Player.townId) {
                            html += ' <button class="btn-medieval" data-action="refillGardenManure" data-id="' + h.id + '" style="font-size:0.65rem;padding:1px 6px;margin-left:4px;">💩 Refill</button>';
                        }
                        html += '</div>';
                    }
                }
                // Home storage contents + transfer UI
                var _hsUsed = Player.getHomeStorageUsed ? Player.getHomeStorageUsed(h) : 0;
                var _hsCap = Player.getHomeStorageCapacity ? Player.getHomeStorageCapacity(h) : (ht.storage || 0);
                var _hsPct = _hsCap > 0 ? Math.round(_hsUsed / _hsCap * 100) : 0;
                var _hsColor = _hsPct >= 90 ? '#e74c3c' : _hsPct >= 60 ? '#e67e22' : '#55a868';
                html += '<div style="font-size:0.78rem;margin-top:2px;">📦 Stored: <span style="color:' + _hsColor + ';">' + Math.round(_hsUsed) + '/' + _hsCap + '</span>';
                if (h.homeStorage) {
                    var _hItems = [];
                    for (var _hk in h.homeStorage) {
                        if (h.homeStorage[_hk] > 0) {
                            var _hr = typeof findResource === 'function' ? findResource(_hk) : null;
                            if (!_hr && typeof Player.findResource === 'function') _hr = Player.findResource(_hk);
                            _hItems.push((_hr ? (_hr.icon || '') + ' ' + _hr.name : _hk) + ': ' + h.homeStorage[_hk]);
                        }
                    }
                    if (_hItems.length > 0) html += ' — ' + _hItems.join(', ');
                }
                html += '</div>';
                // Horses stabled at home
                var _maxHomeHorses = (Player.hasSkill && Player.hasSkill('horse_mastery')) ? 4 : 2;
                var _homeHorses = h.horses || [];
                html += '<div style="font-size:0.78rem;">🐴 Horses: ' + _homeHorses.length + '/' + _maxHomeHorses;
                if (_homeHorses.length > 0) {
                    html += ' — ';
                    for (var _hhi = 0; _hhi < _homeHorses.length; _hhi++) {
                        var _hh = _homeHorses[_hhi];
                        html += (_hh.name || 'Horse') + ' ';
                        if (h.townId === Player.townId) html += '<button class="btn-medieval" data-action="unstableHorseUI" data-id="' + h.id + '" data-val="' + _hhi + '" style="font-size:0.65rem;padding:1px 5px;">Take</button> ';
                    }
                }
                html += '</div>';
                // Transfer buttons (only when in same town)
                if (h.townId === Player.townId) {
                    html += '<button class="btn-medieval" data-action="openHomeStorageUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">📦 Transfer Goods</button>';
                    if (Player.horses && Player.horses.length > 0 && _homeHorses.length < _maxHomeHorses) {
                        html += '<button class="btn-medieval" data-action="stableHorseUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🐴 Stable Horse</button>';
                    }
                    var _availAddons = Player.getAvailableAddons ? Player.getAvailableAddons(h.id) : [];
                    if (_availAddons.length > 0) {
                        html += '<button class="btn-medieval" data-action="openHouseAddonsUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🔧 Addons (' + _availAddons.length + ')</button>';
                    }
                    // Craft button if house has a workshop (built-in or addon)
                    var _htForCraft = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === h.type; });
                    var _hasWorkshop = (_htForCraft && _htForCraft.hasWorkshop) || (h.addons && h.addons.indexOf('workshop') >= 0);
                    if (_hasWorkshop) {
                        html += '<button class="btn-medieval" data-action="openHomeCraftUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🔨 Craft</button>';
                    }
                }
                if (h.isRental) {
                    html += '<div style="color:#5ac85a;font-size:0.8rem;">💰 Rented — ' + (h.monthlyRent || 0) + 'g/month (total earned: ' + (h.rentAccumulated || 0) + 'g)</div>';
                    if (h.tenantId) {
                        var _tenant = Engine.findPerson(h.tenantId);
                        var _tName = _tenant ? ((_tenant.firstName || '') + ' ' + (_tenant.lastName || '')) : 'Unknown';
                        html += '<div style="font-size:0.78rem;color:#aaa;">👤 Tenant: ' + _tName + (h.tenantType === 'em' ? ' (Elite Merchant)' : '') + '</div>';
                        if (h.evictionDay) {
                            html += '<div style="font-size:0.78rem;color:#c44e52;">⚠️ Eviction pending — leaves by day ' + h.evictionDay + '</div>';
                        }
                    } else {
                        html += '<div style="font-size:0.78rem;color:#888;">🔍 Waiting for tenant...</div>';
                    }
                }
                if (h.monthlyMaintenance) {
                    html += '<div style="font-size:0.78rem;color:#c4a35a;">🏢 Apartment — weekly maintenance: ' + h.monthlyMaintenance + 'g</div>';
                }
                html += '<div style="margin-top:4px;">';
                if (!isPrimary) html += '<button class="btn-medieval" data-action="setPrimaryHouseUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">⭐ Set Primary</button>';
                // Tents: only Leave option (stop renting), no rent-out/upgrade/sell
                if (ht.fromTentCamp) {
                    html += '<button class="btn-medieval" data-action="leaveTentUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🚪 Leave Tent</button>';
                } else {
                    // Rent out (not for apartments owned from a building — those are units, not full houses)
                    if (!ht.fromApartmentBuilding) {
                        html += '<button class="btn-medieval" data-action="rentOutHouseUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">' + (h.isRental ? '🏠 Stop Renting' : '💰 Rent Out') + '</button>';
                        if (h.tenantId && !h.evictionDay) html += '<button class="btn-medieval" data-action="evictTenantUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🚪 Evict</button>';
                    }
                    // Upgrade only for land-based houses (not apartments, not tents, not portable)
                    if (!ht.fromApartmentBuilding && !ht.portable) {
                        html += '<button class="btn-medieval" data-action="upgradeHouseUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;">🏗️ Upgrade</button>';
                    }
                    // Sell — opens listing UI with price recommendation
                    html += '<button class="btn-medieval" data-action="sellHouseUI" data-id="' + h.id + '" style="font-size:0.75rem;padding:3px 8px;margin:2px;color:#c44e52;">🏚️ Sell</button>';
                }
                html += '</div></div>';
            }
        }

        // Available to buy (if player is in a town)
        if (!Player.traveling && Player.townId) {
            var town = Engine.findTown(Player.townId);
            if (town) {
                html += '<h3 style="margin-top:12px;">🏗️ Buy Housing in ' + town.name + '</h3>';
                var ownedLand = Player.getOwnedLand(Player.townId);
                var usedLand = Player.getUsedLandSlots ? Player.getUsedLandSlots(Player.townId) : 0;
                // v9p33river137: rank/cap is per-kingdom now, not global.
                var _townKingdomId = town.kingdomId;
                var _rankIdx = Player.getPlayerRankIndex ? Player.getPlayerRankIndex(_townKingdomId) : 0;
                var _rankCfg = CONFIG.SOCIAL_RANKS[_rankIdx];
                var _rankMaxLand = (_rankCfg && _rankCfg.maxLand !== undefined) ? _rankCfg.maxLand : '∞';
                var _kingdomLandOwned = Player.getLandInKingdom ? Player.getLandInKingdom(_townKingdomId) : 0;
                var _kingdomObj = Engine.findKingdom ? Engine.findKingdom(_townKingdomId) : null;
                var _kingdomLabel = _kingdomObj ? _kingdomObj.name : 'this kingdom';
                var _hdSub = Player.getActiveSubsidy ? Player.getActiveSubsidy(Player.townId) : null;
                var _hdCost = Player.getLandCost ? Player.getLandCost(Player.townId) : '?';
                var _hdBtnTxt = 'Buy Land (' + _hdCost + 'g)';
                if (_hdSub) _hdBtnTxt = 'Buy Land (' + _hdCost + 'g) ⭐ Subsidy!';
                html += '<div style="font-size:0.85rem;margin-bottom:8px;">Land plots: ' + usedLand + '/' + ownedLand + ' used (in ' + _kingdomLabel + ': ' + _kingdomLandOwned + '/' + _rankMaxLand + ' as ' + (_rankCfg ? _rankCfg.name : 'your rank') + ') | <button class="btn-medieval" data-action="buyLandUI" style="font-size:0.75rem;padding:2px 8px;">' + _hdBtnTxt + '</button></div>';
                // Show subsidized (locked) plots
                var _subLand = (Player.state && Player.state.subsidizedLand && Player.state.subsidizedLand[Player.townId]) || [];
                if (_subLand.length > 0) {
                    html += '<div style="font-size:0.78rem;color:#55a868;margin-bottom:6px;">🔒 Subsidized plots: ';
                    var _slNames = [];
                    for (var _sli = 0; _sli < _subLand.length; _sli++) {
                        var _slBt = Engine.findBuildingType(_subLand[_sli].buildingType);
                        _slNames.push(_slBt ? _slBt.name : _subLand[_sli].buildingType);
                    }
                    html += _slNames.join(', ') + '</div>';
                }

                for (var j = 0; j < CONFIG.HOUSING_TYPES.length; j++) {
                    var htype = CONFIG.HOUSING_TYPES[j];
                    if (htype.id === 'bedroll' || htype.id === 'inn_room') continue;
                    if (htype.notBuildable || htype.fromApartmentBuilding) continue;
                    if (htype.requiresPort && !town.isPort) continue;
                    if (htype.portable && htype.requiresHorse && (!Player.horses || Player.horses.length === 0)) continue;
                    var catOrder = ['village', 'town', 'city', 'capital_city'];
                    if (htype.minTownCategory && catOrder.indexOf(town.category || 'village') < catOrder.indexOf(htype.minTownCategory)) continue;
                    var costInfo = Player.getHousingCost(htype.id, Player.townId);
                    var totalCost = costInfo.total || 0;
                    var canAfford = Player.gold >= totalCost;
                    var matsAvailable = costInfo.available !== false;
                    var needsLand = htype.id !== 'apartment' && !htype.portable && usedLand >= ownedLand;
                    var canBuild = canAfford && matsAvailable && !needsLand;
                    // Rank check
                    if (htype.minRank) {
                        var bestRank = 0;
                        var sr = Player.state.socialRank || {};
                        for (var rk in sr) { if ((sr[rk] || 0) > bestRank) bestRank = sr[rk]; }
                        if (bestRank < htype.minRank) canBuild = false;
                    }
                    html += '<div style="border:1px solid #444;padding:6px;margin:3px 0;border-radius:4px;opacity:' + (canBuild ? '1' : '0.6') + ';">';
                    html += '<div>' + htype.icon + ' <strong>' + htype.name + '</strong> — <span style="color:#ffd700;">' + totalCost.toFixed(2) + 'g</span>';
                    if (costInfo.laborCost) html += ' <span class="text-dim" style="font-size:0.75rem;">(materials: ' + costInfo.materialCost.toFixed(2) + 'g + labor: ' + costInfo.laborCost.toFixed(2) + 'g)</span>';
                    html += '</div>';
                    html += '<div style="font-size:0.75rem;color:#aaa;">' + htype.description + '</div>';
                    // Material list — shows owned + market availability
                    if (htype.materials) {
                        html += '<div style="font-size:0.7rem;margin-top:2px;">';
                        var matParts = [];
                        for (var mid in costInfo.breakdown) {
                            var mb = costInfo.breakdown[mid];
                            var hasEnough = mb.playerHas >= mb.needed;
                            var matColor, indicator;
                            if (hasEnough) {
                                matColor = '#55a868';
                                indicator = ' ✓ owned';
                            } else if (mb.needToBuy <= mb.marketHas) {
                                matColor = '#d4a843';
                                indicator = ' 🛒 buy ' + mb.needToBuy + ' @ ' + mb.unitPrice.toFixed(1) + 'g ea';
                            } else {
                                matColor = '#c44e52';
                                indicator = ' ✗ need ' + mb.needToBuy + ', market has ' + mb.marketHas;
                            }
                            matParts.push('<span style="color:' + matColor + ';">' + mid + ': ' + mb.needed + ' (' + mb.playerHas + ' owned' + indicator + ')</span>');
                        }
                        html += '📦 ' + matParts.join(', ') + '</div>';
                    }
                    html += '<button class="btn-medieval" data-action="buyHouseUI" data-id="' + htype.id + '" style="font-size:0.75rem;padding:3px 8px;margin-top:3px;"' + (canBuild ? '' : ' disabled') + '>🏗️ Build</button>';
                    if (needsLand) html += ' <span style="color:#c44e52;font-size:0.75rem;">Need land!</span>';
                    if (!matsAvailable) html += ' <span style="color:#c44e52;font-size:0.75rem;">Missing materials!</span>';
                    if (htype.minRank) {
                        var reqName = CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[htype.minRank] ? CONFIG.SOCIAL_RANKS[htype.minRank].name : 'Rank ' + htype.minRank;
                        html += ' <span style="font-size:0.7rem;color:#aaa;">Requires: ' + reqName + '</span>';
                    }
                    html += '</div>';
                }

                // === Apartments for sale in current town ===
                var aptBuildings = (town.buildings || []).filter(function(b) { return b.type === 'apartment_building'; });
                if (aptBuildings.length > 0) {
                    html += '<h3 style="margin-top:12px;margin-bottom:6px;">🏢 Apartments For Sale</h3>';
                    for (var ai = 0; ai < aptBuildings.length; ai++) {
                        var aptBld = aptBuildings[ai];
                        var units = aptBld.units || [];
                        var availableUnits = units.filter(function(u) { return !u.occupantId; });
                        var ownerName = 'Unknown';
                        if (aptBld.ownerId === 'player') { ownerName = 'You'; }
                        else if (aptBld.ownerId) {
                            var _aptOwner = Engine.findPerson(aptBld.ownerId);
                            if (_aptOwner) ownerName = (_aptOwner.firstName || '') + ' ' + (_aptOwner.lastName || '');
                            else {
                                var _aptK = Engine.findKingdom(aptBld.ownerId);
                                if (_aptK) ownerName = _aptK.name;
                            }
                        }
                        var _aptUnitPrice = aptBld.unitPrice || 0;
                        // v9p33river322: prefer canonical weeklyFee
                        var _aptWeeklyFee = aptBld.weeklyFee || aptBld.monthlyFee || 0;
                        html += '<div style="border:1px solid #555;padding:6px;margin:3px 0;border-radius:4px;">';
                        html += '<div><strong>🏢 Apartment Building</strong> — Owner: ' + ownerName + '</div>';
                        html += '<div style="font-size:0.78rem;color:#aaa;">' + availableUnits.length + '/' + units.length + ' units available | Buy: <span style="color:#ffd700;">' + Math.ceil(_aptUnitPrice) + 'g</span> | Weekly: <span style="color:#ffd700;">' + Math.ceil(_aptWeeklyFee) + 'g</span></div>';
                        if (availableUnits.length > 0 && aptBld.ownerId !== 'player') {
                            var _canAffordApt = (Player.gold || 0) >= _aptUnitPrice;
                            html += '<button class="btn-medieval" style="font-size:0.7rem;padding:3px 8px;margin-top:4px;" ' + (_canAffordApt ? '' : 'disabled') + ' data-action="buyApartmentUnit" data-id="' + aptBld._id + '">🏢 Buy Apartment (' + Math.ceil(_aptUnitPrice) + 'g)</button>';
                        }
                        html += '</div>';
                    }
                }
            }
        }

        html += '</div>';
        openModal('🏠 Housing & Property', html);
    }

    // ── HOUSE ADDONS UI ──
    function openHouseAddonsUI(houseId) {
        var houses = Player.state.houses || Player.houses || [];
        var house = houses.find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === house.type; });
        var available = Player.getAvailableAddons ? Player.getAvailableAddons(houseId) : [];
        var installed = house.addons || [];

        var html = '<div style="max-height:450px;overflow-y:auto;">';
        html += '<div style="font-size:0.85rem;margin-bottom:8px;">' + (ht ? ht.icon : '🏠') + ' <strong>' + (ht ? ht.name : 'House') + '</strong></div>';

        // Installed addons
        if (installed.length > 0) {
            html += '<h4 style="margin:8px 0 4px;color:#5ac85a;">Installed Addons</h4>';
            for (var ii = 0; ii < installed.length; ii++) {
                var iDef = CONFIG.HOUSE_ADDONS ? CONFIG.HOUSE_ADDONS[installed[ii]] : null;
                if (!iDef) continue;
                html += '<div style="border:1px solid #3a5a3a;padding:4px 6px;margin:3px 0;border-radius:3px;background:rgba(90,200,90,0.08);">';
                html += '<strong>' + iDef.icon + ' ' + iDef.name + '</strong> ✅';
                html += '<div style="font-size:0.78rem;color:#aaa;">' + iDef.description + '</div>';
                html += '</div>';
            }
        }

        // Available addons
        if (available.length > 0) {
            html += '<h4 style="margin:12px 0 4px;">Available Addons</h4>';
            for (var ai = 0; ai < available.length; ai++) {
                var addon = available[ai];
                html += '<div style="border:1px solid #555;padding:6px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + addon.icon + ' ' + addon.name + '</strong></div>';
                html += '<div style="font-size:0.78rem;color:#aaa;">' + addon.desc + '</div>';
                html += '<div style="font-size:0.78rem;margin-top:2px;">';
                html += '💰 ' + addon.goldCost + 'g';
                if (addon.materials) {
                    var matParts = [];
                    for (var mk in addon.materials) {
                        var mRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === mk; });
                        matParts.push((mRes ? mRes.icon + ' ' : '') + addon.materials[mk] + ' ' + (mRes ? mRes.name : mk));
                    }
                    html += ' | ' + matParts.join(', ');
                }
                html += '</div>';
                html += '<button class="btn-medieval" data-action="doInstallAddon" data-id="' + houseId + '" data-val="' + addon.id + '" style="font-size:0.75rem;padding:3px 10px;margin-top:4px;color:#e8dcc8;">🔧 Install</button>';
                html += '</div>';
            }
        } else if (installed.length === 0) {
            html += '<div style="font-size:0.8rem;color:#888;">No addons available for this house type.</div>';
        } else {
            html += '<div style="font-size:0.8rem;color:#888;margin-top:8px;">All available addons installed! ✅</div>';
        }

        html += '</div>';
        openModal('🔧 House Addons', html,
            '<button class="btn-medieval" data-action="openHousingDialog">Back to Housing</button>');
    }

    function doInstallAddon(houseId, addonId) {
        var result = Player.installAddon(houseId, addonId);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openHouseAddonsUI(houseId); // refresh
    }

    // ── HOME CRAFT UI ──
    function openHomeCraftUI(houseId) {
        var recipes = Player.getHomeCraftRecipes ? Player.getHomeCraftRecipes() : [];
        var html = '<div style="max-height:450px;overflow-y:auto;">';
        html += '<div style="font-size:0.85rem;margin-bottom:8px;">🔨 <strong>Workshop Crafting</strong></div>';
        if (recipes.length === 0) {
            html += '<div style="color:#888;">No recipes available.</div>';
        } else {
            for (var ri = 0; ri < recipes.length; ri++) {
                var r = recipes[ri];
                html += '<div style="border:1px solid #555;padding:6px;margin:4px 0;border-radius:4px;background:rgba(0,0,0,0.2);">';
                html += '<div><strong>' + r.name + '</strong> <span style="color:#5ac85a;">→ ' + r.qty + 'x</span></div>';
                // Show inputs
                var inputParts = [];
                for (var resId in r.inputs) {
                    var rDef = Object.values(RESOURCE_TYPES).find(function(res) { return res.id === resId; });
                    var held = (Player.inventory[resId] || 0);
                    var houseObj = (Player.state.houses || Player.houses || []).find(function(h) { return h.id === houseId; });
                    var homeHeld = houseObj && houseObj.homeStorage ? (houseObj.homeStorage[resId] || 0) : 0;
                    var total = held + homeHeld;
                    var needed = r.inputs[resId];
                    var color = total >= needed ? '#5ac85a' : '#c44e52';
                    inputParts.push((rDef ? rDef.icon + ' ' : '') + '<span style="color:' + color + ';">' + total + '/' + needed + '</span> ' + (rDef ? rDef.name : resId));
                }
                html += '<div style="font-size:0.78rem;margin:2px 0;">Needs: ' + inputParts.join(', ') + '</div>';
                if (r.skill) html += '<div style="font-size:0.72rem;color:#c4a35a;">Requires: ' + r.skill + ' skill</div>';
                html += '<button class="btn-medieval" data-action="doHomeCraft" data-id="' + houseId + '" data-val="' + r.id + '" style="font-size:0.75rem;padding:3px 10px;margin-top:4px;">🔨 Craft</button>';
                html += '</div>';
            }
        }
        html += '</div>';
        openModal('🔨 Home Workshop', html,
            '<button class="btn-medieval" data-action="openHousingDialog">Back to Housing</button>');
    }

    function doHomeCraft(houseId, recipeId) {
        var result = Player.craftAtHome(recipeId);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        openHomeCraftUI(houseId);
    }

    function refillGardenManure(houseId) {
        var houses = Player.state.houses || Player.houses || [];
        var house = houses.find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        if (!house.addons || house.addons.indexOf('garden') < 0) { toast('No garden installed.', 'error'); return; }
        var current = house.gardenManure || 0;
        if (current >= 4) { toast('Garden manure is already full (4/4).', 'info'); return; }
        var needed = 4 - current;
        var have = Player.inventory.manure || 0;
        if (have <= 0) { toast('You need manure in your inventory. Buy some from a farm town market!', 'warning'); return; }
        var toAdd = Math.min(needed, have);
        Player.inventory.manure -= toAdd;
        if (Player.inventory.manure <= 0) delete Player.inventory.manure;
        house.gardenManure = current + toAdd;
        toast('💩 Added ' + toAdd + ' manure to garden (' + house.gardenManure + '/4).', 'success');
        openHousingDialog();
    }

    // ── HOME STORAGE TRANSFER UI ──
    function openHomeStorageUI(houseId) {
        var houses = Player.state.houses || Player.houses || [];
        var house = houses.find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        var ht = CONFIG.HOUSING_TYPES.find(function(t) { return t.id === house.type; });
        var cap = Player.getHomeStorageCapacity ? Player.getHomeStorageCapacity(house) : (ht ? ht.storage : 0);
        var used = Player.getHomeStorageUsed ? Player.getHomeStorageUsed(house) : 0;

        var html = '<div style="max-height:400px;overflow-y:auto;">';
        html += '<div style="font-size:0.85rem;margin-bottom:8px;">📦 Storage: <strong>' + Math.round(used) + '/' + cap + '</strong></div>';

        // Items stored in home — withdraw buttons
        html += '<h4 style="margin:8px 0 4px;">Stored at Home</h4>';
        var hasStored = false;
        if (house.homeStorage) {
            for (var sk in house.homeStorage) {
                if (house.homeStorage[sk] <= 0) continue;
                hasStored = true;
                var sr = findResource(sk);
                var sName = sr ? (sr.icon || '') + ' ' + sr.name : sk;
                var sQty = house.homeStorage[sk];
                html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;font-size:0.8rem;">';
                html += '<span style="min-width:140px;">' + sName + ': ' + sQty + '</span>';
                html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeWithdraw" data-id="' + houseId + '" data-key="' + sk + '" data-qty="1">Take 1</button>';
                if (sQty >= 5) html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeWithdraw" data-id="' + houseId + '" data-key="' + sk + '" data-qty="5">5</button>';
                html += '<button class="btn-trade buy" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeWithdraw" data-id="' + houseId + '" data-key="' + sk + '" data-qty="' + sQty + '">All</button>';
                html += '</div>';
            }
        }
        if (!hasStored) html += '<div style="color:#888;font-size:0.8rem;">Empty</div>';

        // Player inventory — deposit buttons
        html += '<h4 style="margin:12px 0 4px;">Your Inventory</h4>';
        var hasInv = false;
        var inv = Player.inventory || {};
        for (var ik in inv) {
            if (inv[ik] <= 0) continue;
            var ir = findResource(ik);
            if (!ir) continue;
            if (ir.category === 'livestock' || ik === 'horses') continue;
            hasInv = true;
            var iName = (ir.icon || '') + ' ' + ir.name;
            var iQty = inv[ik];
            html += '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;font-size:0.8rem;">';
            html += '<span style="min-width:140px;">' + iName + ': ' + iQty + '</span>';
            html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeDeposit" data-id="' + houseId + '" data-key="' + ik + '" data-qty="1">Store 1</button>';
            if (iQty >= 5) html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeDeposit" data-id="' + houseId + '" data-key="' + ik + '" data-qty="5">5</button>';
            html += '<button class="btn-trade sell" style="font-size:0.65rem;padding:1px 6px;" data-action="_homeDeposit" data-id="' + houseId + '" data-key="' + ik + '" data-qty="' + iQty + '">All</button>';
            html += '</div>';
        }
        if (!hasInv) html += '<div style="color:#888;font-size:0.8rem;">Nothing to store</div>';

        html += '</div>';
        openModal('📦 ' + (ht ? ht.name : 'Home') + ' Storage', html,
            '<button class="btn-medieval" data-action="openHousingDialog">Back</button>');
    }

    function _homeDeposit(houseId, resId, qty) {
        var result = Player.depositToHome(houseId, resId, qty);
        toast(result.message, result.success ? 'success' : 'error');
        openHomeStorageUI(houseId);
    }

    function _homeWithdraw(houseId, resId, qty) {
        var result = Player.withdrawFromHome(houseId, resId, qty);
        toast(result.message, result.success ? 'success' : 'error');
        openHomeStorageUI(houseId);
    }

    function stableHorseUI(houseId) {
        var result = Player.stableHorseAtHome(houseId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) openHousingDialog();
    }

    function unstableHorseUI(houseId, horseIdx) {
        var result = Player.unstableHorseFromHome(houseId, horseIdx);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) openHousingDialog();
    }

    function buyHouseUI(housingTypeId) {
        var result = Player.buyHouse(housingTypeId, Player.townId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) openHousingDialog();
    }

    function sellHouseUI(houseId) {
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }
        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        if (!ht) { toast('Unknown housing type.', 'error'); return; }

        // Calculate max price and recommended price
        var maxPrice = Engine.getPropertyMaxBuyPrice({ _isHouse: true, houseType: house.type }, house.townId);
        var discountLow = 0.05, discountHigh = 0.30;
        var discountPct = discountLow + Math.random() * (discountHigh - discountLow);
        var recommendedPrice = Math.max(1, Math.floor(maxPrice * (1 - discountPct)));
        var hasAppraiser = Player.hasSkill && Player.hasSkill('property_appraiser');

        var html = '<div>';
        html += '<div style="margin-bottom:8px;font-size:0.85rem;">' + ht.icon + ' <b>' + ht.name + '</b>';
        var town = Engine.findTown(house.townId);
        if (town) html += ' in ' + town.name;
        html += '</div>';

        html += '<div style="border:1px solid #555;padding:8px;border-radius:4px;margin-bottom:10px;background:rgba(0,0,0,0.2);">';
        html += '<div style="font-size:0.82rem;margin-bottom:4px;">💰 <b>Recommended price:</b> <span style="color:#5ac85a;">' + recommendedPrice + 'g</span> <span style="font-size:0.7rem;color:#aaa;">(5-30% below max)</span></div>';
        if (hasAppraiser) {
            html += '<div style="font-size:0.82rem;margin-bottom:4px;">📊 <b>Max buyer will pay:</b> <span style="color:#ffd700;">' + maxPrice + 'g</span></div>';
        } else {
            html += '<div style="font-size:0.82rem;margin-bottom:4px;color:#888;">📊 Max buyer price: ??? <span style="font-size:0.7rem;">(learn Property Appraiser to reveal)</span></div>';
        }
        html += '</div>';

        html += '<div style="margin-bottom:8px;">';
        html += '<label style="font-size:0.82rem;">Set your asking price (leave blank for recommended):</label><br>';
        html += '<input id="houseSalePrice" type="number" value="' + recommendedPrice + '" min="1" style="width:120px;padding:4px;margin-top:4px;background:#1a1a2e;color:#eee;border:1px solid #555;border-radius:4px;font-size:0.85rem;"> g';
        html += '</div>';

        if (house.isRental && house.tenantId) {
            html += '<div style="color:#c44e52;font-size:0.78rem;margin-bottom:6px;">⚠️ This property has a tenant. Selling will evict them.</div>';
        }

        html += '<div style="font-size:0.72rem;color:#888;">Note: If the price is too high, no one will buy it. Higher prices take longer to sell. Lower prices sell faster.</div>';
        html += '</div>';

        var footer = '<button class="btn-medieval" data-action="confirmSellHouseUI" data-id="' + houseId + '" style="margin-right:8px;">📋 List For Sale</button>';
        footer += '<button class="btn-medieval" data-action="quickSellHouseUI" data-id="' + houseId + '" style="margin-right:8px;color:#c4a35a;">⚡ Quick Sell (' + recommendedPrice + 'g)</button>';
        footer += '<button class="btn-medieval" data-action="closeModal">Cancel</button>';
        openModal('🏚️ Sell ' + ht.name, html, footer);
    }

    function confirmSellHouseUI(houseId) {
        var priceEl = document.getElementById('houseSalePrice');
        var price = priceEl ? parseInt(priceEl.value) : 0;
        if (!price || price < 1) {
            toast('Enter a valid price.', 'warning');
            return;
        }
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }

        // Mark house for sale (AI will buy it over time via tickPlayerPropertySales)
        house.forSale = true;
        house.salePrice = price;
        house.salePriceSetDay = Engine.getDay();

        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        var hName = ht ? ht.name : 'House';
        Engine.logEvent('📋 ' + (Player.state.fullName || 'Player') + ' listed ' + hName + ' for sale at ' + price + 'g.');
        toast('📋 ' + hName + ' listed for ' + price + 'g. A buyer will come if the price is right.', 'success');
        closeModal();
        openHousingDialog();
    }

    function quickSellHouseUI(houseId) {
        var result = Player.sellHouse(houseId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) { closeModal(); openHousingDialog(); }
    }

    function leaveTentUI(houseId) {
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { toast('Tent not found.', 'error'); return; }
        var html = '<div style="font-size:0.85rem;margin-bottom:10px;">Are you sure you want to leave this tent? It will be freed up for someone else.</div>';
        html += '<div style="font-size:0.78rem;color:#888;">You won\'t get any gold back — you\'re just stopping your rental.</div>';
        var footer = '<button class="btn-medieval" data-action="confirmLeaveTent" data-id="' + houseId + '" style="margin-right:8px;color:#c44e52;">🚪 Leave</button>';
        footer += '<button class="btn-medieval" data-action="closeModal">Cancel</button>';
        openModal('🚪 Leave Tent', html, footer);
    }

    function confirmLeaveTent(houseId) {
        var result = Player.leaveTent(houseId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) { closeModal(); openHousingDialog(); }
    }

    function upgradeHouseUI(houseId) {
        // Show upgrade options — list housing types more expensive than current
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'danger'); return; }
        var currentHt = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        if (!currentHt) return;
        var currentCostInfo = Player.getHousingCost(house.type, house.townId);
        var discount = CONFIG.HOUSING_UPGRADE_DISCOUNT || 0.60;
        var credit = Math.floor(currentCostInfo.total * discount);

        var html = '<div style="max-height:400px;overflow-y:auto;">';
        html += '<div style="margin-bottom:8px;">Current: <b>' + currentHt.icon + ' ' + currentHt.name + '</b> (value: ' + currentCostInfo.total.toFixed(2) + 'g, credit: ' + credit.toFixed(2) + 'g)</div>';
        var hasOptions = false;
        for (var i = 0; i < CONFIG.HOUSING_TYPES.length; i++) {
            var ht = CONFIG.HOUSING_TYPES[i];
            if (ht.id === house.type || !ht.materials) continue;
            if (ht.id === 'bedroll' || ht.id === 'inn_room') continue;
            var newCostInfo = Player.getHousingCost(ht.id, house.townId);
            if (newCostInfo.total <= currentCostInfo.total) continue;
            var upgCost = Math.max(0, newCostInfo.total - credit);
            var canUpg = newCostInfo.available && Player.gold >= upgCost;
            hasOptions = true;
            html += '<div style="border:1px solid #444;padding:6px;margin:3px 0;border-radius:4px;opacity:' + (canUpg ? '1' : '0.5') + ';">';
            html += ht.icon + ' <b>' + ht.name + '</b> — <span style="color:#ffd700;">' + upgCost.toFixed(2) + 'g</span> <span class="text-dim" style="font-size:0.7rem;">(full: ' + newCostInfo.total.toFixed(2) + 'g - ' + credit.toFixed(2) + 'g credit)</span><br>';
            html += '<span style="font-size:0.75rem;color:#aaa;">' + ht.description + '</span><br>';
            html += '<button class="btn-medieval" data-action="doUpgradeHouse" data-id="' + houseId + '" data-val="' + ht.id + '" style="font-size:0.75rem;padding:3px 8px;margin-top:2px;"' + (canUpg ? '' : ' disabled') + '>🏗️ Upgrade (' + upgCost.toFixed(2) + 'g)</button>';
            if (!newCostInfo.available) html += ' <span style="color:#c44e52;font-size:0.7rem;">Missing materials</span>';
            html += '</div>';
        }
        if (!hasOptions) html += '<p class="text-dim">No upgrades available for this location.</p>';
        html += '</div>';
        openModal('🏗️ Upgrade ' + currentHt.name, html, '<button class="btn-medieval" data-action="closeModal">Cancel</button>');
    }

    function doUpgradeHouse(houseId, newTypeId) {
        var result = Player.upgradeHouse(houseId, newTypeId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) { closeModal(); openHousingDialog(); }
    }

    function setPrimaryHouseUI(houseId) {
        var result = Player.setPrimaryHouse(houseId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) openHousingDialog();
    }

    function rentOutHouseUI(houseId) {
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { toast('House not found.', 'error'); return; }

        // If already renting, toggle off (which may trigger eviction)
        if (house.isRental) {
            var result = Player.rentOutHouse(houseId);
            toast(result.message, result.success ? 'success' : 'error');
            if (result.success) openHousingDialog();
            return;
        }

        // Show rent price setting dialog
        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        var recommended = 0;
        try { recommended = Player.getRecommendedRent(house); } catch(e) { recommended = 5; }
        var maxRent = 0;
        try { maxRent = Player.getMaxRentWillingness(house); } catch(e) {}
        var hasAppraiser = Player.hasSkill && Player.hasSkill('rental_appraiser');

        var html = '<div style="padding:8px;">';
        html += '<h3>💰 Set Rental Price</h3>';
        html += '<div style="margin:4px 0;">' + (ht ? ht.icon + ' ' + ht.name : 'Property') + '</div>';
        html += '<div style="margin:8px 0;">Recommended monthly rent: <b style="color:#ffd700;">' + recommended + 'g</b></div>';
        if (hasAppraiser) {
            html += '<div style="margin:4px 0;font-size:0.8rem;">🏷️ Max any tenant will pay: <b style="color:#55a868;">' + maxRent + 'g</b></div>';
        }
        html += '<div style="margin:8px 0;"><label>Monthly rent: </label><input type="number" id="rentalPrice" value="' + recommended + '" min="1" style="width:80px;padding:2px 4px;background:#222;color:#eee;border:1px solid #555;border-radius:3px;"> g/month</div>';
        html += '<div style="font-size:0.75rem;color:#aaa;margin-bottom:8px;">You can change the price once per day.</div>';
        html += '<button class="btn-medieval" data-action="rentOutHouse" data-id="' + houseId + '">💰 List For Rent</button>';
        html += '</div>';
        openModal('💰 Rent Property', html);
    }

    function evictTenantUI(houseId) {
        var house = (Player.state.houses || []).find(function(h) { return h.id === houseId; });
        if (!house || !house.tenantId) { toast('No tenant to evict.', 'warning'); return; }
        var tenant = Engine.findPerson(house.tenantId);
        var tName = tenant ? ((tenant.firstName || '') + ' ' + (tenant.lastName || '')) : 'tenant';
        var html = '<div style="padding:8px;">';
        html += '<p>Are you sure you want to evict <b>' + tName + '</b>?</p>';
        html += '<p style="font-size:0.8rem;color:#aaa;">The tenant will stay until 30 days from their last rent payment.</p>';
        html += '<div style="display:flex;gap:8px;margin-top:8px;">';
        html += '<button class="btn-medieval" style="color:#c44e52;" data-action="evictTenant" data-id="' + houseId + '">🚪 Confirm Eviction</button>';
        html += '<button class="btn-medieval" data-action="closeModal">Cancel</button>';
        html += '</div></div>';
        openModal('🚪 Evict Tenant', html);
    }

    function showRentNegotiations() {
        var negotiations = Player.state.rentNegotiations || [];
        if (negotiations.length === 0) { toast('No pending rent negotiations.', 'info'); return; }

        var html = '<div style="max-height:400px;overflow-y:auto;">';
        for (var i = 0; i < negotiations.length; i++) {
            var neg = negotiations[i];
            html += '<div style="border:1px solid #555;padding:8px;margin:4px 0;border-radius:4px;">';
            html += '<div><strong>💬 ' + neg.tenantName + '</strong></div>';
            html += '<div style="font-size:0.8rem;color:#aaa;">Cannot afford current rent of <b>' + neg.currentRent + 'g/month</b></div>';
            html += '<div style="font-size:0.8rem;">Requests: <b style="color:#ffd700;">' + neg.requestedRent + 'g/month</b></div>';
            html += '<div style="display:flex;gap:4px;margin-top:6px;flex-wrap:wrap;">';
            html += '<button class="btn-medieval" style="font-size:0.72rem;" data-action="acceptRentNegotiation" data-id="' + neg.houseId + '">✅ Accept (' + neg.requestedRent + 'g)</button>';
            html += '<button class="btn-medieval" style="font-size:0.72rem;" data-action="counterOfferRent" data-param1="' + Math.floor((neg.currentRent + neg.requestedRent) / 2) + '" data-id="' + neg.houseId + '">🤝 Counter</button>';
            html += '<button class="btn-medieval" style="font-size:0.72rem;color:#c44e52;" data-action="rejectRentNegotiation" data-id="' + neg.houseId + '">❌ Reject</button>';
            html += '</div></div>';
        }
        html += '</div>';
        openModal('💬 Rent Negotiations', html);
    }

    var _buyLandOrigin = null; // 'build' or null (housing)

    function buyLandUI() {
        var townId = Player.townId;
        // Remember where we came from before replacing the modal
        _buyLandOrigin = _wasOpenedFromBuildDialog() ? 'build' : null;
        var sub = Player.getActiveSubsidy ? Player.getActiveSubsidy(townId) : null;
        if (sub) {
            // Show choice dialog: subsidized vs full price
            var fullCost = Player.getLandCost(townId);
            var subCost = Player.getSubsidizedLandCost ? Player.getSubsidizedLandCost(townId) : fullCost;
            var bt = Engine.findBuildingType(sub.buildingType);
            var btName = bt ? bt.name : sub.buildingType;
            var discount = Math.round(sub.discount * 100);
            var html = '<div style="padding:8px;">';
            html += '<p style="margin-bottom:12px;">This town has an active <strong>Royal Land Subsidy</strong>! You can buy land at a discount, but it will be <strong>locked</strong> to building a <strong>' + btName + '</strong>.</p>';
            html += '<div style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center;">';
            html += '<button class="btn-medieval" style="padding:8px 16px;font-size:0.85rem;" data-action="_buyLandSubsidized">🏗️ Subsidized Land<br><span style="font-size:0.75rem;color:#2d6b3f;text-shadow:0 1px 0 rgba(255,255,255,0.3);">' + subCost + 'g (' + discount + '% off) — locked to ' + btName + '</span></button>';
            html += '<button class="btn-medieval" style="padding:8px 16px;font-size:0.85rem;" data-action="_buyLandFull">🏗️ Regular Land<br><span style="font-size:0.75rem;color:#ccc;">' + fullCost + 'g — build anything</span></button>';
            html += '</div></div>';
            openModal('🏗️ Buy Land', html);
        } else {
            var result = Player.buyLand(Player.townId, false);
            toast(result.message, result.success ? 'success' : 'error');
            if (result.success) {
                _refreshAfterLandChange(_buyLandOrigin === 'build');
                _buyLandOrigin = null;
                update();
            }
        }
    }

    function _buyLandSubsidized() {
        var _fromBuild = _buyLandOrigin === 'build';
        closeModal();
        var result = Player.buyLand(Player.townId, true);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) {
            _refreshAfterLandChange(_fromBuild);
            update();
        }
        _buyLandOrigin = null;
    }

    function _buyLandFull() {
        var _fromBuild = _buyLandOrigin === 'build';
        closeModal();
        var result = Player.buyLand(Player.townId, false);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) {
            _refreshAfterLandChange(_fromBuild);
            update();
        }
        _buyLandOrigin = null;
    }

    /** Check if the current modal was opened from the build dialog */
    function _wasOpenedFromBuildDialog() {
        var titleEl = document.getElementById('modalTitle');
        var titleText = titleEl ? titleEl.textContent : '';
        return titleText.indexOf('Build') !== -1 || titleText.indexOf('Buy Land') !== -1;
    }

    /** After buying/selling land, refresh whichever dialog is currently open */
    function _refreshAfterLandChange(fromBuild) {
        if (fromBuild === undefined) {
            fromBuild = _wasOpenedFromBuildDialog();
        }
        if (fromBuild && typeof UI !== 'undefined' && UI.openBuildDialog) {
            UI.openBuildDialog();
        } else {
            openHousingDialog();
        }
    }

    function sellLandUI() {
        var result = Player.sellLand(Player.townId);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) _refreshAfterLandChange();
    }

    // ═══════════════════════════════════════════════════════════
    //  TALK TO TOWNSFOLK DIALOG
    // ═══════════════════════════════════════════════════════════
    function talkToTownsfolk() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot talk while traveling.', 'warning'); return; }
        if (!Player.townId) { toast('You must be in a town to talk to people.', 'warning'); return; }

        var result = Player.talkToTownsfolk();
        if (!result || !result.success) {
            toast((result && result.message) || 'Nobody wants to talk right now.', 'warning');
            return;
        }

        // v9p33river489: open full NPC interaction panel instead of
        // simple quote modal.  If we got a real NPC, show their detail
        // panel on the right and open the interaction modal with the
        // intro flavor text + social buttons.
        if (result.npcId) {
            var npc = null;
            try { npc = Engine.getPerson(result.npcId); } catch(e) {}
            if (npc) {
                // Show NPC detail panel on the right
                if (UI.showPersonDetail) UI.showPersonDetail(npc);
                // Open interaction modal with intro text + switch button
                talkToPerson(result.npcId, {
                    introText: result.message,
                    introIcon: result.icon || '💬',
                    introType: result.type || 'flavor',
                    showSwitchButton: true
                });
                return;
            }
        }
        // Fallback for null NPC (empty/tiny towns)
        _showTalkResult(result);
    }

    function _showTalkResult(result) {
        // Build a nice chat bubble display
        var html = '<div style="text-align:center;margin-bottom:16px;">';
        html += '<div style="font-size:1.5rem;margin-bottom:4px;">' + (result.icon || '💬') + '</div>';
        html += '<div style="font-size:0.85rem;color:var(--gold);">' + result.speaker + '</div>';
        html += '<div style="font-size:0.7rem;color:#888;margin-bottom:12px;text-transform:capitalize;">' + result.occupation + '</div>';
        html += '</div>';

        html += '<div style="background:rgba(255,255,255,0.05);border-left:3px solid ' + (result.type === 'useful' ? 'var(--gold)' : 'rgba(255,255,255,0.2)') + ';padding:10px 14px;border-radius:4px;font-style:italic;font-size:0.82rem;line-height:1.5;margin-bottom:12px;">';
        html += result.message;
        html += '</div>';

        if (result.type === 'useful') {
            html += '<div style="text-align:center;font-size:0.7rem;color:var(--gold);margin-bottom:8px;">📌 Useful information!</div>';
        }

        html += '<div style="text-align:center;">';
        html += '<button class="btn-medieval" data-action="talkToTownsfolk" style="padding:6px 16px;margin-right:8px;">Talk to Someone Else</button>';
        html += '<button class="btn-medieval" data-action="closeModal" style="padding:6px 16px;">Done</button>';
        html += '</div>';

        openModal('💬 Conversation', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  REST DIALOG
    // ═══════════════════════════════════════════════════════════
    function openRestDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot rest while traveling.', 'warning'); return; }

        var energy = Player.energy != null ? Player.energy : 100;
        var maxEnergy = Player.maxEnergy || 100;
        var energyPct = Math.max(0, Math.min(100, (energy / maxEnergy) * 100));
        var thirst = Player.thirst != null ? Player.thirst : 80;

        var html = '<div style="text-align:center;">';
        html += '<h3>⚡ Energy: ' + Math.floor(energy) + '/' + maxEnergy + '</h3>';
        html += '<div class="bar-small" style="width:240px;margin:8px auto;"><div class="bar-small-fill" style="width:' + energyPct + '%;background:' + (energyPct > 60 ? '#55a868' : energyPct > 40 ? '#ccb974' : energyPct > 20 ? '#e8a040' : '#c44e52') + '"></div></div>';
        html += '<h4 style="margin-top:6px;">💧 Thirst: ' + Math.floor(thirst) + '/100</h4>';
        html += '<div class="bar-small" style="width:180px;margin:6px auto;"><div class="bar-small-fill" style="width:' + thirst + '%;background:' + (thirst > 60 ? '#4488cc' : thirst > 30 ? '#cc8844' : '#c44e52') + '"></div></div>';

        // Get available rest options from Player
        var restOptions = [];
        if (Player.getAvailableRestOptions) {
            restOptions = Player.getAvailableRestOptions();
        }

        // Auto-rest toggle
        var arChecked = Player.autoRest ? 'checked' : '';
        html += '<div style="margin:10px 0 6px;padding:6px 12px;background:rgba(85,168,104,0.1);border:1px solid rgba(85,168,104,0.25);border-radius:6px;display:inline-flex;align-items:center;gap:8px;">';
        html += '<label style="font-size:0.85rem;color:#ccc;cursor:pointer;display:flex;align-items:center;gap:6px;">';
        html += '<input type="checkbox" ' + arChecked + ' onchange="(function(cb){var r=Player.setAutoRest(cb.checked);UI.toast(r.message,r.success?\'success\':\'info\');})(this)">';
        html += '💤 Auto-rest when energy &lt; 10 (cheapest first, then best)</label>';
        html += '</div>';

        if (restOptions.length > 0) {
            html += '<h4 style="margin-top:12px;">🛏️ Rest Options</h4>';
            for (var i = 0; i < restOptions.length; i++) {
                var opt = restOptions[i];
                var ticksToFull = Math.ceil((maxEnergy - energy) / opt.energyPerTick);
                var costNote = opt.cost > 0 ? ' — ' + opt.cost + 'g' : ' — Free';
                html += '<div style="margin:6px 0;">';
                html += '<button class="btn-medieval" data-action="restUI" data-id="' + opt.id + '" style="padding:6px 16px;width:90%;">';
                html += (opt.icon || '') + ' ' + opt.name + costNote;
                html += '</button>';
                html += '<div style="font-size:0.75rem;color:#aaa;">+' + opt.energyPerTick.toFixed(1) + ' energy/tick · ~' + ticksToFull + ' ticks to full';
                if (opt.risk) html += ' · ⚠️ ' + opt.risk;
                html += '</div></div>';
            }
        } else {
            // Fallback if getAvailableRestOptions not available
            html += '<div style="margin:8px 0;"><button class="btn-medieval" data-action="sleepOutsideUI" style="padding:8px 20px;">🌙 Sleep Outside (free, disease risk)</button></div>';
        }

        // Draw water button — only if there's an active (non-depleted) well or outpost well upgrade
        var town = Engine.findTown(Player.townId);
        var hasOutpostWell = town && town.isOutpost && town.outpostUpgrades && town.outpostUpgrades.indexOf('well') >= 0;
        if (town && (hasOutpostWell || (town.buildings && town.buildings.length > 0))) {
            var activeWells = town.buildings ? town.buildings.filter(function(b) { return b.type === 'well' && !b.depleted; }) : [];
            var hasCistern = town.buildings ? town.buildings.some(function(b) { return b.type === 'cistern'; }) : false;
            if (activeWells.length > 0 || hasCistern || hasOutpostWell) {
                var kingdom = Engine.findKingdom(town.kingdomId);
                var isFree = hasOutpostWell || (kingdom && kingdom.laws && kingdom.laws.freeWellWater);
                html += '<div style="margin:12px 0;border-top:1px solid #555;padding-top:8px;">';
                html += '<button class="btn-medieval" data-action="drawWaterUI" style="padding:6px 16px;">💧 Draw Water from Well' + (isFree ? ' (Free)' : ' (1g)') + '</button>';
                if (hasOutpostWell) {
                    html += '<div style="font-size:0.75rem;color:#5ac85a;margin-top:4px;">🪣 Outpost Well — unlimited fresh water</div>';
                }
                // Show well water levels for regular wells
                for (var _wwi = 0; _wwi < activeWells.length; _wwi++) {
                    var _w = activeWells[_wwi];
                    if (_w.waterCapacity) {
                        var _pct = Math.round((_w.waterRemaining / _w.waterCapacity) * 100);
                        var _color = _pct > 50 ? '#5ac85a' : (_pct > 15 ? '#d4a844' : '#c44e52');
                        html += '<div style="font-size:0.75rem;color:' + _color + ';margin-top:4px;">🪣 Well ' + (_wwi + 1) + ': ' + Math.floor(_w.waterRemaining).toLocaleString() + '/' + _w.waterCapacity.toLocaleString() + ' (' + _pct + '%)</div>';
                    }
                }
                html += '</div>';
            } else {
                var depletedWells = town.buildings.filter(function(b) { return b.type === 'well' && b.depleted; });
                if (depletedWells.length > 0) {
                    html += '<div style="margin:12px 0;border-top:1px solid #555;padding-top:8px;">';
                    html += '<div style="font-size:0.8rem;color:#c44e52;">🪣 All wells have run dry! No water available.</div>';
                    html += '</div>';
                }
            }
        }

        html += '</div>';
        openModal('💤 Rest & Recovery', html);
    }

    function restUI(locationId) {
        if (!Player.restForTicks) { toast('Rest system not available.', 'error'); return; }
        // Pass a large tick count — restForTicks clamps to what's needed for full energy
        var result = Player.restForTicks(locationId, 9999);
        toast(result.message, result.success ? 'success' : 'error');
        if (result.success) {
            window._tutorialRested = true;
            if (typeof StoryMode !== 'undefined' && StoryMode.onPlayerAction) {
                StoryMode.onPlayerAction('rest', { locationId: locationId });
            }
        }
        closeModal();
    }

    function drawWaterUI() {
        if (!Player.drawWaterFromWell) { toast('Draw water not available.', 'error'); return; }
        var result = Player.drawWaterFromWell();
        toast(result.message, result.success ? 'success' : 'error');
        closeModal();
    }

    function restAtHomeUI() {
        var result = Player.restAtHome(Player.townId);
        toast(result.message, result.success ? 'success' : 'error');
        closeModal();
    }

    function restAtInnUI() {
        var result = Player.restAtInn(Player.townId);
        toast(result.message, result.success ? 'success' : 'error');
        closeModal();
    }

    function sleepOutsideUI() {
        var result = Player.sleepOutside();
        toast(result.message, result.success ? 'success' : 'error');
        closeModal();
    }

    function hireEscortUI() {
        var result = Player.hireArmedEscort(7);
        toast(result.message, result.success ? 'success' : 'error');
        closeModal();
    }

    // ═══════════════════════════════════════════════════════════
    //  OUTPOST MANAGEMENT → js/modules/ui_outpost.js
    //  OFF-SEA TRAVEL UI  → js/modules/ui_outpost.js
    //  SKILLS DIALOG      → js/modules/ui_outpost.js
    // ═══════════════════════════════════════════════════════════
    // ═══════════════════════════════════════════════════════════
    //  ACHIEVEMENTS DIALOG
    // ═══════════════════════════════════════════════════════════
    let _achCategory = 'trading';
    let _achTierFilter = 'all';

    var _tierBadges = {
        bronze: { icon: '🥉', color: '#cd7f32', bg: 'rgba(205,127,50,0.15)', border: 'rgba(205,127,50,0.4)', glow: '' },
        silver: { icon: '🥈', color: '#c0c0c0', bg: 'rgba(192,192,192,0.12)', border: 'rgba(192,192,192,0.35)', glow: '' },
        gold: { icon: '🥇', color: '#ffd700', bg: 'rgba(255,215,0,0.12)', border: 'rgba(255,215,0,0.4)', glow: '' },
        platinum: { icon: '💎', color: '#b0e0e6', bg: 'rgba(176,224,230,0.12)', border: 'rgba(176,224,230,0.5)', glow: 'box-shadow:0 0 8px rgba(176,224,230,0.4);' }
    };

    // ── Achievement Unlock Popup ──
    var _achPopupQueue = [];
    var _achPopupActive = false;

    function showAchievementPopup(achievementId) {
        var ach = ACHIEVEMENTS[achievementId];
        if (!ach) return;
        _achPopupQueue.push({ id: achievementId, ach: ach });
        if (!_achPopupActive) _showNextAchPopup();
    }

    function _showNextAchPopup() {
        if (_achPopupQueue.length === 0) { _achPopupActive = false; return; }
        _achPopupActive = true;
        var item = _achPopupQueue.shift();
        var ach = item.ach;
        var achId = item.id;
        var tier = ach.tier || 'bronze';
        var tb = _tierBadges[tier] || _tierBadges.bronze;
        var isPlatinum = tier === 'platinum';

        // Remove any existing popup
        var existing = document.getElementById('ach-popup-overlay');
        if (existing && existing.parentNode) existing.parentNode.removeChild(existing);

        var overlay = document.createElement('div');
        overlay.id = 'ach-popup-overlay';
        overlay.style.cssText = 'position:fixed;top:60px;left:0;width:100%;z-index:99999;pointer-events:none;display:flex;justify-content:center;';

        // Tier-specific backgrounds
        var bgGradient, borderColor, shadowStyle, shimmerCss;
        if (isPlatinum) {
            bgGradient = 'linear-gradient(135deg, rgba(20,30,50,0.97), rgba(40,60,90,0.97), rgba(20,30,50,0.97))';
            borderColor = '#b0e0e6';
            shadowStyle = '0 0 30px rgba(176,224,230,0.6), 0 0 60px rgba(176,224,230,0.3), 0 4px 20px rgba(0,0,0,0.5)';
            shimmerCss = 'background:linear-gradient(110deg, transparent 30%, rgba(176,224,230,0.15) 45%, rgba(176,224,230,0.25) 50%, rgba(176,224,230,0.15) 55%, transparent 70%);background-size:200% 100%;animation:achShimmer 2s ease-in-out infinite;';
        } else if (tier === 'gold') {
            bgGradient = 'linear-gradient(135deg, rgba(40,30,10,0.95), rgba(60,45,15,0.95))';
            borderColor = '#ffd700';
            shadowStyle = '0 0 15px rgba(255,215,0,0.4), 0 4px 15px rgba(0,0,0,0.4)';
            shimmerCss = '';
        } else if (tier === 'silver') {
            bgGradient = 'linear-gradient(135deg, rgba(30,30,35,0.95), rgba(45,45,50,0.95))';
            borderColor = '#c0c0c0';
            shadowStyle = '0 0 10px rgba(192,192,192,0.3), 0 4px 12px rgba(0,0,0,0.4)';
            shimmerCss = '';
        } else {
            bgGradient = 'linear-gradient(135deg, rgba(35,25,15,0.95), rgba(50,35,20,0.95))';
            borderColor = '#cd7f32';
            shadowStyle = '0 0 8px rgba(205,127,50,0.3), 0 4px 10px rgba(0,0,0,0.4)';
            shimmerCss = '';
        }

        var popupHtml = '';
        popupHtml += '<div id="ach-popup-card" style="pointer-events:auto;cursor:pointer;position:relative;overflow:hidden;';
        popupHtml += 'background:' + bgGradient + ';';
        popupHtml += 'border:2px solid ' + borderColor + ';border-radius:12px;';
        popupHtml += 'box-shadow:' + shadowStyle + ';';
        popupHtml += 'padding:14px 24px;min-width:280px;max-width:420px;';
        popupHtml += 'animation:achSlideIn 0.4s ease-out;';
        popupHtml += 'transition:opacity 0.4s ease, transform 0.4s ease;"';
        popupHtml += ' data-action="_achPopupClick" data-id="' + achId + '">';

        // Shimmer overlay for platinum
        if (isPlatinum) {
            popupHtml += '<div style="position:absolute;top:0;left:0;width:100%;height:100%;' + shimmerCss + 'pointer-events:none;"></div>';
        }

        // Content
        popupHtml += '<div style="position:relative;z-index:1;display:flex;align-items:center;gap:14px;">';

        // Icon
        popupHtml += '<div style="font-size:2.2rem;' + (isPlatinum ? 'animation:achPulse 1.5s ease-in-out infinite;' : '') + '">' + escapeHtml(ach.icon) + '</div>';

        // Text
        popupHtml += '<div style="flex:1;">';
        popupHtml += '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:2px;color:' + tb.color + ';margin-bottom:2px;">' + tb.icon + ' ' + tier.toUpperCase() + ' ACHIEVEMENT</div>';
        popupHtml += '<div style="font-size:1rem;font-weight:bold;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,0.5);">' + escapeHtml(ach.name) + '</div>';
        popupHtml += '<div style="font-size:0.75rem;color:#bbb;margin-top:2px;">' + escapeHtml(ach.desc) + '</div>';
        popupHtml += '<div style="font-size:0.68rem;color:' + tb.color + ';margin-top:4px;">+' + ach.xp + ' XP</div>';
        popupHtml += '</div>';

        popupHtml += '</div>'; // flex container
        popupHtml += '</div>'; // card

        overlay.innerHTML = popupHtml;

        // Inject keyframe animations if not already present
        if (!document.getElementById('ach-popup-styles')) {
            var styleEl = document.createElement('style');
            styleEl.id = 'ach-popup-styles';
            styleEl.textContent = '@keyframes achSlideIn { 0% { opacity:0; transform:translateY(-30px) scale(0.95); } 100% { opacity:1; transform:translateY(0) scale(1); } }' +
                '@keyframes achShimmer { 0% { background-position:200% 0; } 100% { background-position:-200% 0; } }' +
                '@keyframes achPulse { 0%,100% { transform:scale(1); } 50% { transform:scale(1.15); } }';
            document.head.appendChild(styleEl);
        }

        document.body.appendChild(overlay);

        // Auto-dismiss after 5 seconds
        var popupTimeout = setTimeout(function() {
            _dismissAchPopup();
        }, 5000);

        overlay._popupTimeout = popupTimeout;
    }

    function _dismissAchPopup() {
        var overlay = document.getElementById('ach-popup-overlay');
        if (!overlay) { _achPopupActive = false; _showNextAchPopup(); return; }
        var card = document.getElementById('ach-popup-card');
        if (card) {
            card.style.opacity = '0';
            card.style.transform = 'translateY(-20px) scale(0.95)';
        }
        if (overlay._popupTimeout) clearTimeout(overlay._popupTimeout);
        setTimeout(function() {
            if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
            _achPopupActive = false;
            _showNextAchPopup();
        }, 400);
    }

    function _achPopupClick(achievementId) {
        var overlay = document.getElementById('ach-popup-overlay');
        if (overlay && overlay._popupTimeout) clearTimeout(overlay._popupTimeout);
        if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
        _achPopupActive = false;
        _achPopupQueue = [];
        // Navigate to achievements dialog filtered to show this achievement's category and tier
        var ach = ACHIEVEMENTS[achievementId];
        if (ach) {
            _achCategory = ach.category || 'trading';
            _achTierFilter = ach.tier || 'all';
            openAchievementsDialog(ach.category, ach.tier);
        }
    }


    function openAchievementsDialog(category, tierFilter) {
        if (typeof Player !== 'undefined' && Player.state && Player.state.storyMode) {
            Player.state.storyMode._viewedFeats = true;
            if (typeof StoryMode !== 'undefined' && StoryMode.tick) StoryMode.tick(Player.state);
        }
        if (category && typeof category === 'string') _achCategory = category;
        if (tierFilter !== undefined) _achTierFilter = tierFilter;

        const playerAch = Player.achievements || {};
        const totalUnlocked = Object.keys(playerAch).length;
        const totalAch = Object.keys(ACHIEVEMENTS).length;

        // Category tabs
        let tabsHtml = '';
        for (const [catId, info] of Object.entries(ACHIEVEMENT_CATEGORIES)) {
            const active = catId === _achCategory ? 'active' : '';
            const catAchs = Object.keys(ACHIEVEMENTS).filter(id => ACHIEVEMENTS[id].category === catId);
            const unlocked = catAchs.filter(id => playerAch[id]).length;
            tabsHtml += `<button class="skill-tab ${active}" data-action="openAchievementsDialog" data-id="${catId}">
                ${info.icon} ${info.name} <span class="skill-tab-count">${unlocked}/${catAchs.length}</span>
            </button>`;
        }

        // Tier filter buttons
        var tierFilterHtml = '<div style="display:flex;gap:4px;margin:6px 0;flex-wrap:wrap;">';
        var _tierOpts = [
            { id: 'all', label: 'All' },
            { id: 'bronze', label: '🥉 Bronze' },
            { id: 'silver', label: '🥈 Silver' },
            { id: 'gold', label: '🥇 Gold' },
            { id: 'platinum', label: '💎 Platinum' }
        ];
        for (var _ti = 0; _ti < _tierOpts.length; _ti++) {
            var _to = _tierOpts[_ti];
            var _tActive = _achTierFilter === _to.id ? 'background:var(--gold);color:#1a1a2e;' : '';
            tierFilterHtml += '<button class="btn-medieval" style="font-size:0.7rem;padding:3px 8px;' + _tActive + '" data-action="openAchievementsDialog" data-id="' + _achCategory + '" data-val="' + _to.id + '">' + _to.label + '</button>';
        }
        tierFilterHtml += '</div>';

        // Tier summary counts
        var _tierCounts = { bronze: { total: 0, unlocked: 0 }, silver: { total: 0, unlocked: 0 }, gold: { total: 0, unlocked: 0 }, platinum: { total: 0, unlocked: 0 } };
        for (var _aid in ACHIEVEMENTS) {
            var _aTier = ACHIEVEMENTS[_aid].tier || 'bronze';
            if (_tierCounts[_aTier]) {
                _tierCounts[_aTier].total++;
                if (playerAch[_aid]) _tierCounts[_aTier].unlocked++;
            }
        }
        var tierSummaryHtml = '<div style="display:flex;gap:8px;margin-bottom:6px;font-size:0.75rem;flex-wrap:wrap;">';
        for (var _ts in _tierCounts) {
            var _badge = _tierBadges[_ts];
            tierSummaryHtml += '<span style="color:' + _badge.color + ';">' + _badge.icon + ' ' + _tierCounts[_ts].unlocked + '/' + _tierCounts[_ts].total + '</span>';
        }
        tierSummaryHtml += '</div>';

        const categoryAchs = [];
        for (const id in ACHIEVEMENTS) {
            if (ACHIEVEMENTS[id].category === _achCategory) {
                if (_achTierFilter !== 'all' && (ACHIEVEMENTS[id].tier || 'bronze') !== _achTierFilter) continue;
                categoryAchs.push({ id, ...ACHIEVEMENTS[id] });
            }
        }

        // Sort: platinum first, then gold, silver, bronze; unlocked first within each tier
        var _tierOrder = { platinum: 0, gold: 1, silver: 2, bronze: 3 };
        categoryAchs.sort(function(a, b) {
            var aUnlocked = playerAch[a.id] ? 0 : 1;
            var bUnlocked = playerAch[b.id] ? 0 : 1;
            if (aUnlocked !== bUnlocked) return aUnlocked - bUnlocked;
            // v9p33river306: was `_tierOrder[x] || 3` — but _tierOrder.platinum
            // is 0, which is falsy, so `0 || 3` collapsed to 3 and platinum
            // sorted like bronze. Use explicit undefined check.
            var aT = _tierOrder[a.tier || 'bronze'];
            var bT = _tierOrder[b.tier || 'bronze'];
            var aTier = (aT == null) ? 3 : aT;
            var bTier = (bT == null) ? 3 : bT;
            return aTier - bTier;
        });

        let achHtml = '<div class="achievement-grid">';
        for (const ach of categoryAchs) {
            const isUnlocked = playerAch[ach.id];
            const stateClass = isUnlocked ? 'ach-unlocked' : 'ach-locked';
            const dayText = isUnlocked ? `Day ${isUnlocked.unlockedAt}` : '';
            var _tb = _tierBadges[ach.tier || 'bronze'] || _tierBadges.bronze;
            var _tierStyle = 'border-left:3px solid ' + _tb.border + ';background:' + _tb.bg + ';' + (ach.tier === 'platinum' && isUnlocked ? _tb.glow : '');

            achHtml += `<div class="achievement-card ${stateClass}" style="${_tierStyle}">
                <div class="ach-icon">${ach.icon}</div>
                <div class="ach-info">
                    <div class="ach-name">${_tb.icon} ${ach.name} ${isUnlocked ? '✅' : '🔒'}</div>
                    <div class="ach-desc">${ach.desc}</div>
                    <div class="ach-xp" style="color:${_tb.color}">+${ach.xp} XP <span style="font-size:0.65rem;opacity:0.7;">${(ach.tier || 'bronze').toUpperCase()}</span> ${dayText ? '• ' + dayText : ''}</div>
                </div>
            </div>`;
        }
        if (categoryAchs.length === 0) {
            achHtml += '<div style="text-align:center;color:var(--text-muted);padding:20px;">No achievements in this filter.</div>';
        }
        achHtml += '</div>';

        const html = `
            <div class="ach-header">
                <span class="ach-progress">🏆 ${totalUnlocked}/${totalAch} Achievements Unlocked</span>
                <span class="ach-xp-total">Total XP: ${formatGold(Player.totalXp || 0)}</span>
            </div>
            ${tierSummaryHtml}
            <div class="skill-tabs">${tabsHtml}</div>
            ${tierFilterHtml}
            ${achHtml}
        `;

        openModal('🏆 Achievements', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  MARKET INTEL (added to trade dialog)
    // ═══════════════════════════════════════════════════════════
    function buildMarketIntelHtml(currentTownId) {
        if (typeof Player === 'undefined') return '';

        const intel = Player.marketIntel || {};
        const hasIntelSkill = Player.hasSkill && (Player.hasSkill('market_scout') || Player.hasSkill('trade_network') || Player.hasSkill('global_trade_intel'));

        // Gather remote town intel
        const remoteTowns = [];
        for (const [townId, data] of Object.entries(intel)) {
            if (townId === currentTownId) continue;
            const town = Engine.findTown(townId);
            if (!town) continue;
            // v9p33river126: outposts have no market — skip them in intel
            if (town.isOutpost) continue;
            remoteTowns.push({ town, data });
        }

        if (remoteTowns.length === 0 && !hasIntelSkill) {
            return `<div class="market-intel-section">
                <h4>📊 Market Intel</h4>
                <div class="text-dim" style="font-size:0.8rem;">No market intelligence available. Learn the Market Scout skill or pay an Information Broker (${CONFIG.INFO_BROKER_COST || 10}g).</div>
                <button class="btn-trade buy" style="margin-top:6px;" data-action="buyInfoBrokerTip">💡 Buy Trade Tip (${CONFIG.INFO_BROKER_COST || 10}g)</button>
            </div>`;
        }

        let html = '<div class="market-intel-section"><h4>📊 Market Intel</h4>';

        if (!hasIntelSkill) {
            html += `<button class="btn-trade buy" style="margin-bottom:8px;" data-action="buyInfoBrokerTip">💡 Buy Trade Tip (${CONFIG.INFO_BROKER_COST || 10}g)</button>`;
        }

        if (remoteTowns.length > 0) {
            // Show condensed price comparison for profitable resources
            const currentTown = Engine.findTown(currentTownId);
            const currentPrices = currentTown ? currentTown.market.prices : {};

            html += '<div class="intel-table"><table class="intel-prices"><tr><th>Town</th><th>Best Buy</th><th>Best Sell</th><th>Updated</th></tr>';

            for (const { town, data } of remoteTowns.slice(0, 8)) {
                let bestBuy = null, bestSell = null;
                for (const resId in data.prices) {
                    const remotePrice = data.prices[resId] || 0;
                    const localPrice = currentPrices[resId] || 0;
                    if (localPrice > 0 && remotePrice > 0) {
                        const profitSelling = remotePrice - localPrice;
                        const profitBuying = localPrice - remotePrice;
                        if (profitSelling > 0 && (!bestSell || profitSelling > bestSell.profit)) {
                            const res = findResource(resId);
                            bestSell = { res, profit: profitSelling, price: remotePrice };
                        }
                        if (profitBuying > 0 && (!bestBuy || profitBuying > bestBuy.profit)) {
                            const res = findResource(resId);
                            bestBuy = { res, profit: profitBuying, price: remotePrice };
                        }
                    }
                }
                const kingdom = Engine.findKingdom(town.kingdomId);
                const kName = kingdom ? kingdom.name.substring(0, 8) : '';
                const daysSinceUpdate = Engine.getDay() - (data.updatedDay || 0);
                const updateText = daysSinceUpdate <= 1 ? 'Now' : `${daysSinceUpdate}d ago`;
                const _keenEyeD = typeof Player !== 'undefined' && Player.hasSkill && Player.hasSkill('keen_eye');
                const _dealClass = _keenEyeD ? 'good-deal' : 'neutral';
                html += `<tr>
                    <td title="${town.name} (${kName})">${town.name.substring(0, 12)}</td>
                    <td>${bestBuy ? `${bestBuy.res.icon}${Math.round(bestBuy.price * 10) / 10}g <span class="${_dealClass}">(+${Math.round(bestBuy.profit * 10) / 10})</span>` : '—'}</td>
                    <td>${bestSell ? `${bestSell.res.icon}${Math.round(bestSell.price * 10) / 10}g <span class="${_dealClass}">(+${Math.round(bestSell.profit * 10) / 10})</span>` : '—'}</td>
                    <td class="text-dim">${updateText}</td>
                </tr>`;
            }
            html += '</table></div>';
        }

        // Trade tip log
        const tipLog = (typeof Player !== 'undefined' && Player.tradeTipLog) ? Player.tradeTipLog : [];
        if (tipLog.length > 0) {
            const currentDay = (typeof Engine !== 'undefined' && Engine.getDay) ? Engine.getDay() : 0;
            html += '<div style="margin-top:8px;"><div style="font-weight:bold;font-size:0.82rem;margin-bottom:4px;">📝 Trade Tips</div>';
            html += '<div style="font-size:0.78rem;color:#bbb;">';
            const recentTips = tipLog.slice(-10).reverse();
            for (const tip of recentTips) {
                const daysAgo = currentDay - (tip.day || 0);
                const daysLeft = 30 - daysAgo;
                const ageText = daysAgo <= 0 ? 'today' : daysAgo + 'd ago';
                const expiryText = daysLeft <= 5 ? ' · expires in ' + daysLeft + 'd' : '';
                const freshClass = daysAgo <= 3 ? 'color:#c4a35a;' : daysAgo <= 10 ? 'color:#aaa;' : 'color:#777;';
                html += '<div style="margin-bottom:2px;' + freshClass + '">' + tip.message + ' <span style="font-size:0.7rem;opacity:0.7;">(' + ageText + expiryText + ')</span></div>';
            }
            html += '</div></div>';
        }

        html += '</div>';
        return html;
    }

    function buyInfoBrokerTip() {
        if (typeof Player === 'undefined' || !Player.getInfoBrokerTip) return;
        const tips = Player.getInfoBrokerTip();
        if (!tips) {
            toast('Not enough gold for a tip (' + (CONFIG.INFO_BROKER_COST || 10) + 'g).', 'warning');
            return;
        }
        if (tips.length === 0) {
            toast('The broker has no useful tips right now.', 'info');
            return;
        }
        var tip = tips[0];
        var msg = '💡 ' + tip.resource.icon + ' ' + tip.resource.name + ' sells for ' + Math.round(tip.remotePrice) + 'g in ' + tip.town.name;
        toast(msg, 'success');
        // Refresh trade panel to show new tip in market intel
        if (typeof refreshTradePanel === 'function') refreshTradePanel();
    }

    // ═══════════════════════════════════════════════════════════
    //  KINGDOM & TOWN SELECTION → js/modules/ui_kingdom.js
    // ═══════════════════════════════════════════════════════════

    // ═══════════════════════════════════════════════════════════
    //  LEADERBOARD
    // ═══════════════════════════════════════════════════════════

    function openLeaderboard() {
        if (typeof Player !== 'undefined' && Player.state && Player.state.storyMode) {
            Player.state.storyMode._viewedRankings = true;
            if (typeof StoryMode !== 'undefined' && StoryMode.tick) StoryMode.tick(Player.state);
        }
        // Use new Engine leaderboard if available, fallback to old
        var entries;
        if (typeof Engine !== 'undefined' && Engine.getLeaderboard) {
            entries = Engine.getLeaderboard();
        } else if (typeof Player !== 'undefined' && Player.getMerchantLeaderboard) {
            entries = Player.getMerchantLeaderboard();
        } else {
            return;
        }

        const kingdoms = Engine.getKingdoms();
        const kingdomMap = {};
        for (const k of kingdoms) kingdomMap[k.id] = k;
        const RANKS = CONFIG.SOCIAL_RANKS || [];
        const canSeeLocations = typeof Player !== 'undefined' && Player.canSeeEliteMerchantLocations && Player.canSeeEliteMerchantLocations();

        // Find player rank
        let playerRank = -1;
        for (let i = 0; i < entries.length; i++) {
            if (entries[i].isPlayer) { playerRank = i + 1; break; }
        }

        let html = '<div style="padding:15px;">';
        html += '<h3 style="color:#ffd700;text-align:center;margin-bottom:5px;">🏆 Merchant Leaderboard</h3>';
        if (playerRank > 0) {
            html += '<div style="text-align:center;font-size:0.8rem;color:#aaa;margin-bottom:12px;">You are ranked <b style="color:#ffd700;">#' + playerRank + '</b> of ' + entries.length + '</div>';
        }
        html += '<table style="width:100%;border-collapse:collapse;">';
        html += '<tr style="border-bottom:2px solid #555;">';
        html += '<th style="padding:8px;text-align:left;">#</th>';
        html += '<th style="text-align:left;">Name</th>';
        html += '<th style="text-align:center;">Strategy</th>';
        html += '<th style="text-align:center;">Rank</th>';
        if (canSeeLocations) html += '<th style="text-align:center;">Town</th>';
        html += '<th style="text-align:right;">Net Worth</th>';
        html += '<th style="text-align:center;">Track</th>';
        html += '</tr>';

        const strategyIcons = {
            'food_monopoly': '🌾', 'military_supplier': '⚔️', 'luxury_trader': '💎',
            'diversified': '📦', 'political_climber': '👑', 'war_profiteer': '🔥',
            'land_baron': '🏠', 'trade_network': '🗺️', 'Player': '🎮',
        };

        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            const medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : (i + 1);
            const rankIdx = e.highestRank || 0;
            const rankInfo = RANKS[rankIdx];
            const rankIcon = rankInfo ? rankInfo.icon : '🌾';
            const highlight = e.isPlayer ? 'background:rgba(255,215,0,0.15);' : '';
            const nameStyle = e.isPlayer ? 'color:#ffd700;font-weight:bold;' : 'color:#ddd;';
            const k = kingdomMap[e.primaryKingdom];
            const kName = k ? k.name : '—';
            const kColor = k ? (k.color || '#888') : '#888';
            const stratIcon = strategyIcons[e.strategy] || '📦';
            const heraldryStr = e.heraldry ? (e.heraldry.symbol + ' ') : '';
            const heraldryTitle = e.heraldry ? e.heraldry.name : '';

            html += '<tr style="border-bottom:1px solid #333;' + highlight + '">';
            html += '<td style="padding:8px;font-size:1.1rem;">' + medal + '</td>';
            html += '<td style="' + nameStyle + '"><span title="' + heraldryTitle + '">' + heraldryStr + '</span>' + e.name + (e.isPlayer ? ' (You)' : '') +
                '<br><span style="font-size:0.7rem;color:#888;">' + (e.familyName || '') + ' family • <span style="color:' + kColor + ';">' + kName + '</span>' +
                ' • ' + e.buildings + ' bldgs • ' + e.employees + ' workers</span></td>';
            html += '<td style="text-align:center;font-size:0.85rem;" title="' + (e.strategy || '') + '">' + stratIcon + '<br><span style="font-size:0.6rem;color:#aaa;">' + formatStrategy(e.strategy) + '</span></td>';
            html += '<td style="text-align:center;">' + rankIcon + '</td>';
            if (canSeeLocations) {
                let townName = '???';
                if (e.townId != null) {
                    try {
                        const eTown = Engine.findTown(e.townId);
                        townName = eTown ? eTown.name : '???';
                    } catch (ex) { /* no-op */ }
                }
                html += '<td style="text-align:center;font-size:0.75rem;color:#aaa;">' + townName + '</td>';
            }
            html += '<td style="text-align:right;color:#ffd700;font-weight:bold;">' + formatGold(e.netWorth || 0) + '</td>';
            // Track/Untrack button in leaderboard
            if (!e.isPlayer && typeof Player !== 'undefined' && Player.hasSkill && Player.hasSkill('merchant_tracker') && e.id) {
                var lbTracked = Player.isTrackingMerchant && Player.isTrackingMerchant(e.id);
                html += '<td style="text-align:center;"><button class="btn-medieval" style="font-size:0.6rem;padding:1px 5px;' + (lbTracked ? 'background:var(--gold);color:#000;' : '') + '" data-action="toggleLeaderboardTrack" data-method="' + (lbTracked ? 'untrackMerchant' : 'trackMerchant') + '" data-id="' + e.id + '">' + (lbTracked ? '⭐' : '☆') + '</button></td>';
            } else {
                html += '<td></td>';
            }
            html += '</tr>';
        }
        html += '</table>';

        // Alliance info section
        if (typeof Player !== 'undefined' && Player.getAllianceBenefits) {
            const alliances = Player.getAllianceBenefits();
            if (alliances.allianceCount > 0) {
                html += '<div style="margin-top:15px;padding:10px;border-top:1px solid #555;">';
                html += '<h4 style="color:#c0a0ff;margin:0 0 8px 0;">👑 Family Alliances (' + alliances.allianceCount + ')</h4>';
                const playerAlliances = Player.familyAlliances || [];
                for (let ai = 0; ai < playerAlliances.length; ai++) {
                    const a = playerAlliances[ai];
                    html += '<div style="font-size:0.8rem;color:#aaa;margin-bottom:4px;">• ' + (a.familyName || 'Unknown') + ' family (Day ' + a.startDay + ')</div>';
                }
                html += '<div style="font-size:0.75rem;color:#8f8;margin-top:6px;">Benefits: +' + alliances.repBonus + '% reputation, ' + Math.round(alliances.storageDiscount * 100) + '% storage discount</div>';
                html += '</div>';
            }
        }

        // Marriage proposals section
        if (typeof Player !== 'undefined' && Player.getMarriageProposals) {
            const proposals = Player.getMarriageProposals();
            if (proposals.length > 0) {
                html += '<div style="margin-top:15px;padding:10px;border-top:1px solid #555;">';
                html += '<h4 style="color:#ffa0a0;margin:0 0 8px 0;">💍 Marriage Proposals</h4>';
                for (let pi = 0; pi < proposals.length; pi++) {
                    const pr = proposals[pi];
                    html += '<div style="margin-bottom:8px;padding:6px;background:rgba(255,255,255,0.05);border-radius:4px;">';
                    html += '<div style="font-size:0.85rem;color:#ddd;">' + pr.eliteMerchantName + ' proposes: ' + pr.eliteChildName + ' wed ' + pr.playerChildName + '</div>';
                    html += '<button class="btn-medieval" style="font-size:0.7rem;padding:3px 10px;margin-top:4px;" data-action="respondToMarriageProposal" data-id="' + pr.id + '" data-val="true">✅ Accept</button> ';
                    html += '<button class="btn-medieval" style="font-size:0.7rem;padding:3px 10px;margin-top:4px;background:rgba(200,60,50,0.3);" data-action="respondToMarriageProposal" data-id="' + pr.id + '" data-val="false">❌ Reject</button>';
                    html += '</div>';
                }
                html += '</div>';
            }
        }

        html += '</div>';
        openModal('🏆 Merchant Leaderboard', html);
    }

    function respondToMarriageProposalUI(proposalId, accept) {
        if (typeof Player === 'undefined' || !Player.respondToMarriageProposal) return;
        var result = Player.respondToMarriageProposal(proposalId, accept);
        toast(result.message || (accept ? 'Marriage arranged!' : 'Proposal rejected.'), result.success ? 'success' : 'warning');
        if (result.success) openLeaderboard(); // Refresh
    }

    // ═══════════════════════════════════════════════════════════
    //  FIND WORK DIALOG
    // ═══════════════════════════════════════════════════════════

    function openWorkDialog() {
        if (typeof Player === 'undefined') return;
        if (Player.traveling) { toast('Cannot work while traveling.', 'warning'); return; }
        if (Player.workingUntilTick > Engine.getDay()) {
            toast('Already working! Finish on day ' + Player.workingUntilTick + '.', 'warning');
            return;
        }
        if (Player.jailedUntilDay > Engine.getDay()) {
            toast('Cannot work while in jail.', 'warning');
            return;
        }

        let html = '';

        // ── Military Career Section ──
        const wars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        const hasActiveWars = Object.keys(wars).length > 0;

        if (Player.militaryActive) {
            // Currently enlisted — show status panel
            const rankLabel = Player.getMilitaryRankLabel ? Player.getMilitaryRankLabel() : (Player.militaryRank || 'Soldier');
            const pay = Player.getMilitaryPay ? Player.getMilitaryPay() : 0;
            const kName = Player.militaryKingdomId ? (Engine.findKingdom(Player.militaryKingdomId) || {}).name || '?' : '?';
            html += '<div style="border:2px solid var(--danger);padding:10px;margin-bottom:12px;border-radius:6px;background:rgba(200,50,50,0.08);">';
            html += '<h3 style="margin:0 0 6px 0;">⚔️ Military Service — Active</h3>';
            html += '<div class="detail-row"><span class="label">Rank</span><span class="value">' + rankLabel + '</span></div>';
            html += '<div class="detail-row"><span class="label">Fighting for</span><span class="value">' + kName + '</span></div>';
            html += '<div class="detail-row"><span class="label">Battles Survived</span><span class="value">' + (Player.battlesSurvived || 0) + '</span></div>';
            html += '<div class="detail-row"><span class="label">Pay per Battle</span><span class="value">🪙 ' + pay + 'g</span></div>';
            // Show mandatory service info or quit button
            if (Player.militaryMandatory) {
                var milEndDay = Player.militaryServiceEndDay || 0;
                var curDay = Engine.getDay ? Engine.getDay() : 0;
                var milDaysLeft = Math.max(0, milEndDay - curDay);
                html += '<div style="margin-top:8px;padding:6px;background:rgba(200,150,0,0.15);border:1px solid rgba(200,150,0,0.3);border-radius:4px;font-size:0.8rem;">';
                html += '⚠️ <strong>Mandatory Service:</strong> ' + milDaysLeft + ' days remaining (' + (milDaysLeft / (CONFIG.DAYS_PER_SEASON || 90)).toFixed(1) + ' years). Cannot desert.';
                html += '</div>';
            } else {
                html += '<button class="btn-medieval" data-action="quitMilitary" style="margin-top:8px;font-size:0.8rem;padding:6px 16px;background:rgba(200,60,50,0.3);border-color:rgba(200,60,50,0.55);">🏠 Quit Military</button>';
            }
            html += '</div>';
            html += '<p class="text-dim">You cannot take other jobs while enlisted. Battles occur every 3-5 days automatically.</p>';
            openModal('💼 Find Work', html);
            return;
        }

        if (hasActiveWars) {
            html += '<div style="border:1px solid var(--gold);padding:10px;margin-bottom:12px;border-radius:6px;background:rgba(200,150,0,0.06);">';
            html += '<h3 style="margin:0 0 6px 0;">⚔️ Enlist as Soldier</h3>';
            html += '<p style="font-size:0.75rem;color:var(--text-muted);margin:0 0 8px 0;">Active wars detected! Join the fight for a kingdom. Earn gold, gain rank, risk death.</p>';
            // Show kingdoms at war
            const shownKingdoms = {};
            for (const wId in wars) {
                const w = wars[wId];
                for (const kId of [w.kingdomA, w.kingdomB]) {
                    if (shownKingdoms[kId]) continue;
                    shownKingdoms[kId] = true;
                    const k = Engine.findKingdom(kId);
                    if (!k) continue;
                    html += '<button class="btn-medieval" data-action="enlistAsSoldier" data-id="' + kId + '" style="font-size:0.75rem;padding:4px 12px;margin:2px;">';
                    html += '⚔️ Enlist for ' + k.name;
                    html += '</button> ';
                }
            }
            html += '</div>';
        }

        // Show military rank if any (even when not enlisted)
        if (Player.militaryRank && !Player.militaryActive) {
            const rankLabel = Player.getMilitaryRankLabel ? Player.getMilitaryRankLabel() : Player.militaryRank;
            html += '<div style="font-size:0.75rem;color:var(--text-muted);margin-bottom:8px;">🎖️ Military Rank: <strong>' + rankLabel + '</strong> (retired) — Battles survived: ' + (Player.battlesSurvived || 0) + '</div>';
        }

        html += '<p class="work-intro">Find work at local businesses to earn gold without traveling.</p>';

        // Show auto-work status if active
        if (Player.autoWork && Player.autoWork.active) {
            html += _getAutoWorkStatusHtml();
            // If it's a travel auto-work, also show the travel mission status
            if (Player.autoWork.isTravel && Player.autoTravelJob) {
                html += getAutoTravelStatusHtml();
            }
            openModal('💼 Find Work', html);
            return;
        }

        // Show auto-travel mission status if active
        if (Player.autoTravelJob) {
            html += getAutoTravelStatusHtml();
            openModal('💼 Find Work', html);
            return;
        }

        const jobs = Player.getAvailableJobs();

        if (jobs.length === 0) {
            html += '<p>No jobs available right now.</p>';
        } else {
            html += '<div class="job-list">';
            for (let i = 0; i < jobs.length; i++) {
                const job = jobs[i];
                const typeIcons = {
                    building: '🏢', odd: '🔧', kingdom: '👑', castle: '🏰',
                    apprentice: '📖', merchant: '🤝', kingdom_employee: '📋'
                };
                const typeIcon = typeIcons[job.type] || '🏢';
                const typeLabels = {
                    building: 'Building', odd: 'Odd Job', kingdom: 'Kingdom',
                    castle: 'Royal Court', apprentice: 'Apprentice', merchant: 'Merchant',
                    kingdom_employee: 'Kingdom Position'
                };
                const typeLabel = typeLabels[job.type] || '';

                // Risk indicators — show risk level badge
                let riskBadges = '';
                const riskLevel = job.riskLevel || (job.deathRisk ? 'high' : job.injuryRisk > 0.005 ? 'medium' : job.injuryRisk ? 'low' : (job.illnessRisk > 0.03 ? 'high' : job.illnessRisk ? 'medium' : ''));
                if (riskLevel === 'high') {
                    riskBadges += '<span style="font-size:0.7rem;color:#fff;background:#c0392b;margin-left:6px;padding:1px 5px;border-radius:3px;font-weight:bold;">⚠ High Risk</span>';
                } else if (riskLevel === 'medium') {
                    riskBadges += '<span style="font-size:0.7rem;color:#fff;background:#e67e22;margin-left:6px;padding:1px 5px;border-radius:3px;">⚡ Medium Risk</span>';
                } else if (riskLevel === 'low') {
                    riskBadges += '<span style="font-size:0.7rem;color:#fff;background:#27ae60;margin-left:6px;padding:1px 5px;border-radius:3px;">🛡 Low Risk</span>';
                }
                if (job.deathRisk) riskBadges += '<span style="font-size:0.7rem;color:var(--danger);margin-left:4px;">☠️</span>';
                if (job.injuryRisk) riskBadges += '<span style="font-size:0.7rem;color:#e67e22;margin-left:4px;">🩹</span>';
                if (job.illnessRisk) riskBadges += '<span style="font-size:0.7rem;color:#8e44ad;margin-left:4px;">🤒</span>';

                html += '<div class="job-item">';
                html += '<div class="job-info">';
                html += '<span class="job-name">' + typeIcon + ' ' + job.name + riskBadges + '</span>';
                if (typeLabel) {
                    html += '<span style="font-size:0.7rem;color:var(--text-muted);margin-left:6px;background:var(--bg-card);padding:1px 5px;border-radius:3px;">' + typeLabel + '</span>';
                }
                if (job.contextReason) {
                    html += '<span style="font-size:0.7rem;color:var(--gold);margin-left:4px;background:rgba(200,150,0,0.1);padding:1px 5px;border-radius:3px;">' + job.contextReason + '</span>';
                }
                if (job.autoTravel) {
                    html += '<span style="font-size:0.7rem;color:#60a5fa;margin-left:4px;background:rgba(96,165,250,0.12);padding:1px 5px;border-radius:3px;">🗺️ Auto-Travel</span>';
                }
                if (job.isOwnBuilding) {
                    html += '<span style="font-size:0.7rem;color:#2ecc71;margin-left:6px;background:rgba(46,204,113,0.1);padding:1px 5px;border-radius:3px;">🏠 Your Building</span>';
                }
                html += '<span class="job-details">⏱ ' + job.hours + ' hours';
                if (job.isOwnBuilding) {
                    html += ' — 📦 Produces goods for storage';
                } else {
                    html += ' — 🪙 ' + job.pay + 'g';
                }
                if (job.xpReward) html += ' — ⭐ ' + job.xpReward + ' XP';
                if (job.repGain) html += ' — 👑 +' + job.repGain + ' Rep';
                if (job.skillGain) html += ' — 📚 ' + job.skillGain;
                html += '</span>';
                if (job.description) {
                    html += '<span style="font-size:0.72rem;color:var(--text-muted);display:block;margin-top:2px;">' + job.description + '</span>';
                }
                // Skill learning progress
                if (job.jobTypeKey && Player.getJobSkillProgress) {
                    var prog = Player.getJobSkillProgress(job.jobTypeKey);
                    if (prog) {
                        html += '<span style="font-size:0.7rem;color:#2ecc71;display:block;margin-top:1px;">📚 ' + prog.current + '/' + prog.needed + ' days to learn ' + prog.skillName + '</span>';
                    }
                }
                html += '</div>';

                // Building selector dropdown — if multiple buildings of same type exist
                if (job.type === 'building' && job.buildingType) {
                    var _wTown = Engine.findTown(Player.townId);
                    if (_wTown) {
                        var _sameBlds = (_wTown.buildings || []).filter(function(b) {
                            return b.type === job.buildingType && b.ownerId !== 'player' &&
                                   b.condition !== 'destroyed' && b.condition !== 'under_construction';
                        });
                        if (_sameBlds.length > 1) {
                            html += '<div style="margin-top:3px;font-size:0.7rem;">';
                            html += '<label style="color:var(--text-muted);">Work at: </label>';
                            html += '<select id="bldSelect_' + i + '" style="font-size:0.7rem;background:var(--bg-card);color:var(--text);border:1px solid var(--border);border-radius:3px;padding:1px 4px;">';
                            for (var _si = 0; _si < _sameBlds.length; _si++) {
                                var _sb = _sameBlds[_si];
                                var _sbOwner = 'Unknown';
                                if (_sb.ownerId) {
                                    var _sbP = Engine.findPerson(_sb.ownerId);
                                    if (_sbP) _sbOwner = (_sbP.firstName || '') + ' ' + (_sbP.lastName || '');
                                    else {
                                        var _sbK = Engine.findKingdom(_sb.ownerId);
                                        if (_sbK) _sbOwner = _sbK.name;
                                    }
                                }
                                var _sbCond = _sb.condition || 'good';
                                html += '<option value="' + _si + '">Lv.' + (_sb.level || 1) + ' — ' + _sbOwner + ' (' + _sbCond + ')</option>';
                            }
                            html += '</select>';
                            html += '</div>';
                        }
                    }
                }

                html += '<div style="display:flex;gap:4px;">';
                html += '<button class="btn-medieval btn-work" data-action="executeWork" data-id="' + i + '">Work</button>';
                html += '<button class="btn-medieval" data-action="startAutoWorkUI" data-id="' + i + '" style="font-size:0.75rem;padding:4px 10px;background:rgba(80,160,80,0.35);border-color:rgba(120,200,120,0.5);color:#c8e6c9;text-shadow:1px 1px 2px rgba(0,0,0,0.7);" title="Repeat this job automatically">&#x27F3; Auto</button>';
                html += '</div>';
                html += '</div>';
            }
            html += '</div>';
        }

        openModal('💼 Find Work', html);

        // Scroll modal body to top so jobs list is visible
        var _wMb = el.modalBody || document.getElementById('modalBody');
        if (_wMb) _wMb.scrollTop = 0;

        // Story mode: highlight the relevant job item + dropdown + WORK button
        if (Player.storyMode && Player.storyMode.active && !Player.storyMode.complete &&
            typeof StoryMode !== 'undefined' && StoryMode.getCurrentChapter) {
            var _wsCh = StoryMode.getCurrentChapter();
            if (_wsCh && _wsCh.objectives) {
                for (var _wsOi = 0; _wsOi < _wsCh.objectives.length; _wsOi++) {
                    var _wsObj = _wsCh.objectives[_wsOi];
                    if (_wsObj.type === 'work_shift' && !_wsObj.done) {
                        var _wsAllowed = (_wsObj.building || '').split('|');
                        // Find matching job items and highlight them
                        var _wsJobItems = document.querySelectorAll('.job-item');
                        for (var _wsJi = 0; _wsJi < _wsJobItems.length; _wsJi++) {
                            var _wsJob = jobs[_wsJi];
                            if (_wsJob && _wsJob.buildingType && _wsAllowed.indexOf(_wsJob.buildingType) !== -1) {
                                // Highlight the job card
                                _wsJobItems[_wsJi].style.border = '2px solid var(--gold)';
                                _wsJobItems[_wsJi].style.boxShadow = '0 0 12px rgba(218,165,32,0.5)';
                                _wsJobItems[_wsJi].style.background = 'rgba(218,165,32,0.08)';
                                // Highlight the WORK button
                                var _wsWorkBtn = _wsJobItems[_wsJi].querySelector('[data-action="executeWork"]');
                                if (_wsWorkBtn) _wsWorkBtn.classList.add('tutorial-highlight');
                                // Highlight the building dropdown if present
                                var _wsSelect = _wsJobItems[_wsJi].querySelector('select');
                                if (_wsSelect) {
                                    _wsSelect.style.border = '2px solid var(--gold)';
                                    _wsSelect.style.boxShadow = '0 0 8px rgba(218,165,32,0.5)';
                                    _wsSelect.style.background = 'rgba(218,165,32,0.15)';
                                    // Pre-select father's building if available
                                    var _wsOpts = _wsSelect.querySelectorAll('option');
                                    for (var _wsOptI = 0; _wsOptI < _wsOpts.length; _wsOptI++) {
                                        if (_wsOpts[_wsOptI].textContent.indexOf('Edmund') !== -1 ||
                                            _wsOpts[_wsOptI].textContent.indexOf('Ashford') !== -1) {
                                            _wsSelect.value = _wsOpts[_wsOptI].value;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
            }
        }
    }

    function enlistAsSoldier(kingdomId) {
        if (typeof Player === 'undefined' || !Player.enlistAsSoldier) return;
        const result = Player.enlistAsSoldier(kingdomId);
        if (result.success) {
            toast(result.message, 'success');
            closeModal();
        } else {
            toast(result.message, 'warning');
        }
    }

    function quitMilitary() {
        if (typeof Player === 'undefined' || !Player.quitMilitary) return;
        const result = Player.quitMilitary();
        if (result.success) {
            toast(result.message, 'success');
            closeModal();
        } else {
            toast(result.message, 'warning');
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  MILITARY EVENT CHOICE — Battle/Task approach selection
    // ═══════════════════════════════════════════════════════════
    function showMilitaryEventChoice(event) {
        if (!event) return;
        var approaches = (typeof CONFIG !== 'undefined' && CONFIG.MILITARY_APPROACH) ? CONFIG.MILITARY_APPROACH : {};
        var isBattle = event.type === 'battle';
        var title = isBattle ? '⚔️ Battle Incoming!' : '📋 Military Assignment';
        var desc = '';

        if (isBattle) {
            var enemyName = 'the enemy';
            if (event.enemyKingdomId && typeof Engine !== 'undefined' && Engine.findKingdom) {
                var ek = Engine.findKingdom(event.enemyKingdomId);
                if (ek) enemyName = ek.name;
            }
            desc = '<p style="color:#ff9966;font-size:1.05rem;margin-bottom:12px;">⚔️ Your unit has been called to battle against <strong>' + enemyName + '</strong>!</p>';
            desc += '<p style="color:#ccc;font-size:0.9rem;margin-bottom:16px;">Choose your approach. Aggressive fighters risk more but earn glory faster. Cautious soldiers survive longer but advance slowly.</p>';
        } else if (event.task) {
            desc = '<p style="color:#aad;font-size:1.05rem;margin-bottom:8px;">' + (event.task.name || 'Military Task') + '</p>';
            desc += '<p style="color:#ccc;font-size:0.9rem;margin-bottom:16px;">' + (event.task.desc || '') + '</p>';
            if (event.task.injuryChance > 0) {
                var riskLabel = event.task.injuryChance >= 0.10 ? '⚠️ High' : event.task.injuryChance >= 0.05 ? '⚡ Moderate' : '✅ Low';
                desc += '<p style="color:#888;font-size:0.85rem;margin-bottom:12px;">Injury risk: ' + riskLabel + ' (' + Math.round(event.task.injuryChance * 100) + '%)</p>';
            }
        }

        var html = '<div style="text-align:center;padding:10px;">';
        html += desc;
        html += '<div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:10px;">';

        // Aggressive button
        var agg = approaches.aggressive || {};
        html += '<div style="flex:1;min-width:140px;max-width:200px;background:#3a1515;border:2px solid #cc3333;border-radius:8px;padding:12px;cursor:pointer;" ';
        html += 'data-action="resolvePendingMilitaryEventAndCloseModal" data-id="aggressive" ';
        html += 'onmouseover="this.style.borderColor=\'#ff4444\'" onmouseout="this.style.borderColor=\'#cc3333\'">';
        html += '<div style="font-size:1.2rem;margin-bottom:6px;">' + (agg.label || '⚔️ Aggressive') + '</div>';
        html += '<div style="color:#ccc;font-size:0.8rem;">' + (agg.desc || 'Fight recklessly for glory.') + '</div>';
        if (isBattle) html += '<div style="color:#ff6666;font-size:0.75rem;margin-top:6px;">+50% death risk • Guaranteed promotion</div>';
        html += '</div>';

        // Normal button
        var norm = approaches.normal || {};
        html += '<div style="flex:1;min-width:140px;max-width:200px;background:#1a2a1a;border:2px solid #FFD700;border-radius:8px;padding:12px;cursor:pointer;" ';
        html += 'data-action="resolvePendingMilitaryEventAndCloseModal" data-id="normal" ';
        html += 'onmouseover="this.style.borderColor=\'#ffee00\'" onmouseout="this.style.borderColor=\'#FFD700\'">';
        html += '<div style="font-size:1.2rem;margin-bottom:6px;">' + (norm.label || '🛡️ Normal') + '</div>';
        html += '<div style="color:#ccc;font-size:0.8rem;">' + (norm.desc || 'Standard approach.') + '</div>';
        if (isBattle) html += '<div style="color:#aaa;font-size:0.75rem;margin-top:6px;">Standard risk • Standard advancement</div>';
        html += '</div>';

        // Cautious button
        var caut = approaches.cautious || {};
        html += '<div style="flex:1;min-width:140px;max-width:200px;background:#151a2a;border:2px solid #4488cc;border-radius:8px;padding:12px;cursor:pointer;" ';
        html += 'data-action="resolvePendingMilitaryEventAndCloseModal" data-id="cautious" ';
        html += 'onmouseover="this.style.borderColor=\'#66aaee\'" onmouseout="this.style.borderColor=\'#4488cc\'">';
        html += '<div style="font-size:1.2rem;margin-bottom:6px;">' + (caut.label || '🐢 Cautious') + '</div>';
        html += '<div style="color:#ccc;font-size:0.8rem;">' + (caut.desc || 'Stay in the rear.') + '</div>';
        if (isBattle) html += '<div style="color:#6699cc;font-size:0.75rem;margin-top:6px;">-60% death risk • Slower advancement</div>';
        html += '</div>';

        html += '</div></div>';

        // Save game speed before pausing
        if (typeof Player !== 'undefined' && Player.state) {
            Player.state._preMilitarySpeed = (typeof Game !== 'undefined' && Game.getSpeed) ? Game.getSpeed() : 1;
        }

        openModal(title, html, '');
    }

    function executeWork(jobIndex) {
        const result = Player.doWork(jobIndex);
        if (result.success) {
            toast(result.message, 'success');
            closeModal();
            // Handle tournament continue prompt
            if (result.tournamentContinue) {
                setTimeout(function() { showTournamentContinueDialog(result); }, 300);
            }
        } else {
            toast(result.message, 'warning');
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  ENCOUNTER DIALOG (Bandits / Pirates / Wartime Ambush)
    // ═══════════════════════════════════════════════════════════

    function showEncounterDialog(encounter) {
        if (!encounter) return;

        // Auto-pause the game for encounters
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var isSea = encounter.isSea;
        var isWartime = encounter.isWartime;
        var enemyName = isWartime ? (isSea ? 'Enemy Navy' : 'Enemy Soldiers') : (isSea ? 'Pirates' : 'Bandits');
        var enemyIcon = isWartime ? (isSea ? '⚓' : '⚔️') : (isSea ? '🏴‍☠️' : '🗡️');

        var fightPct = Math.round(encounter.fightWinChance * 100);
        var negPct = Math.round(encounter.negotiateChance * 100);

        // Surrender cost description
        var goldForSurrender = Math.min(Math.floor((Player.gold || 0) * 0.50), 500);
        var invCount = 0;
        var inv = Player.inventory || {};
        for (var k in inv) { if (inv[k] > 0) invCount += inv[k]; }

        // Negotiate cost description
        var goldForNeg = Math.min(Math.floor((Player.gold || 0) * 0.10), 250);

        var html = '<div style="text-align:center;margin-bottom:16px;">';
        html += '<div style="font-size:2.5rem;margin-bottom:8px;">' + enemyIcon + '</div>';
        html += '<h2 style="margin:0;color:var(--danger);">' + enemyName + ' Encounter!</h2>';

        if (isWartime) {
            html += '<p style="color:#e67e22;font-size:0.9rem;margin:8px 0;">';
            if (isSea) {
                html += 'An enemy warship has intercepted you! Their navy crew is well-armed and disciplined.';
            } else {
                html += 'Enemy soldiers have ambushed you on the road! They are well-trained and dangerous.';
            }
            html += '</p>';
        } else {
            html += '<p style="color:#d4c9a0;font-size:0.9rem;margin:8px 0;">';
            if (isSea) {
                html += 'A pirate vessel has spotted you and is closing in! They fly the black flag.';
            } else {
                html += 'A group of bandits has blocked the road ahead! They demand your valuables.';
            }
            html += '</p>';
        }
        html += '</div>';

        // Three choices
        html += '<div style="display:flex;flex-direction:column;gap:12px;margin-top:16px;">';

        // Surrender
        html += '<button class="btn-medieval" data-action="resolveEncounterChoice" data-choice="surrender" style="padding:14px 16px;text-align:left;background:rgba(200,50,50,0.15);border-color:rgba(200,50,50,0.5);border-width:2px;">';
        html += '<div style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🏳️ Surrender</div>';
        html += '<div style="font-size:0.82rem;color:#ccc;margin-top:4px;">Give up all goods' + (invCount > 0 ? ' (' + invCount + ' items)' : '') + ' and ' + goldForSurrender + 'g. They let you pass unharmed.</div>';
        html += '</button>';

        // Negotiate
        html += '<button class="btn-medieval" data-action="resolveEncounterChoice" data-choice="negotiate" style="padding:14px 16px;text-align:left;background:rgba(241,196,15,0.12);border-color:rgba(241,196,15,0.5);border-width:2px;">';
        html += '<div style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">🤝 Negotiate <span style="font-size:0.85rem;color:#f1c40f;font-weight:bold;">(' + negPct + '% chance)</span></div>';
        html += '<div style="font-size:0.82rem;color:#ccc;margin-top:4px;">Offer half your goods and ' + goldForNeg + 'g. If they refuse, it becomes a fight (with penalty).</div>';
        html += '</button>';

        // Fight
        var fightColor = fightPct >= 60 ? '#2ecc71' : fightPct >= 35 ? '#f39c12' : '#e74c3c';
        html += '<button class="btn-medieval" data-action="resolveEncounterChoice" data-choice="fight" style="padding:14px 16px;text-align:left;background:rgba(46,204,113,0.12);border-color:rgba(46,204,113,0.5);border-width:2px;">';
        html += '<div style="font-size:1.05rem;font-weight:bold;color:#f0d0a0;">⚔️ Fight <span style="font-size:0.85rem;color:' + fightColor + ';font-weight:bold;">(' + fightPct + '% chance to win)</span></div>';
        html += '<div style="font-size:0.82rem;color:#ccc;margin-top:4px;">';
        if (isSea) {
            html += 'Fight them off! If you lose, you wash ashore ill with nothing.';
        } else {
            html += 'Fight your way through! If you lose, suffer injuries and lose all goods.';
        }
        html += '</div>';
        html += '</button>';

        html += '</div>';

        // Modifiers info
        html += '<div style="margin-top:16px;padding:8px;background:rgba(0,0,0,0.2);border-radius:4px;font-size:0.75rem;color:var(--text-muted);">';
        html += '<strong>Your advantages:</strong> ';
        var advantages = [];
        var guardNum = Player.guards ? Player.guards.length : (Player.personalGuards || 0);
        if (guardNum > 0) {
            var guardNames = [];
            if (Player.guards) {
                for (var gi = 0; gi < Player.guards.length; gi++) {
                    guardNames.push(Player.guards[gi].name || 'Guard');
                }
            }
            advantages.push('\uD83D\uDEE1\uFE0F ' + guardNum + ' guard' + (guardNum > 1 ? 's' : '') + (guardNames.length > 0 ? ' (' + guardNames.join(', ') + ')' : ''));
        }
        if (Player.weapon) advantages.push('⚔️ Armed');
        if (Player.armor) advantages.push('🛡️ Armored');
        if (Player.hasSkill && Player.hasSkill('battle_hardened')) advantages.push('💪 Battle Hardened');
        else if (Player.hasSkill && Player.hasSkill('combat_trained')) advantages.push('🗡️ Combat Trained');
        if (isSea) {
            var ship = Player.getBestShip ? Player.getBestShip() : null;
            if (ship) {
                var st = CONFIG.SHIP_TYPES ? CONFIG.SHIP_TYPES[ship.type] : null;
                advantages.push('⛵ ' + (st ? st.name : ship.type));
            }
        }
        if (advantages.length === 0) advantages.push('None');
        html += advantages.join(' · ');
        html += '</div>';

        openModal('⚠️ ' + enemyName + ' Encounter!', html, '');

        // Lock the encounter modal — cannot be closed or dismissed
        _encounterLocked = true;
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = 'none';
    }

    function resolveEncounterChoice(choice) {
        if (typeof Player === 'undefined' || !Player.resolveEncounter) return;

        // Unlock the encounter modal so result can be closed
        _encounterLocked = false;
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = '';

        var result = Player.resolveEncounter(choice);

        // Show result in the same modal
        var resultHtml = '<div style="text-align:center;margin-bottom:12px;">';

        if (result.choice === 'surrender') {
            resultHtml += '<div style="font-size:2rem;">🏳️</div>';
            resultHtml += '<h3 style="color:var(--gold);">Surrendered</h3>';
            resultHtml += '<p>You gave up your goods and ' + (result.goldLost || 0) + 'g. They let you pass.</p>';
        } else if (result.choice === 'negotiate' || result.choice === 'negotiate_failed') {
            if (result.choice === 'negotiate') {
                resultHtml += '<div style="font-size:2rem;">🤝</div>';
                resultHtml += '<h3 style="color:#f1c40f;">Negotiation Successful</h3>';
                resultHtml += '<p>You talked your way out, losing some goods and ' + (result.goldLost || 0) + 'g.</p>';
            } else {
                resultHtml += '<div style="font-size:2rem;">❌</div>';
                resultHtml += '<h3 style="color:var(--danger);">Negotiation Failed!</h3>';
                if (result.success) {
                    resultHtml += '<p>They rejected your offer — but you won the ensuing fight!</p>';
                } else {
                    resultHtml += '<p>They rejected your offer and attacked! You lost the fight.</p>';
                }
            }
        } else if (result.choice === 'fight') {
            if (result.success) {
                resultHtml += '<div style="font-size:2rem;">⚔️</div>';
                resultHtml += '<h3 style="color:#2ecc71;">Victory!</h3>';
                resultHtml += '<p>You fought them off!</p>';
                if (result.shipDamaged) resultHtml += '<p style="color:#e67e22;">Your ship took damage in the fight.</p>';
            } else {
                resultHtml += '<div style="font-size:2rem;">💀</div>';
                resultHtml += '<h3 style="color:var(--danger);">Defeated!</h3>';
                if (result.died) {
                    resultHtml += '<p style="color:var(--danger);font-weight:bold;">You were killed.</p>';
                } else if (result.injured) {
                    resultHtml += '<p>You suffered a <strong style="color:' + (result.injurySeverity === 'severe' ? 'var(--danger)' : '#e67e22') + ';">' + result.injurySeverity + '</strong> injury and lost all your goods.</p>';
                }
            }
        }

        resultHtml += '</div>';

        // Losses summary
        var lossKeys = Object.keys(result.goodsLost || {});
        if (lossKeys.length > 0 || result.goldLost > 0) {
            resultHtml += '<div style="padding:8px;background:rgba(200,50,50,0.1);border-radius:4px;font-size:0.8rem;">';
            resultHtml += '<strong>Losses:</strong><br>';
            if (result.goldLost > 0) resultHtml += '💰 ' + result.goldLost + ' gold<br>';
            for (var li = 0; li < Math.min(lossKeys.length, 8); li++) {
                var lKey = lossKeys[li];
                var res = null;
                try { res = findResource(lKey); } catch (e) {}
                var lName = res ? res.name : lKey;
                resultHtml += (res ? (res.icon || '') : '') + ' ' + lName + ' ×' + result.goodsLost[lKey] + '<br>';
            }
            if (lossKeys.length > 8) resultHtml += '...and ' + (lossKeys.length - 8) + ' more types of goods.<br>';
            resultHtml += '</div>';
        }

        // Guard casualties
        if (result.guardCasualties && result.guardCasualties.length > 0) {
            resultHtml += '<div style="padding:8px;background:rgba(200,50,50,0.15);border-radius:4px;font-size:0.8rem;margin-top:6px;">';
            resultHtml += '<strong>🛡️ Guard Casualties:</strong><br>';
            for (var gci = 0; gci < result.guardCasualties.length; gci++) {
                var gc = result.guardCasualties[gci];
                if (gc.outcome === 'killed') {
                    resultHtml += '💀 ' + gc.name + ' — <span style="color:var(--danger);">killed</span><br>';
                } else if (gc.outcome === 'injured') {
                    var gcColor = gc.severity === 'severe' ? 'var(--danger)' : '#e67e22';
                    resultHtml += '🩹 ' + gc.name + ' — <span style="color:' + gcColor + ';">' + gc.severity + ' injury</span><br>';
                }
            }
            resultHtml += '</div>';
        }

        // Family companion casualties
        if (result.familyCasualties && result.familyCasualties.length > 0) {
            resultHtml += '<div style="padding:8px;background:rgba(200,50,50,0.15);border-radius:4px;font-size:0.8rem;margin-top:6px;">';
            resultHtml += '<strong>👨‍👩‍👧‍👦 Family Casualties:</strong><br>';
            for (var fci = 0; fci < result.familyCasualties.length; fci++) {
                var fc = result.familyCasualties[fci];
                if (fc.outcome === 'killed') {
                    resultHtml += '💀 ' + fc.name + ' (' + fc.role + ') — <span style="color:var(--danger);">killed</span><br>';
                } else if (fc.outcome === 'injured') {
                    var fcColor = fc.severity === 'severe' ? 'var(--danger)' : '#e67e22';
                    resultHtml += '🩹 ' + fc.name + ' (' + fc.role + ') — <span style="color:' + fcColor + ';">' + fc.severity + ' injury</span><br>';
                }
            }
            resultHtml += '</div>';
        }

        resultHtml += '<div style="text-align:center;margin-top:16px;"><button class="btn-medieval" data-action="closeModal" style="padding:8px 24px;">Continue Journey</button></div>';

        openModal('Encounter Result', resultHtml, '');
    }

    // Register the encounter dialog callback for player.js to call
    window._showEncounterDialog = showEncounterDialog;

    // Conquest lock — called from engine.js when conquest choice modal is shown
    function setConquestLock(locked) {
        _conquestLocked = !!locked;
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = locked ? 'none' : '';
    }

    // ── Medical Rest (extended bed rest for low health) ──
    var _medRestInterval = null;
    function startMedicalRest(days) {
        if (typeof Player === 'undefined' || typeof Game === 'undefined') return;
        var result = Player.startMedicalRest(days);
        if (!result.success) {
            toast(result.message, 'warning');
            return;
        }
        toast(result.message, 'success');
        closeModal();
        // Set speed to 60x and show lock overlay
        var _prevSpeed = Game.getSpeed();
        Game.setSpeed(60);
        _showMedicalRestOverlay(days);
        // Poll every 200ms to check if rest is done
        _medRestInterval = setInterval(function() {
            if (!Player.state || !Player.state._medicalRest) {
                clearInterval(_medRestInterval);
                _medRestInterval = null;
                Game.setSpeed(_prevSpeed || 1);
                _hideMedicalRestOverlay();
                toast('Medical rest complete! You feel much better.', 'success');
                return;
            }
            var mr = Player.state._medicalRest;
            var _curHp = Player.health != null ? Player.health : 100;
            var _maxHp = Player.maxHealth || 100;
            _updateMedicalRestOverlay(mr.daysRemaining, mr.daysTotal, _curHp, _maxHp);
        }, 200);
    }

    function _showMedicalRestOverlay(days) {
        var overlay = document.createElement('div');
        overlay.id = 'medicalRestOverlay';
        overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.85);z-index:99999;display:flex;align-items:center;justify-content:center;';
        overlay.innerHTML = '<div style="text-align:center;color:#ddd;font-family:serif;">' +
            '<div style="font-size:2.5rem;margin-bottom:12px;">🛏️</div>' +
            '<div style="font-size:1.3rem;color:var(--gold,#c9a84c);margin-bottom:8px;">Medical Rest in Progress</div>' +
            '<div id="medRestStatus" style="font-size:1rem;color:#ccc;">Resting... ' + days + ' day' + (days > 1 ? 's' : '') + ' remaining</div>' +
            '<div id="medRestHealth" style="font-size:0.9rem;color:#8e8;margin-top:6px;"></div>' +
            '<div style="margin-top:16px;"><div style="width:200px;height:10px;background:#333;border-radius:5px;margin:0 auto;">' +
            '<div id="medRestBar" style="width:0%;height:100%;background:linear-gradient(90deg,#c44e52,#55a868);border-radius:5px;transition:width 0.3s;"></div>' +
            '</div></div>' +
            '</div>';
        document.body.appendChild(overlay);
    }

    function _updateMedicalRestOverlay(daysLeft, daysTotal, curHp, maxHp) {
        var statusEl = document.getElementById('medRestStatus');
        var healthEl = document.getElementById('medRestHealth');
        var barEl = document.getElementById('medRestBar');
        if (statusEl) statusEl.textContent = 'Resting... ' + daysLeft + ' day' + (daysLeft !== 1 ? 's' : '') + ' remaining';
        if (healthEl) healthEl.textContent = '❤️ Health: ' + Math.floor(curHp) + '/' + maxHp;
        if (barEl) barEl.style.width = Math.round(((daysTotal - daysLeft) / daysTotal) * 100) + '%';
    }

    function _hideMedicalRestOverlay() {
        var overlay = document.getElementById('medicalRestOverlay');
        if (overlay) overlay.remove();
    }

    // ═══════════════════════════════════════════════════════════
    //  HEALTH DIALOG
    // ═══════════════════════════════════════════════════════════

    function openHealthDialog() {
        if (typeof Player === 'undefined') return;
        let html = '<h3>🏥 Treatment Options</h3>';

        const injuries = Player.injuries || [];
        const illnesses = Player.illnesses || [];

        // Check for sick companions before deciding to return early
        var _earlyComps = (typeof Player !== 'undefined' && Player.getTreatableCompanions) ? Player.getTreatableCompanions() : [];

        if (injuries.length === 0 && illnesses.length === 0 && _earlyComps.length === 0) {
            html += '<p class="text-dim">You are healthy!</p>';
            openModal('🏥 Health', html);
            return;
        }

        if (injuries.length === 0 && illnesses.length === 0) {
            html += '<p class="text-dim">You are healthy!</p>';
        }

        // Check medical facility availability (none available while traveling)
        var _isTraveling = Player.traveling || false;
        var medFacilities = (!_isTraveling && Player.getMedicalFacilities) ? Player.getMedicalFacilities() : { hasHospital: false, hasClinic: false };
        var hasHospital = medFacilities.hasHospital;
        var hasClinic = medFacilities.hasClinic;

        const hasDoctor = Player.hasSkill && Player.hasSkill('doctor');
        const hasFieldMedic = Player.hasSkill && Player.hasSkill('field_medic');
        const hasFirstAid = Player.hasSkill && Player.hasSkill('first_aid');
        var canSelfTreat = hasDoctor || hasFieldMedic || hasFirstAid;

        // Facility info + get AI-driven fees
        var hospFees = null;
        try { hospFees = Engine.getHospitalFees ? Engine.getHospitalFees(Player.townId) : null; } catch(e) {}

        if (hasHospital || hasClinic) {
            html += '<div style="font-size:0.72rem;color:#aaa;margin-bottom:8px;">';
            if (hasHospital) {
                var hInfo = hospFees ? hospFees.hospital : null;
                html += '🏥 Hospital available';
                if (hInfo) html += ' — ' + hInfo.queueLength + '/' + hInfo.maxHealers + ' patients';
                if (hInfo && hInfo.healthcareTaxRate > 0) html += ' (Healthcare tax: ' + Math.round(hInfo.healthcareTaxRate * 100) + '%)';
                html += '. ';
            }
            if (hasClinic) {
                var cInfo = hospFees ? hospFees.clinic : null;
                html += '⚕️ Clinic available';
                if (cInfo) html += ' — ' + cInfo.queueLength + '/' + cInfo.maxHealers + ' patients';
                html += '. ';
            }
            html += '</div>';
        }

        // Helper to get fee and time description (includes queue wait)
        function _getFeeAndTime(facilityType, severity) {
            var info = hospFees ? hospFees[facilityType] : null;
            var fallbackFee = severity === 'severe' ? 40 : severity === 'moderate' ? 20 : 10;
            var fee = info && info.fees ? (info.fees[severity] || fallbackFee) : fallbackFee;
            var ticks = info && info.treatmentTicks ? (info.treatmentTicks[severity] || 25) : 25;
            // Clinics take 2x for severe
            if (facilityType === 'clinic' && severity === 'severe') ticks = ticks * 2;
            // Queue wait estimate
            var qLen = info ? (info.queueLength || 0) : 0;
            var maxH = info ? (info.maxHealers || 2) : 2;
            var _pIsNoble = Player.state && Player.state.isNoble;
            if (!_pIsNoble && Player.state && Player.state.socialRank) {
                var _pTown = Engine.findTown ? Engine.findTown(Player.townId) : null;
                if (_pTown && Player.state.socialRank[_pTown.kingdomId] >= 4) _pIsNoble = true;
            }
            var queueWait = _pIsNoble ? 0 : Math.max(0, Math.ceil((qLen / maxH) * 30));
            var totalTicks = ticks + queueWait;
            var timeStr;
            if (totalTicks <= 5) timeStr = 'quick';
            else if (totalTicks <= 15) timeStr = '~' + Math.round(totalTicks * 24 / 60) + 'h';
            else if (totalTicks <= 60) timeStr = '~' + Math.round(totalTicks * 24 / 60) + 'h';
            else timeStr = '~' + Math.round(totalTicks / 60 * 10) / 10 + ' days';
            var queueNote = '';
            if (_pIsNoble && qLen > 0) queueNote = ' 👑';
            else if (queueWait > 0) queueNote = ' +wait';
            return { fee: fee, time: timeStr + queueNote };
        }

        // Injuries
        if (injuries.length > 0) {
            html += '<h4 style="margin:8px 0 4px 0;">🩹 Injuries</h4>';
            for (let i = 0; i < injuries.length; i++) {
                var inj = injuries[i];
                var injTypes = Player.getInjuryTypes ? Player.getInjuryTypes() : [];
                var typeDef = injTypes.find(function(t) { return t.id === inj.type; });
                var sevColor = inj.severity === 'severe' ? 'var(--danger)' : inj.severity === 'moderate' ? '#e67e22' : '#2ecc71';

                html += '<div style="border:1px solid var(--border);padding:6px;margin-bottom:6px;border-radius:4px;">';
                html += '<div class="detail-row"><span class="label">' + inj.name + '</span>';
                html += '<span class="value" style="color:' + sevColor + ';">' + inj.severity + (inj.treated ? ' ✓ treating' : '') + '</span></div>';
                html += '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">';
                if (hasHospital) {
                    var hft = _getFeeAndTime('hospital', inj.severity);
                    html += '<button class="btn-medieval" data-action="treatAtHospital" data-idx="' + i + '" data-val="false" style="font-size:0.7rem;padding:3px 8px;">🏥 Hospital (' + hft.fee + 'g, ' + hft.time + ')</button>';
                }
                if (hasClinic) {
                    var cft = _getFeeAndTime('clinic', inj.severity);
                    var _clinSevNote = inj.severity === 'severe' ? ' ⚠️ 2x time' : '';
                    html += '<button class="btn-medieval" data-action="treatAtClinic" data-idx="' + i + '" data-val="false" style="font-size:0.7rem;padding:3px 8px;">⚕️ Clinic (' + cft.fee + 'g, ' + cft.time + _clinSevNote + ')</button>';
                }
                if (canSelfTreat && !inj.treated && typeDef) {
                    html += '<button class="btn-medieval" data-action="selfTreatCondition" data-idx="' + i + '" data-val="false" style="font-size:0.7rem;padding:3px 8px;">💊 Self-Treat (needs ' + typeDef.product + ')</button>';
                }
                html += '</div></div>';
            }
        }

        // Illnesses
        if (illnesses.length > 0) {
            html += '<h4 style="margin:8px 0 4px 0;">🤒 Illnesses</h4>';
            for (let i = 0; i < illnesses.length; i++) {
                var ill = illnesses[i];
                var illTypes = Player.getIllnessTypes ? Player.getIllnessTypes() : [];
                var illTypeDef = illTypes.find(function(t) { return t.id === ill.type; });
                var illSevColor = ill.severity === 'severe' ? 'var(--danger)' : ill.severity === 'moderate' ? '#e67e22' : '#2ecc71';

                html += '<div style="border:1px solid var(--border);padding:6px;margin-bottom:6px;border-radius:4px;">';
                var illDisplayName = ill.name || (illTypeDef ? illTypeDef.name : (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Unknown Illness'));
                html += '<div class="detail-row"><span class="label">' + illDisplayName + '</span>';
                html += '<span class="value" style="color:' + illSevColor + ';">' + ill.severity + (ill.treated ? ' ✓ treating' : '') + '</span></div>';
                html += '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">';
                if (hasHospital) {
                    var ihft = _getFeeAndTime('hospital', ill.severity);
                    html += '<button class="btn-medieval" data-action="treatAtHospital" data-idx="' + i + '" data-val="true" style="font-size:0.7rem;padding:3px 8px;">🏥 Hospital (' + ihft.fee + 'g, ' + ihft.time + ')</button>';
                }
                if (hasClinic) {
                    var icft = _getFeeAndTime('clinic', ill.severity);
                    var _clinSevNote2 = ill.severity === 'severe' ? ' ⚠️ 2x time' : '';
                    html += '<button class="btn-medieval" data-action="treatAtClinic" data-idx="' + i + '" data-val="true" style="font-size:0.7rem;padding:3px 8px;">⚕️ Clinic (' + icft.fee + 'g, ' + icft.time + _clinSevNote2 + ')</button>';
                }
                if (canSelfTreat && !ill.treated && illTypeDef) {
                    html += '<button class="btn-medieval" data-action="selfTreatCondition" data-idx="' + i + '" data-val="true" style="font-size:0.7rem;padding:3px 8px;">💊 Self-Treat (needs ' + illTypeDef.product + ')</button>';
                }
                html += '</div></div>';
            }
        }

        if (!hasHospital && !hasClinic) {
            html += '<p class="text-dim" style="font-size:0.72rem;">No hospital or clinic here. Visit a town with medical facilities for treatment.</p>';
        } else if (!hasHospital && hasClinic) {
            html += '<p class="text-dim" style="font-size:0.72rem;">Only a clinic here — severe conditions take 2x longer with reduced success rate. A hospital (cities/capitals) is faster.</p>';
        }
        if (!canSelfTreat) {
            html += '<p class="text-dim" style="font-size:0.72rem;">Learn First Aid, Field Medic, or Doctor skill to self-treat with medical supplies.</p>';
        }

        // === SICK COMPANIONS (spouse, family, guards) ===
        if (typeof Player !== 'undefined' && Player.getTreatableCompanions) {
            var _sickComps = Player.getTreatableCompanions();
            if (_sickComps.length > 0) {
                html += '<h4 style="margin:12px 0 6px 0;border-top:1px solid var(--border);padding-top:8px;">👥 Sick Companions</h4>';
                var _compHasDoc = Player.hasSkill && (Player.hasSkill('field_medic') || Player.hasSkill('doctor'));
                for (var _sci = 0; _sci < _sickComps.length; _sci++) {
                    var _sc = _sickComps[_sci];
                    var _scIcon = _sc.type === 'spouse' ? '💍' : _sc.type === 'guard' ? '🛡️' : '👤';
                    var _scCondIcon = _sc.condition === 'gravely_ill' ? '☠️' : _sc.condition === 'sick' ? '🤒' : '🩹';
                    var _scCondColor = _sc.condition === 'gravely_ill' ? '#f33' : _sc.condition === 'sick' ? '#e67e22' : '#d4a017';
                    var _scLabel = _sc.type === 'spouse' ? 'Spouse' : _sc.type === 'guard' ? 'Guard' : (_sc.role ? _sc.role.charAt(0).toUpperCase() + _sc.role.slice(1) : 'Family');
                    html += '<div style="border:1px solid var(--border);padding:6px;margin-bottom:6px;border-radius:4px;">';
                    html += '<div class="detail-row"><span class="label">' + _scIcon + ' ' + _sc.name + ' <span style="font-size:0.7rem;color:#888;">(' + _scLabel + ')</span></span>';
                    html += '<span class="value" style="color:' + _scCondColor + ';">' + _scCondIcon + ' ' + _sc.condition.replace('_', ' ') + '</span></div>';
                    html += '<div style="font-size:0.72rem;color:#aaa;margin:2px 0;">Health: ' + _sc.health + '</div>';
                    html += '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">';
                    if (_compHasDoc) {
                        html += '<button class="btn-medieval" data-action="treatCompanionUI" data-type="' + _sc.type + '" data-id="' + _sc.id + '" data-val="player" style="font-size:0.7rem;padding:3px 8px;background:rgba(40,120,40,0.3);border-color:rgba(60,180,60,0.5);">⚕️ Treat</button>';
                    }
                    if (hasHospital || hasClinic) {
                        html += '<button class="btn-medieval" data-action="treatCompanionUI" data-type="' + _sc.type + '" data-id="' + _sc.id + '" data-val="hospital" style="font-size:0.7rem;padding:3px 8px;background:rgba(40,80,160,0.3);border-color:rgba(60,120,220,0.5);">🏥 Hospital</button>';
                    }
                    html += '</div></div>';
                }
            }
        }

        openModal('🏥 Health', html);
    }

    function treatAtHospital(index, isIllness) {
        if (typeof Player === 'undefined' || !Player.visitHospital) return;
        var result = Player.visitHospital(index, isIllness);
        if (result.success) {
            toast(result.message, 'success');
            openHealthDialog(); // refresh
        } else {
            toast(result.message, 'warning');
        }
    }

    function treatAtClinic(index, isIllness) {
        if (typeof Player === 'undefined' || !Player.visitClinic) return;
        var result = Player.visitClinic(index, isIllness);
        if (result.success) {
            toast(result.message, 'success');
            openHealthDialog(); // refresh
        } else {
            toast(result.message, 'warning');
        }
    }

    function selfTreatCondition(index, isIllness) {
        if (typeof Player === 'undefined' || !Player.selfTreat) return;
        var result = Player.selfTreat(index, isIllness);
        if (result.success) {
            toast(result.message, 'success');
            openHealthDialog(); // refresh
        } else {
            toast(result.message, 'warning');
        }
    }

    // Treat a companion (spouse, family member, or guard)
    function treatCompanionUI(targetType, targetId, method) {
        if (typeof Player === 'undefined' || !Player.treatCompanion) {
            toast('Treatment system unavailable.', 'error');
            return;
        }
        var result = Player.treatCompanion(targetType, targetId, method);
        if (result.success) {
            toast(result.message, 'success');
        } else {
            toast(result.message, 'warning');
        }
        // Refresh the appropriate UI based on context
        var modalTitle = document.getElementById('modalTitle');
        var titleText = modalTitle ? modalTitle.textContent : '';
        if (titleText.indexOf('Health') >= 0) {
            try { openHealthDialog(); } catch(e) {}
        } else if (targetType === 'spouse') {
            try { UI.openSpousePanel(); } catch(e) {}
        } else if (targetType === 'guard') {
            try { openCharacterDialog(); } catch(e) {}
        } else {
            try { UI.openFamilyPanel(); } catch(e) {}
        }
        // Also refresh NPC detail if person detail is showing
        if (targetId && selectedPersonId === targetId) {
            try {
                var refreshPerson = Engine.findPerson(targetId);
                if (refreshPerson) UI.showPersonDetail(refreshPerson);
            } catch(e) {}
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  TEACH CHILD DIALOG
    // ═══════════════════════════════════════════════════════════

    function openTeachChildDialog(childId) {
        if (typeof Player === 'undefined') return;

        var child = null;
        try { child = Engine.findPerson(childId); } catch (e) { /* no-op */ }
        if (!child) { toast('Child not found.', 'warning'); return; }

        var passed = (Player.skillPointsPassedToChild && Player.skillPointsPassedToChild[childId]) || 0;
        var html = '<h3>📚 Teach ' + child.firstName + '</h3>';
        html += '<p style="font-size:0.75rem;color:var(--text-muted);">Costs 3 of your Skill Points to give 1 SP to your child (as heir). Points taught: <strong>' + passed + '/5</strong></p>';
        html += '<p style="font-size:0.75rem;">Your Skill Points: <strong>' + Player.skillPoints + '</strong></p>';

        if (passed >= 5) {
            html += '<p class="text-dim">Maximum skills already taught to this child.</p>';
            openModal('📚 Teach Child', html);
            return;
        }
        if (Player.skillPoints < 3) {
            html += '<p class="text-dim">Need at least 3 skill points to teach.</p>';
            openModal('📚 Teach Child', html);
            return;
        }

        // Show skills the player knows
        var skills = Player.skills || {};
        var hasAny = false;
        html += '<div class="job-list">';
        for (var skillId in skills) {
            if (!skills[skillId]) continue;
            var skillDef = null;
            if (typeof SKILLS !== 'undefined') skillDef = SKILLS[skillId];
            var skillName = (skillDef && skillDef.name) || skillId;
            var skillIcon = (skillDef && skillDef.icon) || '📖';
            hasAny = true;
            html += '<div class="job-item">';
            html += '<div class="job-info"><span class="job-name">' + skillIcon + ' ' + skillName + '</span></div>';
            html += '<button class="btn-medieval" data-action="executeTeachChild" data-id="' + childId + '" data-val="' + skillId + '" style="font-size:0.7rem;padding:3px 10px;">Teach (3→1 SP)</button>';
            html += '</div>';
        }
        html += '</div>';
        if (!hasAny) html += '<p class="text-dim">You have no skills to teach.</p>';

        openModal('📚 Teach Child', html);
    }

    function executeTeachChild(childId, skillId) {
        if (typeof Player === 'undefined' || !Player.teachChild) return;
        var result = Player.teachChild(childId, skillId);
        if (result.success) {
            toast(result.message, 'success');
            openTeachChildDialog(childId); // refresh
        } else {
            toast(result.message, 'warning');
        }
    }


    // §STREET_TRADING — Extracted to js/modules/ui_street_trading.js

    // ═══════════════════════════════════════════════════════════
    //  NOBLE COUNCIL VOTING DIALOG
    // ═══════════════════════════════════════════════════════════
    function openVotingDialog(voteId) {
        var vote = null;
        try { vote = Engine.getActiveVote ? Engine.getActiveVote(voteId) : null; } catch (e) {}
        if (!vote) {
            toast('No active vote found.', 'warning');
            return;
        }

        var kingdom = null;
        try { kingdom = Engine.getKingdom(vote.kingdomId); } catch (e) {}
        var kName = kingdom ? kingdom.name : 'Unknown';
        var daysLeft = Math.max(0, (vote.deadlineDay || 0) - (Engine.getDay ? Engine.getDay() : 0));

        // Vote weight labels — v9p33river419: RA weight is x5 (matches engine at 12458)
        var _weightLabels = { 7: '👑 King (×5)', 6: '📜 Royal Advisor (×5)', 5: '⚔️ Lord (×2)', 4: '🏛️ Minor Noble (×1)' };
        var _weightValues = { 7: 5, 6: 5, 5: 2, 4: 1 };

        // Tally — v9p33river419: exclude abstentions from total (matches engine resolution)
        var yesVotes = 0, noVotes = 0, abstainVotes = 0;
        var voters = vote.voters || [];
        for (var vi = 0; vi < voters.length; vi++) {
            var v = voters[vi];
            var w = _weightValues[v.rank] || 1;
            if (v.vote === 'yes') yesVotes += w;
            else if (v.vote === 'no') noVotes += w;
            else abstainVotes += w;
        }
        var totalWeight = yesVotes + noVotes; // abstentions excluded
        var yesPct = totalWeight > 0 ? Math.round(yesVotes / totalWeight * 100) : 0;
        var noPct = totalWeight > 0 ? Math.round(noVotes / totalWeight * 100) : 0;

        var html = '';

        // Decision description
        html += '<div style="background:rgba(201,168,76,0.1);border:1px solid rgba(201,168,76,0.3);border-radius:8px;padding:12px;margin-bottom:10px;">';
        html += '<div style="font-size:0.9rem;font-weight:bold;color:var(--gold);">📜 ' + escapeHtml(vote.title || 'Kingdom Decision') + '</div>';
        html += '<div style="font-size:0.8rem;color:#ccc;margin-top:4px;">' + escapeHtml(vote.description || '') + '</div>';
        html += '<div style="font-size:0.75rem;color:#aaa;margin-top:6px;">⏱️ ' + daysLeft + ' day' + (daysLeft !== 1 ? 's' : '') + ' remaining • Kingdom: ' + escapeHtml(kName) + '</div>';
        html += '</div>';

        // Vote tally bar
        html += '<div style="margin-bottom:10px;">';
        html += '<div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px;">';
        html += '<span style="color:#55a868;">✅ Yes: ' + yesVotes + ' (' + yesPct + '%)</span>';
        html += '<span style="color:#c44e52;">❌ No: ' + noVotes + ' (' + noPct + '%)</span>';
        html += '</div>';
        html += '<div style="height:12px;background:rgba(0,0,0,0.3);border-radius:6px;overflow:hidden;display:flex;">';
        if (totalWeight > 0) {
            html += '<div style="width:' + yesPct + '%;background:#55a868;"></div>';
            html += '<div style="width:' + noPct + '%;background:#c44e52;"></div>';
            html += '<div style="flex:1;background:rgba(150,150,150,0.3);"></div>';
        }
        html += '</div>';
        html += '<div style="font-size:0.7rem;color:#888;text-align:center;margin-top:2px;">Majority needed to pass (' + Math.ceil(totalWeight / 2 + 0.1) + '+ weighted votes)</div>';
        html += '</div>';

        // Voter list
        html += '<div style="max-height:300px;overflow-y:auto;margin-bottom:10px;">';
        for (var vi2 = 0; vi2 < voters.length; vi2++) {
            var voter = voters[vi2];
            var person = null;
            var name = '';
            // v9p33river419: handle player voter (Engine.getPerson('player') returns null)
            if (voter.isPlayer) {
                name = (typeof Player !== 'undefined' && Player.state) ? (Player.state.fullName || Player.state.firstName || 'You') : 'You';
            } else {
                try { person = Engine.getPerson(voter.id); } catch (e) {}
                name = person ? (escapeHtml(person.firstName) + ' ' + escapeHtml(person.lastName)) : 'Unknown';
            }
            var rankLabel = _weightLabels[voter.rank] || 'Noble';
            var weight = _weightValues[voter.rank] || 1;
            var voteIcon = voter.vote === 'yes' ? '✅' : voter.vote === 'no' ? '❌' : '⏳';
            var voteColor = voter.vote === 'yes' ? '#55a868' : voter.vote === 'no' ? '#c44e52' : '#888';
            var isPlayer = voter.isPlayer;
            var borderStyle = isPlayer ? 'border:2px solid var(--gold);' : 'border:1px solid rgba(255,255,255,0.08);';

            html += '<div style="background:rgba(0,0,0,0.2);' + borderStyle + 'border-radius:6px;padding:8px;margin-bottom:4px;display:flex;justify-content:space-between;align-items:center;">';
            html += '<div>';
            html += '<div style="font-size:0.82rem;color:#eee;">' + (isPlayer ? '⭐ ' : '') + name + '</div>';
            html += '<div style="font-size:0.68rem;color:#999;">' + rankLabel + ' (×' + weight + ')</div>';
            html += '</div>';
            html += '<div style="display:flex;align-items:center;gap:6px;">';

            if (isPlayer && daysLeft > 0) {
                // Player can change their vote
                html += '<button class="btn-medieval" data-action="castVote_yes" data-id="' + voteId + '" data-id2="' + voteId + '" style="font-size:0.7rem;padding:3px 8px;' + (voter.vote === 'yes' ? 'background:rgba(85,168,104,0.3);border-color:#55a868;' : '') + '">✅ Yes</button>';
                html += '<button class="btn-medieval" data-action="castVote_no" data-id="' + voteId + '" data-id2="' + voteId + '" style="font-size:0.7rem;padding:3px 8px;' + (voter.vote === 'no' ? 'background:rgba(196,78,82,0.3);border-color:#c44e52;' : '') + '">❌ No</button>';
            } else {
                html += '<span style="font-size:0.85rem;color:' + voteColor + ';">' + voteIcon + ' ' + (voter.vote || 'Undecided') + '</span>';
            }

            // Influence button (if player has high enough relationship and is a noble)
            if (!isPlayer && daysLeft > 0) {
                var rel = 0;
                try { if (Player.getRelationship) { var _r = Player.getRelationship(voter.id); rel = _r ? _r.level : 0; } } catch (e) {}
                var canInfluence = rel >= 50;
                if (canInfluence) {
                    html += '<button class="btn-medieval" data-action="tryInfluenceVote" data-id="' + voteId + '" data-id2="' + voter.id + '" style="font-size:0.65rem;padding:2px 6px;" title="Attempt to persuade (requires relationship 50+)">🗣️</button>';
                }
            }
            html += '</div></div>';
        }
        html += '</div>';

        var footerHtml = '<button class="btn-medieval" data-action="closeAndOpenNobilityDialog">Back to Nobility</button>';
        openModal('🗳️ Council Vote — ' + escapeHtml(vote.title || 'Decision'), html, footerHtml);
    }

    function _tryInfluenceVote(voteId, noblegId) {
        var result = null;
        try { result = Engine.influenceVote ? Engine.influenceVote(voteId, noblegId) : null; } catch (e) {}
        if (result && result.success) {
            toast('🗣️ ' + result.message, 'success');
        } else {
            toast('❌ ' + (result ? result.message : 'Could not influence this noble.'), 'warning');
        }
        openVotingDialog(voteId);
    }

    function openActiveVotesDialog() {
        var votes = [];
        try { votes = Engine.getActiveVotes ? Engine.getActiveVotes() : []; } catch (e) {}
        if (votes.length === 0) {
            toast('No active council votes.', 'info');
            return;
        }

        var html = '<div style="font-size:0.8rem;color:#ccc;margin-bottom:10px;">Active kingdom council votes requiring noble input:</div>';
        for (var i = 0; i < votes.length; i++) {
            var v = votes[i];
            var kName = '';
            try { var k = Engine.getKingdom(v.kingdomId); kName = k ? k.name : ''; } catch (e) {}
            var daysLeft = Math.max(0, (v.deadlineDay || 0) - (Engine.getDay ? Engine.getDay() : 0));
            html += '<button class="btn-medieval" data-action="openVotingDialog" data-id="' + v.id + '" style="display:block;width:100%;text-align:left;padding:8px 12px;margin-bottom:6px;">';
            html += '<div style="font-size:0.82rem;font-weight:bold;">' + escapeHtml(v.title || 'Decision') + '</div>';
            html += '<div style="font-size:0.72rem;color:#aaa;">' + escapeHtml(kName) + ' • ' + daysLeft + ' day' + (daysLeft !== 1 ? 's' : '') + ' left</div>';
            html += '</button>';
        }
        openModal('🗳️ Active Council Votes', html, '<button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    // ═══════════════════════════════════════════════════════════
    //  ROYAL FEAST DIALOG
    // ═══════════════════════════════════════════════════════════
    function openFeastDialog(kingdomId) {
        var feast = null;
        try { feast = Engine.getActiveFeast ? Engine.getActiveFeast(kingdomId) : null; } catch (e) {}
        if (!feast) {
            toast('No active feast in this kingdom.', 'info');
            return;
        }

        var day = 0;
        try { day = Engine.getDay(); } catch (e) {}
        var daysLeft = Math.max(0, (feast.endDay || 0) - day);
        var maxActions = feast._maxActionsPerDay || 3;
        var usedToday = (feast._playerActionDay === day) ? (feast._playerActionsToday || 0) : 0;
        var actionsLeft = maxActions - usedToday;
        var feastTown = '';
        try { var ft = Engine.findTown(feast.townId); feastTown = ft ? ft.name : ''; } catch (e) {}

        // Location check: player must be at the feast town
        if (feast.townId && Player.townId !== feast.townId) {
            toast('You must travel to ' + (feastTown || 'the feast location') + ' to attend the feast.', 'info');
            return;
        }

        // Detect if player is king of this kingdom
        var isKing = false;
        try {
            isKing = Player.state && Player.state.isKing && Player.state.kingState && Player.state.kingState.kingdomId === kingdomId;
        } catch(e) {}

        var html = '';

        // Feast header
        html += '<div style="background:linear-gradient(135deg,rgba(200,150,50,0.15),rgba(200,150,50,0.05));border:1px solid rgba(200,150,50,0.3);border-radius:8px;padding:12px;margin-bottom:10px;">';
        html += '<div style="font-size:0.9rem;font-weight:bold;color:#f0c040;">🎪 Royal Feast in ' + escapeHtml(feastTown) + (isKing ? ' (Your Feast)' : '') + '</div>';
        html += '<div style="font-size:0.78rem;color:#ccc;margin-top:4px;">' + daysLeft + ' day' + (daysLeft !== 1 ? 's' : '') + ' remaining • ' + actionsLeft + '/' + maxActions + ' action' + (actionsLeft !== 1 ? 's' : '') + ' left today</div>';
        if (isKing && actionsLeft <= 0 && daysLeft > 0) {
            html += '<div style="margin-top:6px;"><button class="btn-medieval" data-action="skipFeastDay" data-kingdom="' + kingdomId + '" style="font-size:0.72rem;padding:4px 12px;background:rgba(93,173,226,0.3);border-color:rgba(93,173,226,0.5);">⏭️ Skip to Next Feast Day</button></div>';
        }
        html += '</div>';

        // Attending nobles
        var attendees = feast.attendees || [];
        if (attendees.length > 0) {
            html += '<div style="margin-bottom:10px;">';
            html += '<div style="font-size:0.82rem;font-weight:bold;color:#ddd;margin-bottom:6px;">👥 Attendees (' + attendees.length + ')</div>';
            html += '<div style="max-height:150px;overflow-y:auto;display:flex;flex-wrap:wrap;gap:4px;">';
            for (var ai = 0; ai < attendees.length; ai++) {
                var att = null;
                try { att = Engine.getPerson(attendees[ai]); } catch (e) {}
                if (!att) continue;
                var attRank = 0;
                if (att.socialRank) for (var _rk in att.socialRank) { if (att.socialRank[_rk] > attRank) attRank = att.socialRank[_rk]; }
                var rankIcon = attRank >= 7 ? '👑' : attRank >= 6 ? '📜' : attRank >= 5 ? '⚔️' : '🏛️';
                html += '<span style="font-size:0.72rem;padding:3px 8px;border-radius:4px;background:rgba(200,150,50,0.1);border:1px solid rgba(200,150,50,0.2);cursor:pointer;" data-action="showPersonDetailById" data-id="' + att.id + '">' + rankIcon + ' ' + escapeHtml(att.firstName) + ' ' + escapeHtml(att.lastName) + '</span>';
            }
            html += '</div></div>';
        }

        // King-specific noble selector
        if (isKing) {
            html += '<div style="background:rgba(200,150,50,0.08);border:1px solid rgba(200,150,50,0.2);border-radius:6px;padding:8px;margin-bottom:8px;">';
            html += '<div style="font-size:0.75rem;color:#f0c040;margin-bottom:4px;">👑 Target Noble (for royal actions):</div>';
            html += '<select id="_feastNobleSelect" style="width:100%;background:#1a1a2e;color:#eee;border:1px solid rgba(200,150,50,0.3);border-radius:4px;padding:4px 8px;font-size:0.75rem;">';
            html += '<option value="">— Random attendee —</option>';
            for (var ns = 0; ns < attendees.length; ns++) {
                var nsPerson = null;
                try { nsPerson = Engine.getPerson(attendees[ns]); } catch(e) {}
                if (!nsPerson) continue;
                var playerPId = '';
                try { playerPId = Player.personId || 'player'; } catch(e) {}
                if (attendees[ns] === playerPId || attendees[ns] === 'player') continue;
                html += '<option value="' + attendees[ns] + '">' + escapeHtml(nsPerson.firstName) + ' ' + escapeHtml(nsPerson.lastName) + '</option>';
            }
            html += '</select>';
            html += '</div>';
        }

        // Standard feast actions
        var feastActions = [
            { id: 'mingle', icon: '🤝', name: 'Mingle & Socialize', desc: 'Build relationships (+3-8 relationship)', category: 'social' },
            { id: 'private_chat', icon: '💬', name: 'Private Conversation', desc: 'Deep conversation (+5-10 relationship, secrets)', category: 'social' },
            { id: 'eavesdrop', icon: '👂', name: 'Eavesdrop', desc: 'Learn kingdom secrets or noble plans', category: 'intel' },
            { id: 'observe_court', icon: '👀', name: 'Observe Court Politics', desc: 'Learn about noble relationships', category: 'intel' },
            { id: 'spread_rumor', icon: '🗣️', name: 'Spread a Rumor', desc: 'Damage noble reputation', category: 'scheme' },
            { id: 'forge_alliance', icon: '🤝', name: 'Forge Alliance', desc: 'Propose pact with a noble', category: 'scheme' },
            { id: 'pit_nobles', icon: '⚔️', name: 'Pit Nobles', desc: 'Cause friction (-10 mutual)', category: 'scheme' },
            { id: 'champion_noble', icon: '🏅', name: 'Champion a Noble', desc: 'Publicly praise a noble to the king (+4-8 perceived loyalty)', category: 'social' },
            { id: 'introduce_noble', icon: '🎩', name: 'Introduce Noble to King', desc: 'Bring a lesser noble to the king\'s attention (+2-5 perceived loyalty, +rank visibility)', category: 'social' }
        ];

        // Add non-king-specific actions
        if (!isKing) {
            feastActions.splice(1, 0, { id: 'toast_king', icon: '🥂', name: 'Toast the King', desc: 'Gain king favor (+2 relationship, +1 rep)', category: 'social' });
        }

        // Merchant guest actions — available if player is attending as invited merchant (not noble)
        var isMerchantGuest = false;
        try {
            if (!isKing && Player.state && Player.state._feastInvitations) {
                isMerchantGuest = Player.state._feastInvitations.some(function(inv) {
                    return inv.feastId === feast.id && inv.isMerchantInvite;
                });
            }
            // Also check if player is rank 3-4 (burgher/guildmaster) and attending
            if (!isMerchantGuest && !isKing) {
                var pPerson = Engine.getPerson(Player.personId);
                var kingdom = Engine.getKingdom(kingdomId);
                if (pPerson && kingdom) {
                    var pRank = (pPerson.socialRank && pPerson.socialRank[kingdom.id]) || 0;
                    if (pRank >= 3 && pRank <= 4) isMerchantGuest = true;
                }
            }
        } catch(e) {}

        if (isMerchantGuest) {
            feastActions.push({ id: 'advocate_lower_taxes', icon: '📜', name: 'Advocate Lower Taxes', desc: 'Convince a noble to push for lower taxes', category: 'economic' });
            feastActions.push({ id: 'advocate_lower_tariffs', icon: '📦', name: 'Advocate Lower Tariffs', desc: 'Convince a noble to push for lower tariffs', category: 'economic' });
            feastActions.push({ id: 'advocate_unban_good', icon: '🚫', name: 'Advocate Unbanning Good', desc: 'Convince a noble to push for unbanning a trade good', category: 'economic' });
            feastActions.push({ id: 'merchant_network', icon: '💰', name: 'Merchant Networking', desc: 'Build contacts with other merchants/EMs', category: 'economic' });
        }

        var categories = [
            { id: 'social', icon: '🤝', name: 'Social' },
            { id: 'intel', icon: '🕵️', name: 'Intelligence' },
            { id: 'scheme', icon: '🎭', name: 'Schemes' }
        ];

        // Add economic category if merchant guest
        if (isMerchantGuest) {
            categories.push({ id: 'economic', icon: '💰', name: 'Economic Advocacy' });
        }

        // King-specific actions section
        if (isKing) {
            categories.unshift({ id: 'royal', icon: '👑', name: 'Royal Actions' });

            var kingActions = [
                { id: 'royal_toast', icon: '🥂', name: 'Royal Toast', desc: 'Honor a specific noble publicly (+12 loyalty, others envious)', category: 'royal' },
                { id: 'royal_decree', icon: '📢', name: 'Royal Decree', desc: 'Make a kingdom announcement (happiness + loyalty)', category: 'royal' },
                { id: 'royal_challenge', icon: '🏆', name: 'Royal Challenge', desc: 'Challenge a noble to a contest (fear or respect)', category: 'royal' },
                { id: 'grant_feast_favor', icon: '🎁', name: 'Grant Royal Favor', desc: 'Grant a boon to a noble (+10-15 loyalty, +5-10 rel)', category: 'royal' },
                { id: 'subtle_interrogation', icon: '🔍', name: 'Subtle Interrogation', desc: 'Probe a noble for intel during conversation', category: 'royal' }
            ];

            feastActions = kingActions.concat(feastActions);
        }

        for (var ci = 0; ci < categories.length; ci++) {
            var cat = categories[ci];
            var catActions = feastActions.filter(function(a) { return a.category === cat.id; });
            if (catActions.length === 0) continue;
            html += '<div style="margin-bottom:8px;">';
            html += '<div style="font-size:0.82rem;font-weight:bold;color:' + (cat.id === 'royal' ? '#f0c040' : '#ddd') + ';margin-bottom:4px;">' + cat.icon + ' ' + cat.name + '</div>';
            for (var fai = 0; fai < catActions.length; fai++) {
                var fa = catActions[fai];
                var disabled = actionsLeft <= 0;
                var actionName = (isKing && fa.category === 'royal') ? 'doKingFeastAction' : 'doFeastAction';
                html += '<button class="btn-medieval" data-action="' + actionName + '" data-kingdom="' + kingdomId + '" data-id="' + fa.id + '" style="display:block;width:100%;text-align:left;padding:6px 10px;margin-bottom:3px;font-size:0.75rem;color:#111;' + (disabled ? 'opacity:0.4;cursor:not-allowed;' : '') + (fa.category === 'royal' ? 'border-color:rgba(200,150,50,0.4);' : '') + '" ' + (disabled ? 'disabled' : '') + '>';
                html += fa.icon + ' <strong>' + fa.name + '</strong><br>';
                html += '<span style="font-size:0.68rem;color:#444;">' + fa.desc + '</span>';
                html += '</button>';
            }
            html += '</div>';
        }

        // Feast events log
        if (feast.events && feast.events.length > 0) {
            html += '<div style="margin-top:8px;border-top:1px solid rgba(200,150,50,0.2);padding-top:8px;">';
            html += '<div style="font-size:0.78rem;font-weight:bold;color:#f0c040;margin-bottom:4px;">📰 Feast Events (' + feast.events.length + ')</div>';
            html += '<div style="max-height:150px;overflow-y:auto;">';
            for (var ei = feast.events.length - 1; ei >= Math.max(0, feast.events.length - 12); ei--) {
                html += '<div style="font-size:0.72rem;color:#bbb;margin-bottom:3px;padding:3px 6px;background:rgba(0,0,0,0.15);border-radius:4px;">' + escapeHtml(feast.events[ei]) + '</div>';
            }
            html += '</div></div>';
        }

        var backAction = isKing ? 'kingBackToDecisions' : 'closeAndOpenNobilityDialog';
        var footerHtml = '<button class="btn-medieval" data-action="' + backAction + '">Back</button>';
        openModal('🎪 Royal Feast', html, footerHtml);
    }

    // ═══════════════════════════════════════════════════════════
    //  NOBLE LOAN DIALOG
    // ═══════════════════════════════════════════════════════════
    function openNobleLoanDialog(nobleId) {
        var noble = null;
        try { noble = Engine.getPerson(nobleId); } catch (e) {}
        if (!noble) { toast('Noble not found.', 'warning'); return; }

        var playerGold = Player.gold || 0;
        var stressed = noble._financiallyStressed;
        var desperate = noble._desperateForLoan;
        var stressLabel = desperate ? '<span style="color:#ff6b6b;font-weight:bold;">🩸 DESPERATE — ' + escapeHtml(noble._desperateReason || 'medical emergency') + '</span>'
            : stressed ? '<span style="color:#c44e52;">💸 Financially Stressed</span>'
            : '<span style="color:#55a868;">💰 Financially Stable</span>';

        var existingLoans = Player.getNobleLoans ? Player.getNobleLoans() : [];
        var hasLoan = existingLoans.find(function(l) { return l.nobleId === nobleId; });

        // v9p33river248: predatory rate preview when desperate
        var previewInterest = 0.15;
        if (stressed) previewInterest += 0.25;
        if (desperate) previewInterest += 0.25;
        var maxLoan = desperate ? 5000 : 2000;

        var html = '';
        html += '<div style="font-size:0.82rem;color:#ccc;margin-bottom:10px;">';
        html += 'Offer a loan to <strong>' + escapeHtml(noble.firstName) + ' ' + escapeHtml(noble.lastName) + '</strong>.<br>';
        html += 'Status: ' + stressLabel + '<br>';
        html += 'Interest: <strong style="color:' + (previewInterest >= 0.40 ? '#ff8b3d' : '#f0c040') + ';">' + Math.round(previewInterest * 100) + '%</strong>'
              + (desperate ? ' (predatory — they have no choice)' : '')
              + '. Indebted nobles are easier to influence in council votes.';
        html += '</div>';
        if (desperate) {
            html += '<div style="background:rgba(180,40,40,0.18);border:1px solid rgba(220,80,80,0.4);border-radius:6px;padding:8px;margin-bottom:10px;font-size:0.78rem;color:#ffb0b0;">';
            html += '🩺 They will accept almost any terms to save themselves or their family. You can extend up to <strong>' + maxLoan + 'g</strong>.';
            html += '</div>';
        }

        if (hasLoan) {
            html += '<div style="background:rgba(200,150,50,0.15);border:1px solid rgba(200,150,50,0.3);border-radius:6px;padding:8px;margin-bottom:8px;">';
            html += '<div style="font-size:0.8rem;color:#f0c040;">📋 Existing Loan: ' + hasLoan.remainingAmount + 'g remaining (of ' + hasLoan.amount + 'g)</div>';
            html += '</div>';
        } else {
            html += '<div style="margin-bottom:10px;">';
            html += '<label style="font-size:0.78rem;color:#aaa;">Loan Amount (50-' + maxLoan + 'g):</label><br>';
            html += '<input type="number" id="loanAmountInput" min="50" max="' + maxLoan + '" value="' + (desperate ? Math.min(maxLoan, 1000) : 200) + '" style="width:120px;padding:4px 8px;border-radius:4px;border:1px solid #555;background:#1a1a2e;color:#eee;font-size:0.85rem;margin-top:4px;">';
            html += '<span style="font-size:0.72rem;color:#888;margin-left:8px;">Your gold: ' + Math.floor(playerGold) + 'g</span>';
            html += '</div>';
            html += '<button class="btn-medieval" data-action="offerNobleLoan" data-id="' + nobleId + '" data-id2="' + nobleId + '" style="font-size:0.8rem;padding:6px 16px;">💰 Offer Loan</button>';
        }

        // Show all active loans
        if (existingLoans.length > 0) {
            html += '<div style="margin-top:12px;border-top:1px solid rgba(255,255,255,0.1);padding-top:8px;">';
            html += '<div style="font-size:0.78rem;font-weight:bold;color:#ddd;margin-bottom:4px;">📋 Your Active Loans</div>';
            for (var li = 0; li < existingLoans.length; li++) {
                var loan = existingLoans[li];
                html += '<div style="font-size:0.72rem;color:#bbb;padding:3px 0;">';
                html += escapeHtml(loan.nobleName) + ': ' + loan.remainingAmount + 'g remaining (issued day ' + loan.issuedDay + ')';
                html += '</div>';
            }
            html += '</div>';
        }

        openModal('💰 Noble Loan — ' + escapeHtml(noble.firstName), html, '<button class="btn-medieval" data-action="closeModal">Close</button>');
    }

    function openSchemesDialog() {
        const actions = Player.getAvailableCorruptActions();
        const tabs = [
            { id: 'sabotage', label: '🔨 Sabotage', tip: 'Damage rival businesses, burn warehouses, and disrupt supply chains' },
            { id: 'political', label: '🏛️ Political', tip: 'Bribe officials, spread rumors, and manipulate kingdom politics' },
            { id: 'assassination', label: '🗡️ Assassination', tip: 'Eliminate rivals and competitors through hired assassins or poison' },
            { id: 'tax_evasion', label: '💰 Tax Evasion', tip: 'Hide income, forge documents, and evade kingdom taxes' },
            { id: 'market', label: '📈 Market', tip: 'Manipulate prices, corner markets, and exploit insider information' },
        ];

        let html = '<div class="schemes-tabs" style="display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap;">';
        for (const tab of tabs) {
            const count = actions.filter(a => a.tab === tab.id).length;
            html += `<button class="btn-tab${UI._schemesTab === tab.id ? ' active' : ''}" `
                + `data-action="switchSchemesTab" data-id="${tab.id}" `
                + `title="${tab.tip}" `
                + `style="font-size:0.85rem;padding:6px 12px;">`
                + `${tab.label} (${count})</button>`;
        }
        html += '</div>';

        // Show locked schemes the player is missing out on
        var _allSchemeInfo = [
            { name: 'Pit Nobles', skill: 'shadow_dealings', tab: 'political' },
            { name: 'Turn Noble Against King', skill: 'kingmaker_skill', tab: 'political' },
            { name: 'Discredit Noble', skill: 'shadow_dealings', skillAlt: 'silver_tongue_dark', tab: 'political' },
            { name: 'Manipulate Noble Vote', skill: 'silver_tongue_dark', skillAlt: 'kingmaker_skill', tab: 'political' },
            { name: 'Expose Noble Secrets', skill: 'dark_connections', skillAlt: 'shadow_dealings', tab: 'political' },
            { name: 'Insider Trading', skill: 'insider_trading', tab: 'market' },
            { name: 'Blackmail', skill: 'dark_connections', tab: 'political' },
            { name: 'Counterfeit Goods', skill: 'master_forger', tab: 'market' },
            { name: 'Sabotage Building', skill: 'sabotage_expert', skillAlt: 'shadow_dealings', tab: 'sabotage' }
        ];
        var _lockedSchemesList = [];
        var _hasSkillCheck = typeof Player !== 'undefined' && Player.hasSkill ? Player.hasSkill : function() { return false; };
        for (var _lsi = 0; _lsi < _allSchemeInfo.length; _lsi++) {
            var _ls = _allSchemeInfo[_lsi];
            if (!_hasSkillCheck(_ls.skill) && (!_ls.skillAlt || !_hasSkillCheck(_ls.skillAlt))) {
                _lockedSchemesList.push(_ls);
            }
        }
        if (_lockedSchemesList.length > 0) {
            html += '<div style="background:rgba(196,78,82,0.06);border:1px solid rgba(196,78,82,0.15);border-radius:6px;padding:6px 10px;margin-bottom:10px;">';
            html += '<div style="font-size:0.78rem;color:#c44e52;margin-bottom:3px;">🔒 <b>' + _lockedSchemesList.length + ' Schemes Locked</b> — missing skills:</div>';
            for (var _lsj = 0; _lsj < _lockedSchemesList.length; _lsj++) {
                var _lsk = _lockedSchemesList[_lsj];
                var _sn = _lsk.skill.replace(/_/g, ' ');
                var _sa = _lsk.skillAlt ? (' or ' + _lsk.skillAlt.replace(/_/g, ' ')) : '';
                html += '<span style="font-size:0.7rem;color:#999;margin-right:8px;">🔒 ' + _lsk.name + ' <span style="color:#c44e52;">(' + _sn + _sa + ')</span></span>';
            }
            html += '</div>';
        }

        // Notoriety meter + stats
        var _notoriety = typeof Player !== 'undefined' ? Math.floor(Player.notoriety || 0) : 0;
        var _notorietyPct = Math.min(100, _notoriety);
        var _notorietyColor = _notoriety >= 80 ? '#c44e52' : _notoriety >= 50 ? '#e8a040' : _notoriety >= 25 ? '#ccb974' : '#55a868';
        var _notorietyLabel = _notoriety >= 80 ? 'WANTED' : _notoriety >= 50 ? 'Notorious' : _notoriety >= 25 ? 'Suspicious' : _notoriety >= 10 ? 'Whispered' : 'Unknown';
        var _investigationRisk = Math.min(95, Math.floor(_notoriety * 0.3 + 2));
        html += '<div style="background:rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.08);border-radius:6px;padding:8px 12px;margin-bottom:10px;">';
        html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">';
        html += '<span style="font-size:0.85rem;color:#ccc;">⚠️ Notoriety: <strong style="color:' + _notorietyColor + ';">' + _notoriety + '</strong> — <span style="color:' + _notorietyColor + ';">' + _notorietyLabel + '</span></span>';
        html += '<span style="font-size:0.75rem;color:#aaa;">🔍 Investigation risk: ' + _investigationRisk + '%</span>';
        html += '</div>';
        html += '<div style="width:100%;height:8px;background:#222;border-radius:4px;overflow:hidden;">';
        html += '<div style="width:' + _notorietyPct + '%;height:100%;background:' + _notorietyColor + ';border-radius:4px;transition:width 0.3s;"></div>';
        html += '</div>';
        html += '<div style="display:flex;gap:12px;margin-top:6px;font-size:0.78rem;color:var(--text-muted);">';
        html += '<span>🗡️ Crimes: ' + (Player.corruptActions || 0) + '</span>';
        html += '<span>🔥 Streak: ' + (Player.corruptionStreak || 0) + '</span>';
        var _activeRackets = 0; try { _activeRackets = Object.keys(Player.state.protectionRackets || {}).length; } catch(e) {}
        var _activeRoutes = 0; try { _activeRoutes = (Player.state.smugglingRoutes || []).length; } catch(e) {}
        var _activeSpies = 0; try { _activeSpies = Object.keys(Player.state.spyNetworks || {}).length; } catch(e) {}
        if (_activeRackets > 0) html += '<span>💪 Rackets: ' + _activeRackets + '</span>';
        if (_activeRoutes > 0) html += '<span>🥷 Routes: ' + _activeRoutes + '</span>';
        if (_activeSpies > 0) html += '<span>🕵️ Spies: ' + _activeSpies + '</span>';
        html += '</div>';
        // Active notoriety reduction indicator
        try {
            var _nr = Player.state.notorietyReduction;
            if (_nr) {
                var _nrDay = typeof Engine !== 'undefined' && Engine.getDay ? Engine.getDay() : 0;
                var _nrDaysLeft = Math.max(0, _nr.endDay - _nrDay);
                var _nrProgress = _nr.endDay > _nr.startDay ? Math.floor(100 * (_nrDay - _nr.startDay) / (_nr.endDay - _nr.startDay)) : 100;
                _nrProgress = Math.min(100, Math.max(0, _nrProgress));
                var _nrTypeLabel = _nr.type === 'lay_low' ? '🕶️ Laying Low' : '🧹 Cleansing Identity';
                html += '<div style="margin-top:6px;padding:4px 8px;background:rgba(85,168,104,0.15);border:1px solid rgba(85,168,104,0.3);border-radius:4px;font-size:0.78rem;color:#88cc88;">';
                html += _nrTypeLabel + ' — ' + _nrDaysLeft + ' days remaining (~' + Math.floor(_nr.dailyReduction * _nrDaysLeft) + ' notoriety left to remove)';
                html += '<div style="width:100%;height:4px;background:#333;border-radius:2px;margin-top:3px;overflow:hidden;">';
                html += '<div style="width:' + _nrProgress + '%;height:100%;background:#55a868;border-radius:2px;"></div></div>';
                html += '</div>';
            }
        } catch(e) {}
        // Double Noble Agent mission tracker
        try {
            var _dna = Player.state.doubleNobleAgent;
            if (_dna) {
                var _dnaDay = typeof Engine !== 'undefined' && Engine.getDay ? Engine.getDay() : 0;
                var _dnaSponsor = typeof Engine !== 'undefined' && Engine.findKingdom ? Engine.findKingdom(_dna.sponsorKingdomId) : null;
                var _dnaTarget = typeof Engine !== 'undefined' && Engine.findKingdom ? Engine.findKingdom(_dna.targetKingdomId) : null;
                html += '<div style="margin-top:6px;padding:6px 8px;background:rgba(196,78,82,0.15);border:1px solid rgba(196,78,82,0.3);border-radius:4px;font-size:0.78rem;">';
                html += '<div style="color:#e8a0a0;font-weight:bold;">🎭 Double Noble Agent — ' + (_dnaSponsor ? _dnaSponsor.name : 'Unknown') + '</div>';
                html += '<div style="color:var(--text-muted);margin:2px 0;">Destabilizing: ' + (_dnaTarget ? _dnaTarget.name : 'Unknown') + ' | Day ' + (_dnaDay - (_dna.startDay || 0)) + ' of mission</div>';
                html += '<div style="margin-top:4px;">';
                for (var _dti = 0; _dti < _dna.tasks.length; _dti++) {
                    var _dt = _dna.tasks[_dti];
                    var _dtIcon = _dt.completed ? '✅' : '⬜';
                    var _dtColor = _dt.completed ? '#55a868' : '#aaa';
                    html += '<div style="font-size:0.75rem;color:' + _dtColor + ';margin:1px 0;">' + _dtIcon + ' ' + _dt.name + '</div>';
                }
                html += '</div>';
                html += '<div style="margin-top:4px;font-size:0.75rem;color:var(--gold);">Progress: ' + (_dna.completed || 0) + '/5 tasks</div>';
                // Progress bar
                var _dnaProgress = Math.floor((_dna.completed || 0) / 5 * 100);
                html += '<div style="width:100%;height:4px;background:#333;border-radius:2px;margin-top:3px;overflow:hidden;">';
                html += '<div style="width:' + _dnaProgress + '%;height:100%;background:#c4a35a;border-radius:2px;"></div></div>';
                html += '</div>';
            }
        } catch(e) {}
        html += '</div>';

        for (const tab of tabs) {
            const tabActions = actions.filter(a => a.tab === tab.id);
            html += `<div id="schemesTab_${tab.id}" style="display:${UI._schemesTab === tab.id ? '' : 'none'}">`;

            if (tabActions.length === 0) {
                html += '<div style="color:var(--text-muted);font-size:0.78rem;padding:12px;">No actions available at this location.</div>';
            }

            for (let ai = 0; ai < tabActions.length; ai++) {
                const a = tabActions[ai];
                const detPct = Math.round(a.detection * 100);
                const detColor = UI.getDetectionColor(a.detection);
                const locked = a.requires && !a.available;
                const opacity = a.available ? '1' : '0.5';

                html += `<div style="border:1px solid var(--border);border-radius:6px;padding:10px;margin-bottom:8px;opacity:${opacity}">`;
                html += `<div style="display:flex;justify-content:space-between;align-items:center;">`;
                html += `<strong style="font-size:0.95rem;">${a.name}</strong>`;
                if (a.detection > 0) {
                    var detSpanId = (a.id === 'steal_goods') ? ` id="stealDetect_${ai}"` : '';
                    html += `<span${detSpanId} style="font-size:0.85rem;color:${detColor};font-weight:bold;">${detPct}% detection</span>`;
                } else {
                    html += '<span style="font-size:0.85rem;color:#55a868;">No detection</span>';
                }
                html += '</div>';
                html += `<div style="font-size:0.85rem;color:var(--text-muted);margin:4px 0;">${a.desc}</div>`;
                html += '<div style="display:flex;gap:12px;font-size:0.85rem;margin:4px 0;">';
                html += `<span>💰 ${a.cost}</span>`;
                html += `<span>🎯 ${a.reward}</span>`;
                html += `<span>⭐ ${a.xp} XP</span>`;
                html += '</div>';
                if (a.requires && !hasSkillForAction(a)) {
                    html += `<div style="font-size:0.85rem;color:#c44e52;">🔒 Requires: ${a.requires}</div>`;
                }

                if (!a.available) {
                    // Show why this action is currently unavailable
                    var reason = a.disabledReason || '';
                    if (!reason) {
                        if (a.requires && !hasSkillForAction(a)) {
                            reason = 'You lack the required skill: ' + a.requires;
                        } else if (typeof a.cost === 'string') {
                            reason = 'You don\u2019t have the required resources (' + a.cost + ')';
                        } else {
                            reason = 'Requirements not met';
                        }
                    }
                    html += `<div style="font-size:0.8rem;color:#c44e52;font-style:italic;margin-top:4px;">\u26D4 ${reason}</div>`;
                }

                if (a.available) {
                    // For actions that need extra input (steal_goods, counterfeit, spread_rumors, etc.)
                    if (a.id === 'steal_goods') {
                        html += buildStealGoodsUI(a, ai);
                    } else if (a.id === 'counterfeit') {
                        html += buildCounterfeitUI(a, ai);
                    } else if (a.id === 'spread_rumors' || a.id === 'frame_competitor' ||
                               a.id === 'assassinate_competitor' || a.id === 'poison' ||
                               a.id === 'plant_evidence') {
                        html += buildTargetSelectUI(a, ai);
                    } else if (a.id === 'bribe_guards') {
                        html += buildBribeGuardsUI(a, ai);
                    } else if (a.id === 'bribe_advisor') {
                        html += buildBribeAdvisorUI(a, ai);
                    } else if (a._needsBuildingSelect) {
                        html += buildBuildingSelectUI(a, ai);
                    } else if (a._needsNobleSelect) {
                        html += buildNobleIntrigueUI(a, ai);
                    } else if (a._needsRoyalOrderConfig) {
                        // v9p33river344: Forge a Royal Order configurator.
                        html += buildForgeRoyalOrderUI(a, ai);
                    } else if (a._needsTreasonConfig) {
                        // v9p33river345: Plant Treasonous Evidence configurator.
                        html += buildPlantTreasonUI(a, ai);
                    } else if (a._needsInciteStrikesConfig) {
                        // v9p33river346: Incite Strikes configurator.
                        html += buildInciteStrikesUI(a, ai);
                    } else if (a._needsSpreadPlagueConfig) {
                        // v9p33river347: Spread Plague configurator.
                        html += buildSpreadPlagueUI(a, ai);
                    } else {
                        html += `<button class="btn-trade sell" style="font-size:0.85rem;margin-top:6px;" `
                            + `data-action="executeScheme" data-id="${a.id}" data-params="${JSON.stringify(a.params).replace(/"/g, '&quot;')}">⚡ Execute</button>`;
                    }
                }
                html += '</div>';
            }
            html += '</div>';
        }

        // Insider info display
        if (Player.insiderInfo && Player.insiderInfo.length > 0) {
            html += '<div style="border-top:1px solid var(--border);margin-top:10px;padding-top:8px;">';
            html += '<h4 style="font-size:0.9rem;margin-bottom:6px;">📋 Insider Information</h4>';
            for (const info of Player.insiderInfo) {
                html += `<div style="font-size:0.85rem;color:var(--text-muted);">• ${info.type.replace(/_/g, ' ')} in ~${Math.max(0, info.effectDay - (Engine.getDay ? Engine.getDay() : 0))} days</div>`;
            }
            html += '</div>';
        }

        // Scheme Log (M4) — recent scheme outcomes
        try {
            var _schemeLog = Player.state._schemeLog || [];
            if (_schemeLog.length > 0) {
                html += '<div style="border-top:1px solid var(--border);margin-top:10px;padding-top:8px;">';
                html += '<h4 style="font-size:0.9rem;margin-bottom:6px;">📜 Scheme Log</h4>';
                var _logStart = Math.max(0, _schemeLog.length - 10);
                for (var _li = _schemeLog.length - 1; _li >= _logStart; _li--) {
                    var _le = _schemeLog[_li];
                    var _leIcon = _le.caught ? '🚨' : _le.success ? '✅' : '❌';
                    var _leColor = _le.caught ? '#c44e52' : _le.success ? '#55a868' : '#aaa';
                    var _leScheme = (_le.scheme || '').replace(/_/g, ' ');
                    html += '<div style="font-size:0.78rem;color:' + _leColor + ';margin:2px 0;padding:3px 6px;background:rgba(0,0,0,0.15);border-radius:3px;">';
                    html += _leIcon + ' Day ' + (_le.day || '?') + ' — <strong>' + escapeHtml(_leScheme) + '</strong> vs ' + escapeHtml(_le.target || '?');
                    html += '</div>';
                }
                html += '</div>';
            }
        } catch(e) {}

        openModal('🗡️ Dark Deeds — Schemes', html);
        // v9p33river348: inline <script>setTimeout(...)</script> tags
        // appended by the four configurator builders do NOT execute when
        // inserted via innerHTML (modern browsers block this for XSS
        // safety). Instead, walk the rendered DOM and trigger the
        // refresh helper for each configurator that's currently mounted.
        // Runs after a microtask so openModal's innerHTML write completes.
        setTimeout(function() {
            try {
                if (UI._froRefresh) {
                    document.querySelectorAll('[id^="froKingdom_"]').forEach(function(el) {
                        var idx = parseInt(el.id.replace('froKingdom_', ''), 10);
                        if (!isNaN(idx)) UI._froRefresh(idx);
                    });
                }
                if (UI._ptRefresh) {
                    document.querySelectorAll('[id^="ptTarget_"]').forEach(function(el) {
                        var idx = parseInt(el.id.replace('ptTarget_', ''), 10);
                        if (!isNaN(idx)) UI._ptRefresh(idx);
                    });
                }
                if (UI._isRefresh) {
                    document.querySelectorAll('[id^="isTown_"]').forEach(function(el) {
                        var idx = parseInt(el.id.replace('isTown_', ''), 10);
                        if (!isNaN(idx)) UI._isRefresh(idx);
                    });
                }
                if (UI._spRefresh) {
                    document.querySelectorAll('[id^="spVariant_"]').forEach(function(el) {
                        var idx = parseInt(el.id.replace('spVariant_', ''), 10);
                        if (!isNaN(idx)) UI._spRefresh(idx);
                    });
                }
            } catch (_e) { /* no-op */ }
        }, 30);
    }

    function hasSkillForAction(action) {
        if (!action.requires) return true;
        // Use requiresSkill array if provided (actual skill IDs)
        if (action.requiresSkill && Array.isArray(action.requiresSkill)) {
            for (var si = 0; si < action.requiresSkill.length; si++) {
                if (Player.hasSkill(action.requiresSkill[si])) return true;
            }
            return false;
        }
        // Fallback: map display name to skill ID
        var skillMap = {
            'Arsonist': 'arsonist_skill',
            'Shadow Dealings': 'shadow_dealings',
            'Discrete': 'discrete',
            'Master Forger': 'master_forger',
            'Dark Connections': 'dark_connections',
            'Political Intrigue': 'political_intrigue',
            'Assassination': 'assassination_skill',
            'Noble Intrigue': 'noble_intrigue',
            'Assassin': 'assassin',
            'Poisoner': 'poisoner',
            'Kingmaker': 'kingmaker_skill',
            'Bribe Expert': 'bribe_expert',
            'Silver Tongue (Dark)': 'silver_tongue_dark'
        };
        if (typeof action.requires === 'string') {
            // v9p33river350: support both 'X or Y' (OR — any matches) AND
            // 'X + Y' (AND — all must match). Previously only split on
            // ' or ', so strings like 'Master Forger + Shadow Dealings'
            // were treated as one impossible skill name and the UI
            // showed a false lock warning for schemes the player
            // actually had access to.
            // Sub-clauses (comma-separated) are also treated as AND.
            function _matchOne(token) {
                token = token.trim();
                if (!token) return true;
                var mapped = skillMap[token];
                if (mapped && Player.hasSkill(mapped)) return true;
                return Player.hasSkill(token);
            }
            // Strip parenthesized clarifications like "(both)" or
            // "(citizenship in both kingdoms)" — they're not skills.
            var cleaned = action.requires.replace(/\([^)]*\)/g, '').trim();
            // Split on ' or ' first into OR groups, then each group on
            // ' + ' (or ',') into AND tokens.
            var orGroups = cleaned.split(/\s+or\s+/i);
            for (var ogi = 0; ogi < orGroups.length; ogi++) {
                var andTokens = orGroups[ogi].split(/\s*\+\s*|\s*,\s*/);
                var allMatch = true;
                for (var ati = 0; ati < andTokens.length; ati++) {
                    if (!_matchOne(andTokens[ati])) { allMatch = false; break; }
                }
                if (allMatch) return true;
            }
            return false;
        }
        return true;
    }

    function buildStealGoodsUI(action, idx) {
        let html = '<div style="display:flex;gap:4px;align-items:center;margin-top:4px;">';
        html += '<select id="stealRes_' + idx + '" style="font-size:0.7rem;padding:2px;flex:1;" onchange="UI.updateStealDetection(' + idx + ')">';
        const town = Engine.findTown(Player.townId);
        if (town && town.market) {
            for (const key in RESOURCE_TYPES) {
                const res = RESOURCE_TYPES[key];
                const avail = town.market.supply[res.id] || 0;
                if (avail > 0) {
                    html += `<option value="${res.id}">${res.icon} ${res.name} (${Math.floor(avail)})</option>`;
                }
            }
        }
        html += '</select>';
        html += `<input type="number" id="stealQty_${idx}" value="5" min="1" max="20" style="width:45px;font-size:0.7rem;padding:2px;" oninput="UI.updateStealDetection(${idx})">`;
        html += `<button class="btn-trade sell" style="font-size:0.7rem;" `
            + `data-action="executeStealGoods" data-id="${idx}">⚡ Steal</button>`;
        html += '</div>';
        // Trigger initial detection update after render
        html += `<script>setTimeout(function(){ if(UI.updateStealDetection) UI.updateStealDetection(${idx}); }, 50);<\/script>`;
        return html;
    }

