    function executeBuildingScheme(actionId, idx, townId) {
        var sel = document.getElementById('bldSelect_' + idx);
        if (!sel) return;
        var buildingIndex = parseInt(sel.value);
        var result = Player.executeCorruptAction(actionId, [buildingIndex, townId]);
        if (result.success) {
            toast(result.message, 'success');
        } else if (result.caught) {
            toast(result.message, 'danger');
        } else {
            toast(result.message, 'warning');
        }
        openSchemesDialog();
    }

    // v9p33river344: configurator UI for the "Forge a Royal Order"
    // scheme. Shows kingdom + order-type drop-downs, plus a third
    // contextual select for the order's sub-target (which good to ban,
    // which prisoner-town, which noble to jail, which enemy kingdom).
    function buildForgeRoyalOrderUI(action, idx) {
        var kingdoms = (Engine.getKingdoms ? Engine.getKingdoms() : []);
        var orderTypes = [
            { id: 'tax_change',       label: 'Adjust Tax Rate (easier — 1500g)', cost: 1500, diff: 'Easier' },
            { id: 'release_prisoner', label: 'Release a Prisoner (easier — 1500g)', cost: 1500, diff: 'Easier' },
            { id: 'good_ban_toggle',  label: 'Ban / Unban a Good (medium — 2000g)', cost: 2000, diff: 'Medium' },
            { id: 'jail_noble',       label: 'Jail a Noble (hard — 3500g)', cost: 3500, diff: 'Hard' },
            { id: 'war_declare',      label: 'Declare War (very hard — 5000g)', cost: 5000, diff: 'Very Hard' },
            { id: 'war_peace',        label: 'Make Peace (very hard — 5000g)', cost: 5000, diff: 'Very Hard' },
        ];
        var pTown = Engine.findTown(Player.townId);
        var html = '<div style="margin-top:8px;padding:8px;background:rgba(80,40,40,0.15);border:1px solid #844;border-radius:4px;">';
        html += '<div style="font-size:0.78rem;color:#caa;margin-bottom:6px;"><strong>📜 Configure Royal Order</strong> — kingdom + decree + target.</div>';

        // Kingdom select
        html += '<div style="display:flex;gap:4px;align-items:center;margin-bottom:4px;flex-wrap:wrap;">';
        html += '<label style="font-size:0.7rem;color:#aaa;min-width:60px;">Kingdom:</label>';
        html += '<select id="froKingdom_' + idx + '" onchange="UI._froRefresh(' + idx + ')" style="font-size:0.75rem;padding:2px;flex:1;min-width:120px;">';
        for (var ki = 0; ki < kingdoms.length; ki++) {
            var k = kingdoms[ki];
            var nobleTag = '';
            if (Player.state.socialRank && (Player.state.socialRank[k.id] || 0) >= 4) nobleTag = ' (noble — easier)';
            var selK = (pTown && pTown.kingdomId === k.id) ? ' selected' : '';
            html += '<option value="' + k.id + '"' + selK + '>' + escapeHtml(k.name) + nobleTag + '</option>';
        }
        html += '</select></div>';

        // Order type select
        html += '<div style="display:flex;gap:4px;align-items:center;margin-bottom:4px;flex-wrap:wrap;">';
        html += '<label style="font-size:0.7rem;color:#aaa;min-width:60px;">Order:</label>';
        html += '<select id="froType_' + idx + '" onchange="UI._froRefresh(' + idx + ')" style="font-size:0.75rem;padding:2px;flex:1;min-width:120px;">';
        for (var oi = 0; oi < orderTypes.length; oi++) {
            var ot = orderTypes[oi];
            html += '<option value="' + ot.id + '">' + escapeHtml(ot.label) + '</option>';
        }
        html += '</select></div>';

        // Sub-target select (populated by client-side selection state).
        html += '<div id="froTarget_' + idx + '" style="margin-bottom:6px;"></div>';

        html += '<button class="btn-trade sell" style="font-size:0.85rem;margin-top:4px;width:100%;" '
              + 'data-action="forgeRoyalOrderSubmit" data-idx="' + idx + '">⚡ Forge & Deliver Royal Order</button>';
        html += '<div style="font-size:0.7rem;color:#aa7;margin-top:4px;font-style:italic;">⚠️ Detection ≈ 2× ordinary forgery. Massive notoriety hit on success. Devastating if caught (heavy fines, 14–30 day jail).</div>';
        html += '</div>';
        // v9p33river348: inline <script> tags don't execute when inserted
        // via innerHTML; the auto-populate refresh is triggered from
        // openSchemesDialog() instead, which walks the DOM after openModal.
        return html;
    }

    // v9p33river344: build the sub-target select (third dropdown)
    // contextual to the chosen order type. Called from a refresh
    // handler so the player sees relevant options without leaving the panel.
    function _buildForgeRoyalOrderTargetSelect(idx, kingdomId, orderType) {
        var kingdom = Engine.findKingdom(kingdomId);
        if (!kingdom) return '<div style="font-size:0.7rem;color:#caa;">No kingdom selected.</div>';
        var html = '<label style="font-size:0.7rem;color:#aaa;display:block;margin-bottom:2px;">Target:</label>';
        if (orderType === 'tax_change') {
            html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;width:100%;">'
                  + '<option value="raise">Raise tax rate by +2%</option>'
                  + '<option value="lower">Lower tax rate by −2%</option>'
                  + '</select>';
        } else if (orderType === 'release_prisoner') {
            // List towns in the target kingdom that have jailed NPCs.
            var w = Engine.getWorld();
            var townOpts = [];
            if (w && w.people && kingdom.territories) {
                var territoryIds = Array.from(kingdom.territories || []);
                var day = Engine.getDay();
                for (var ti = 0; ti < territoryIds.length; ti++) {
                    var t = Engine.findTown(territoryIds[ti]);
                    if (!t) continue;
                    var count = w.people.filter(function(p) {
                        return p.alive && p.townId === t.id && p._jailedUntilDay && p._jailedUntilDay > day;
                    }).length;
                    if (count > 0) townOpts.push({ id: t.id, name: t.name, count: count });
                }
            }
            if (townOpts.length === 0) {
                html += '<div style="font-size:0.7rem;color:#caa;">No towns with jailed prisoners in ' + escapeHtml(kingdom.name) + '.</div>';
            } else {
                html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;width:100%;">';
                for (var to = 0; to < townOpts.length; to++) {
                    html += '<option value="' + townOpts[to].id + '">' + escapeHtml(townOpts[to].name) + ' (' + townOpts[to].count + ' jailed)</option>';
                }
                html += '</select>';
            }
        } else if (orderType === 'good_ban_toggle') {
            // Two sub-selects: good + ban/unban mode.
            html += '<div style="display:flex;gap:4px;">';
            html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;flex:1;">';
            // Show resources — common ones first
            if (typeof RESOURCE_TYPES !== 'undefined') {
                for (var rk in RESOURCE_TYPES) {
                    var r = RESOURCE_TYPES[rk];
                    if (!r || !r.id) continue;
                    html += '<option value="' + r.id + '">' + escapeHtml(r.name || r.id) + '</option>';
                }
            }
            html += '</select>';
            html += '<select id="froSubMode_' + idx + '" style="font-size:0.75rem;padding:2px;">';
            html += '<option value="ban">Ban</option>';
            html += '<option value="unban">Unban</option>';
            html += '</select>';
            html += '</div>';
        } else if (orderType === 'jail_noble') {
            // List nobles in the target kingdom.
            var w2 = Engine.getWorld();
            var nobleOpts = [];
            if (w2 && w2.people) {
                for (var pi = 0; pi < w2.people.length; pi++) {
                    var np = w2.people[pi];
                    if (!np.alive) continue;
                    if (np.kingdomId !== kingdom.id) continue;
                    var isNoble = np.isNoble || np.occupation === 'noble' ||
                                  (np.socialRank && (np.socialRank[kingdom.id] || 0) >= 4);
                    if (!isNoble) continue;
                    if (np.id === kingdom.king) continue; // can't jail the king with this
                    nobleOpts.push(np);
                }
            }
            if (nobleOpts.length === 0) {
                html += '<div style="font-size:0.7rem;color:#caa;">No eligible nobles in ' + escapeHtml(kingdom.name) + '.</div>';
            } else {
                html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;width:100%;">';
                for (var nn = 0; nn < nobleOpts.length; nn++) {
                    var no = nobleOpts[nn];
                    html += '<option value="' + no.id + '">' + escapeHtml((no.firstName || 'Noble') + ' ' + (no.lastName || '')) + '</option>';
                }
                html += '</select>';
            }
        } else if (orderType === 'war_declare') {
            // Pick a non-self kingdom not already at war with the target.
            var allK = Engine.getKingdoms ? Engine.getKingdoms() : [];
            html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;width:100%;">';
            for (var ak = 0; ak < allK.length; ak++) {
                if (allK[ak].id === kingdom.id) continue;
                var atWar = kingdom.atWar && (kingdom.atWar instanceof Set ? kingdom.atWar.has(allK[ak].id) : (Array.isArray(kingdom.atWar) && kingdom.atWar.indexOf(allK[ak].id) >= 0));
                if (atWar) continue;
                html += '<option value="' + allK[ak].id + '">' + escapeHtml(allK[ak].name) + '</option>';
            }
            html += '</select>';
        } else if (orderType === 'war_peace') {
            // Pick a kingdom the target is currently at war with.
            var enemies = [];
            if (kingdom.atWar) {
                var warSet = kingdom.atWar instanceof Set ? Array.from(kingdom.atWar) : (Array.isArray(kingdom.atWar) ? kingdom.atWar : []);
                for (var wi = 0; wi < warSet.length; wi++) {
                    var ek = Engine.findKingdom(warSet[wi]);
                    if (ek) enemies.push(ek);
                }
            }
            if (enemies.length === 0) {
                html += '<div style="font-size:0.7rem;color:#caa;">' + escapeHtml(kingdom.name) + ' is not currently at war.</div>';
            } else {
                html += '<select id="froSub_' + idx + '" style="font-size:0.75rem;padding:2px;width:100%;">';
                for (var ei = 0; ei < enemies.length; ei++) {
                    html += '<option value="' + enemies[ei].id + '">' + escapeHtml(enemies[ei].name) + '</option>';
                }
                html += '</select>';
            }
        }
        return html;
    }

    // v9p33river345: configurator for the "Plant Treasonous Evidence"
    // scheme. Drop-downs: target kingdom (must be at war + player citizen),
    // enemy kingdom (must be at war with target + player citizen), noble
    // (lives in target kingdom + not the king + noble-eligible). All three
    // refresh in sequence; the noble list shows whether nobility access
    // grants the easier detection.
    function buildPlantTreasonUI(action, idx) {
        var kingdoms = (Engine.getKingdoms ? Engine.getKingdoms() : []);
        var citizenKingdoms = kingdoms.filter(function(k) {
            return (Player.state.socialRank && (Player.state.socialRank[k.id] || 0) >= 1);
        });
        var html = '<div style="margin-top:8px;padding:8px;background:rgba(80,30,30,0.18);border:1px solid #844;border-radius:4px;">';
        html += '<div style="font-size:0.78rem;color:#caa;margin-bottom:6px;"><strong>📃 Configure Treason Frame</strong> — target kingdom at war + enemy + noble victim.</div>';

        if (citizenKingdoms.length < 2) {
            html += '<div style="font-size:0.75rem;color:#c44e52;">⛔ You need citizenship in at least TWO kingdoms (the target and a kingdom it\'s at war with).</div>';
            html += '</div>';
            return html;
        }

        // Target kingdom select — only kingdoms at war where player is citizen.
        var validTargets = citizenKingdoms.filter(function(k) {
            var atWarSize = 0;
            if (k.atWar) {
                if (k.atWar instanceof Set) atWarSize = k.atWar.size;
                else if (Array.isArray(k.atWar)) atWarSize = k.atWar.length;
            }
            return atWarSize > 0;
        });
        if (validTargets.length === 0) {
            html += '<div style="font-size:0.75rem;color:#c44e52;">⛔ None of your citizenship kingdoms are currently at war.</div>';
            html += '</div>';
            return html;
        }
        html += '<div style="display:flex;gap:4px;align-items:center;margin-bottom:4px;flex-wrap:wrap;">';
        html += '<label style="font-size:0.7rem;color:#aaa;min-width:70px;">Target:</label>';
        html += '<select id="ptTarget_' + idx + '" onchange="UI._ptRefresh(' + idx + ')" style="font-size:0.75rem;padding:2px;flex:1;min-width:120px;">';
        for (var ti = 0; ti < validTargets.length; ti++) {
            var tk = validTargets[ti];
            var tagT = (Player.state.socialRank && (Player.state.socialRank[tk.id] || 0) >= 4) ? ' (noble — easier)' : '';
            html += '<option value="' + tk.id + '">' + escapeHtml(tk.name) + tagT + '</option>';
        }
        html += '</select></div>';

        // Enemy + noble dropdowns will be built by the refresh handler.
        html += '<div id="ptEnemy_' + idx + '" style="margin-bottom:4px;"></div>';
        html += '<div id="ptNoble_' + idx + '" style="margin-bottom:6px;"></div>';

        html += '<button class="btn-trade sell" style="font-size:0.85rem;margin-top:4px;width:100%;" '
              + 'data-action="plantTreasonSubmit" data-idx="' + idx + '">⚡ Plant Evidence</button>';
        html += '<div style="font-size:0.7rem;color:#aa7;margin-top:4px;font-style:italic;">⚠️ Detection ~70% baseline (nobles in either kingdom: −15%). If caught: 5× cost fine, 60-day jail, reputation devastated.</div>';
        html += '</div>';
        // v9p33river348: refresh is triggered from openSchemesDialog().
        return html;
    }

    // v9p33river345: build the enemy + noble sub-selects for plant_treason.
    function _buildPlantTreasonSubSelects(idx, targetKingdomId) {
        var targetK = Engine.findKingdom(targetKingdomId);
        if (!targetK) return { enemyHtml: '', nobleHtml: '' };
        // Enemies player is also citizen of.
        var atWarList = [];
        if (targetK.atWar) {
            atWarList = targetK.atWar instanceof Set ? Array.from(targetK.atWar) : (Array.isArray(targetK.atWar) ? targetK.atWar : []);
        }
        var enemyOpts = [];
        for (var ei = 0; ei < atWarList.length; ei++) {
            var ek = Engine.findKingdom(atWarList[ei]);
            if (!ek) continue;
            var hasCit = Player.state.socialRank && (Player.state.socialRank[ek.id] || 0) >= 1;
            if (!hasCit) continue;
            enemyOpts.push(ek);
        }
        var enemyHtml = '<div style="display:flex;gap:4px;align-items:center;flex-wrap:wrap;">';
        enemyHtml += '<label style="font-size:0.7rem;color:#aaa;min-width:70px;">Framed enemy:</label>';
        if (enemyOpts.length === 0) {
            enemyHtml += '<div style="font-size:0.7rem;color:#c44e52;flex:1;">⛔ You\'re not a citizen of any kingdom at war with ' + escapeHtml(targetK.name) + '.</div>';
        } else {
            enemyHtml += '<select id="ptEnemySel_' + idx + '" style="font-size:0.75rem;padding:2px;flex:1;min-width:120px;">';
            for (var ej = 0; ej < enemyOpts.length; ej++) {
                var eo = enemyOpts[ej];
                var tagE = (Player.state.socialRank && (Player.state.socialRank[eo.id] || 0) >= 4) ? ' (noble — easier)' : '';
                enemyHtml += '<option value="' + eo.id + '">' + escapeHtml(eo.name) + tagE + '</option>';
            }
            enemyHtml += '</select>';
        }
        enemyHtml += '</div>';

        // Noble list — nobles of target kingdom, not the king.
        var w = Engine.getWorld();
        var nobleOpts = [];
        if (w && w.people) {
            for (var pi = 0; pi < w.people.length; pi++) {
                var np = w.people[pi];
                if (!np.alive) continue;
                if (np.kingdomId !== targetKingdomId) continue;
                if (np.id === targetK.king) continue;
                var isNoble = np.isNoble || np.occupation === 'noble' ||
                              (np.socialRank && (np.socialRank[targetKingdomId] || 0) >= 4);
                if (!isNoble) continue;
                if (np._jailedUntilDay && np._jailedUntilDay > (Engine.getDay ? Engine.getDay() : 0)) continue;
                nobleOpts.push(np);
            }
        }
        var nobleHtml = '<div style="display:flex;gap:4px;align-items:center;flex-wrap:wrap;">';
        nobleHtml += '<label style="font-size:0.7rem;color:#aaa;min-width:70px;">Victim noble:</label>';
        if (nobleOpts.length === 0) {
            nobleHtml += '<div style="font-size:0.7rem;color:#c44e52;flex:1;">⛔ No eligible nobles in ' + escapeHtml(targetK.name) + '.</div>';
        } else {
            nobleHtml += '<select id="ptNobleSel_' + idx + '" style="font-size:0.75rem;padding:2px;flex:1;min-width:120px;">';
            for (var nn = 0; nn < nobleOpts.length; nn++) {
                var no = nobleOpts[nn];
                var nm = (no.firstName || 'Noble') + ' ' + (no.lastName || '');
                nobleHtml += '<option value="' + no.id + '">' + escapeHtml(nm) + '</option>';
            }
            nobleHtml += '</select>';
        }
        nobleHtml += '</div>';

        return { enemyHtml: enemyHtml, nobleHtml: nobleHtml };
    }

    // v9p33river346: configurator for "Incite Strikes". One drop-down
    // (town), with a live cost preview and modifiers display so the
    // player can compare options before paying.
    function buildInciteStrikesUI(action, idx) {
        var towns = (Engine.getTowns ? Engine.getTowns() : []);
        var day = Engine.getDay ? Engine.getDay() : 0;
        var cdMap = (Player.state && Player.state._inciteStrikesCooldowns) || {};

        // Build town option list with computed cost + cooldown status.
        var townOpts = [];
        for (var ti = 0; ti < towns.length; ti++) {
            var t = towns[ti];
            if (!t || !t.kingdomId) continue;
            var prosperity = Math.max(0, Math.min(100, t.prosperity || 50));
            var pop = 0;
            if (Engine.getPeopleInTown) {
                try { pop = (Engine.getPeopleInTown(t.id) || []).length; } catch (_e) { pop = 0; }
            }
            if (!pop) pop = 50;
            var rawCost = 1000 + Math.floor((prosperity / 100) * 4500) + Math.floor((Math.min(200, pop) / 200) * 4500);
            var cost = Math.max(1000, Math.min(10000, rawCost));
            var cdUntil = cdMap[t.id] || 0;
            var cdLeft = Math.max(0, cdUntil - day);
            townOpts.push({ town: t, cost: cost, cdLeft: cdLeft, prosperity: prosperity, pop: pop });
        }
        // Sort by cost ascending so cheapest options surface first.
        townOpts.sort(function(a, b) { return a.cost - b.cost; });

        var html = '<div style="margin-top:8px;padding:8px;background:rgba(60,60,30,0.18);border:1px solid #884;border-radius:4px;">';
        html += '<div style="font-size:0.78rem;color:#caa;margin-bottom:6px;"><strong>🚧 Configure Strike</strong> — bribes scale with prosperity + population. 90-day per-town cooldown on success.</div>';

        if (townOpts.length === 0) {
            html += '<div style="font-size:0.75rem;color:#c44e52;">⛔ No towns available.</div></div>';
            return html;
        }

        html += '<div style="display:flex;gap:4px;align-items:center;margin-bottom:4px;flex-wrap:wrap;">';
        html += '<label style="font-size:0.7rem;color:#aaa;min-width:60px;">Town:</label>';
        html += '<select id="isTown_' + idx + '" onchange="UI._isRefresh(' + idx + ')" style="font-size:0.75rem;padding:2px;flex:1;min-width:140px;">';
        var pTown = Engine.findTown(Player.townId);
        for (var oi = 0; oi < townOpts.length; oi++) {
            var to = townOpts[oi];
            var label = to.town.name + ' — ' + to.cost + 'g';
            var tags = [];
            if (to.town.isCapital) tags.push('CAPITAL');
            if (to.cdLeft > 0) tags.push('on cooldown ' + to.cdLeft + 'd');
            var aff = (Player.gold || 0) >= to.cost;
            if (!aff) tags.push('can\'t afford');
            if (tags.length > 0) label += ' (' + tags.join(', ') + ')';
            var sel = (pTown && pTown.id === to.town.id) ? ' selected' : '';
            // Visually mark unavailable options but still selectable so the
            // player sees why.
            html += '<option value="' + to.town.id + '"' + sel + '>' + escapeHtml(label) + '</option>';
        }
        html += '</select></div>';

        // Cost + modifier preview pane (populated by _isRefresh).
        html += '<div id="isPreview_' + idx + '" style="font-size:0.72rem;color:#aaa;margin-bottom:6px;padding:6px;background:rgba(0,0,0,0.18);border-radius:3px;"></div>';

        html += '<button class="btn-trade sell" style="font-size:0.85rem;margin-top:4px;width:100%;" '
              + 'data-action="inciteStrikesSubmit" data-idx="' + idx + '">⚡ Pay Bribes & Incite Strike</button>';
        html += '<div style="font-size:0.7rem;color:#aa7;margin-top:4px;font-style:italic;">⚠️ Halts ALL non-player buildings in the town for 14 days. Costs 1000–10000g. If caught: 3× cost fine + 20-day jail.</div>';
        html += '</div>';
        // v9p33river348: refresh is triggered from openSchemesDialog().
        return html;
    }

    // v9p33river346: build the live cost/modifier preview for incite_strikes.
    function _buildInciteStrikesPreview(idx, townId) {
        var t = Engine.findTown(townId);
        if (!t) return '<span style="color:#c44e52;">Town not found.</span>';
        var prosperity = Math.max(0, Math.min(100, t.prosperity || 50));
        var pop = 0;
        if (Engine.getPeopleInTown) {
            try { pop = (Engine.getPeopleInTown(t.id) || []).length; } catch (_e) { pop = 0; }
        }
        if (!pop) pop = 50;
        var rawCost = 1000 + Math.floor((prosperity / 100) * 4500) + Math.floor((Math.min(200, pop) / 200) * 4500);
        var cost = Math.max(1000, Math.min(10000, rawCost));
        var sec = Math.max(0, Math.min(100, t.security || 50));
        var secMult = 0.85 + (sec / 100) * 0.30;
        var citizenHere = !!(Player.state.socialRank && t.kingdomId && (Player.state.socialRank[t.kingdomId] || 0) >= 1);

        var lines = [];
        lines.push('💰 Cost: <strong>' + cost + 'g</strong> (prosperity ' + Math.round(prosperity) + '%, pop ~' + pop + ')');
        var detectBits = ['base 50%'];
        if (citizenHere) detectBits.push('+5% (your home kingdom)');
        if (pop > 150) detectBits.push('+5% (large town)');
        detectBits.push('×' + secMult.toFixed(2) + ' (security ' + Math.round(sec) + ')');
        if (t.isCapital) detectBits.push('+15% (CAPITAL — royal scrutiny)');
        lines.push('🚨 Detection: ' + detectBits.join(', '));
        // Live cooldown indicator
        var cdUntil = (Player.state._inciteStrikesCooldowns || {})[t.id] || 0;
        var day = Engine.getDay ? Engine.getDay() : 0;
        if (cdUntil > day) {
            lines.push('<span style="color:#c44e52;">⛔ On cooldown for ' + (cdUntil - day) + ' more days in this town.</span>');
        }
        // Affordability indicator
        if ((Player.gold || 0) < cost) {
            lines.push('<span style="color:#c44e52;">⛔ You only have ' + Math.floor(Player.gold || 0) + 'g.</span>');
        }
        // Building count estimate
        var buildings = Array.isArray(t.buildings) ? t.buildings.filter(function(b) { return b && b.ownerId !== 'player'; }) : [];
        lines.push('🏭 Will halt ~' + buildings.length + ' non-player buildings for 14 days.');
        return lines.join('<br>');
    }

    // v9p33river347: configurator for "Spread Plague". The player can
    // only target the town they're currently standing in (the function
    // enforces this), so there's no town picker — just a variant picker
    // (A/B/C) with cost/material/effect preview.
    function buildSpreadPlagueUI(action, idx) {
        var pTown = Engine.findTown(Player.townId);
        var day = Engine.getDay ? Engine.getDay() : 0;
        var cdMap = (Player.state && Player.state._spreadPlagueCooldowns) || {};
        var cdLeft = pTown ? Math.max(0, (cdMap[pTown.id] || 0) - day) : 0;

        var html = '<div style="margin-top:8px;padding:8px;background:rgba(40,60,30,0.18);border:1px solid #484;border-radius:4px;">';
        html += '<div style="font-size:0.78rem;color:#caa;margin-bottom:6px;"><strong>🦠 Configure Plague Spread</strong> — you must be in the target town. 90-day per-town cooldown after success.</div>';

        if (!pTown) {
            html += '<div style="font-size:0.75rem;color:#c44e52;">⛔ You\'re not in a town.</div></div>';
            return html;
        }

        html += '<div style="font-size:0.75rem;color:#aa9;margin-bottom:6px;">Target: <strong>' + escapeHtml(pTown.name) + '</strong></div>';

        if (cdLeft > 0) {
            html += '<div style="font-size:0.75rem;color:#c44e52;margin-bottom:6px;">⛔ On cooldown here for ' + cdLeft + ' more days.</div></div>';
            return html;
        }

        var variants = [
            { id: 'seed',  label: 'A: Seed Infections — 800g, 1 herb', desc: '2-4 immediate plague infections. Smallest direct hit, fastest setup, cheapest.' },
            { id: 'water', label: 'B: Poison Water Supply — 2500g, 2 herbs + 1 hide', desc: 'Contaminates water for 21 days. 1-2 new infections per health tick. Larger total spread than A.' },
            { id: 'food',  label: 'C: Taint Food Stocks — 5000g, 4 herbs + 2 hide', desc: 'Taints food for 30 days. 2-4 infections per tick + ~10% chance per tick to spill to a connected town via caravan. Largest total spread, hardest to contain.' },
        ];

        html += '<div style="display:flex;gap:4px;align-items:center;margin-bottom:4px;flex-wrap:wrap;">';
        html += '<label style="font-size:0.7rem;color:#aaa;min-width:60px;">Method:</label>';
        html += '<select id="spVariant_' + idx + '" onchange="UI._spRefresh(' + idx + ')" style="font-size:0.75rem;padding:2px;flex:1;min-width:140px;">';
        for (var vi = 0; vi < variants.length; vi++) {
            var v = variants[vi];
            html += '<option value="' + v.id + '">' + escapeHtml(v.label) + '</option>';
        }
        html += '</select></div>';

        html += '<div id="spPreview_' + idx + '" style="font-size:0.72rem;color:#aaa;margin-bottom:6px;padding:6px;background:rgba(0,0,0,0.18);border-radius:3px;"></div>';

        html += '<button class="btn-trade sell" style="font-size:0.85rem;margin-top:4px;width:100%;" '
              + 'data-action="spreadPlagueSubmit" data-idx="' + idx + '">⚡ Plant Contagion</button>';
        html += '<div style="font-size:0.7rem;color:#aa7;margin-top:4px;font-style:italic;">⚠️ Treason-tier if caught: 10× cost fine + 90-day jail + huge notoriety. Karma: 5% per week chance you catch it yourself while in town for the next 14 days.</div>';
        html += '</div>';
        // v9p33river348: refresh is triggered from openSchemesDialog().
        return html;
    }

    function _buildSpreadPlaguePreview(idx, variantId) {
        var pTown = Engine.findTown(Player.townId);
        if (!pTown) return '';
        var variants = {
            seed:  { cost: 800,  herbs: 1, hide: 0, baseDetect: 0.60, effect: '2-4 immediate plague infections; natural contagion takes over.' },
            water: { cost: 2500, herbs: 2, hide: 1, baseDetect: 0.65, effect: '21-day water taint; 1-2 fresh infections every 3-day health tick.' },
            food:  { cost: 5000, herbs: 4, hide: 2, baseDetect: 0.70, effect: '30-day food taint; 2-4 fresh infections every 3-day health tick + ~10% per-tick chance to spread to a connected town.' },
        };
        var v = variants[variantId];
        if (!v) return '';
        var sec = Math.max(0, Math.min(100, pTown.security || 50));
        var secMult = 0.85 + (sec / 100) * 0.30;
        var lines = [];
        lines.push('💰 Cost: <strong>' + v.cost + 'g</strong> + ' + v.herbs + ' herbs' + (v.hide > 0 ? ' + ' + v.hide + ' hide' : ''));
        var heldHerbs = (Player.inventory && Player.inventory.herbs) || 0;
        var heldHide = (Player.inventory && Player.inventory.hide) || 0;
        var canAfford = (Player.gold || 0) >= v.cost && heldHerbs >= v.herbs && heldHide >= v.hide;
        lines.push('📦 You have: ' + Math.floor(Player.gold || 0) + 'g, ' + heldHerbs + ' herbs, ' + heldHide + ' hide ' + (canAfford ? '✅' : '<span style="color:#c44e52;">⛔ insufficient</span>'));
        var detectBits = ['base ' + Math.round(v.baseDetect * 100) + '%'];
        detectBits.push('×' + secMult.toFixed(2) + ' (security ' + Math.round(sec) + ')');
        if (pTown.isCapital) detectBits.push('+15% (CAPITAL)');
        lines.push('🚨 Detection: ' + detectBits.join(', ') + ' + global notoriety scaling');
        lines.push('🦠 Effect: ' + v.effect);
        return lines.join('<br>');
    }

    function buildNobleIntrigueUI(action, idx) {
        var nobles = action._nobles || [];
        var needTwo = action._needsNobleSelect >= 2;
        var html = '<div style="margin-top:6px;">';
        html += '<div style="display:flex;gap:4px;align-items:center;flex-wrap:wrap;">';
        // First noble select
        html += '<select id="nobleA_' + idx + '" style="font-size:0.7rem;padding:2px;flex:1;min-width:100px;">';
        for (var ni = 0; ni < nobles.length; ni++) {
            var n = nobles[ni];
            var nName = (n.firstName || 'Noble') + ' ' + (n.lastName || '');
            var nRank = '';
            if (n.socialRank) {
                var town = Engine.findTown(Player.townId);
                var kId = town ? town.kingdomId : '';
                var rankIdx = n.socialRank[kId] || 0;
                if (rankIdx >= 6) nRank = ' [RA]';
                else if (rankIdx >= 5) nRank = ' [Lord]';
                else if (rankIdx >= 4) nRank = ' [Noble]';
            }
            // Show influence bonus
            var rel = Player.state.relationships[n.id];
            var relLvl = rel ? rel.level : 0;
            var hasLoan = (Player.state._nobleLoans || []).some(function(l) { return l.nobleId === n.id && l.status === 'active'; });
            var hasBm = Player.state.blackmailTargets && Player.state.blackmailTargets[n.id];
            var leverage = '';
            if (hasBm) leverage += '🔗';
            if (hasLoan) leverage += '💰';
            if (relLvl >= 60) leverage += '❤️';
            html += '<option value="' + n.id + '">' + nName.trim() + nRank + (leverage ? ' ' + leverage : '') + '</option>';
        }
        html += '</select>';
        // Second noble select if needed
        if (needTwo) {
            html += '<select id="nobleB_' + idx + '" style="font-size:0.7rem;padding:2px;flex:1;min-width:100px;">';
            for (var ni2 = 0; ni2 < nobles.length; ni2++) {
                var n2 = nobles[ni2];
                var n2Name = (n2.firstName || 'Noble') + ' ' + (n2.lastName || '');
                html += '<option value="' + n2.id + '">' + n2Name.trim() + '</option>';
            }
            html += '</select>';
        }
        html += '<button class="btn-trade sell" style="font-size:0.7rem;" '
            + 'data-action="executeNobleIntrigue" data-id="' + action.id.replace(/'/g, '') + '" data-idx="' + idx + '" data-need-two="' + (needTwo ? 'true' : 'false') + '">⚡ Execute</button>';
        html += '</div>';
        // v9p33river416: direction dropdown for manipulate_vote (support vs oppose)
        if (action.id === 'manipulate_vote') {
            html += '<div style="display:flex;gap:4px;align-items:center;margin-top:3px;">';
            html += '<label style="font-size:0.65rem;color:var(--text-muted);">Direction:</label>';
            html += '<select id="voteDir_' + idx + '" style="font-size:0.7rem;padding:2px;">';
            html += '<option value="yes">✅ Support (vote yes)</option>';
            html += '<option value="no">❌ Oppose (vote no)</option>';
            html += '</select>';
            html += '</div>';
        }
        // Legend
        html += '<div style="font-size:0.65rem;color:var(--text-muted);margin-top:2px;">🔗=blackmailed 💰=indebted ❤️=ally (60+rel) — leverage boosts success</div>';
        html += '</div>';
        return html;
    }

    function executeNobleIntrigue(actionId, idx, needTwo) {
        var selA = document.getElementById('nobleA_' + idx);
        if (!selA) return;
        var nobleAId = selA.value;
        var params = [nobleAId];
        if (needTwo) {
            var selB = document.getElementById('nobleB_' + idx);
            if (!selB) return;
            var nobleBId = selB.value;
            if (nobleAId === nobleBId) { toast('Select two different nobles!', 'warning'); return; }
            params = [nobleAId, nobleBId];
        }
        // v9p33river416: pass vote direction for manipulate_vote
        if (actionId === 'manipulate_vote') {
            var dirSel = document.getElementById('voteDir_' + idx);
            var direction = dirSel ? dirSel.value : 'yes';
            params = [nobleAId, 'general', direction];
        }
        var result = Player.executeCorruptAction(actionId, params);
        if (result.success) {
            toast(result.message, 'success');
        } else if (result.caught) {
            toast(result.message, 'danger');
        } else {
            toast(result.message, 'warning');
        }
        openSchemesDialog();
    }

